# DOMENIA V10.22 FULL RESTORE remote fallback + accounts editing fix
[CmdletBinding()]
param(
    [string]$Server,
    [string]$SearchBase,
    [int]$DefaultLimit = 100,
    [switch]$NoAutoConnect,
    [Alias("MegADSelfTest")][switch]$DomeniaSelfTest,
    [Alias("MegADSelfTestResultPath")][string]$DomeniaSelfTestResultPath
