# ---------------------------------------------------------------------
# Initialisation du host et validation Active Directory.
# Aucun processus PowerShell enfant n est cree par Domenia.
# ---------------------------------------------------------------------
# DOMENIA Reliability R1 - helpers loaded before bootstrap; Windows PowerShell 5.1.
# These functions do not start network requests, background scans or services.
function Write-DomeniaAtomicText {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$LiteralPath,[Parameter(Mandatory)][AllowEmptyString()][string]$Value,[switch]$KeepBackup)
    $full = [IO.Path]::GetFullPath($LiteralPath)
    $dir = [IO.Path]::GetDirectoryName($full)
    if (-not [IO.Directory]::Exists($dir)) { [void][IO.Directory]::CreateDirectory($dir) }
    $temp = Join-Path $dir ('.domenia-' + [guid]::NewGuid().ToString('N') + '.tmp')
    $stream = $null
    try {
        $bytes = [Text.UTF8Encoding]::new($false).GetBytes($Value)
        $stream = [IO.FileStream]::new($temp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
        $stream.Write($bytes,0,$bytes.Length)
        $stream.Flush($true)
        $stream.Dispose(); $stream = $null
        if ([IO.File]::Exists($full)) {
            # Same-directory replacement. Never delete the valid destination first.
            # [NullString]::Value: under 5.1 a plain $null becomes "" for a .NET string parameter and Replace throws.
            if ($KeepBackup) { [IO.File]::Replace($temp,$full,($full + '.bak'),$true) }
            else { [IO.File]::Replace($temp,$full,[NullString]::Value,$true) }
        } else { [IO.File]::Move($temp,$full) }
    }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
        if ([IO.File]::Exists($temp)) { [IO.File]::Delete($temp) }
    }
}

function Protect-DomeniaLogText {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $value = [string]$Text
    # D059: once the closed loader has run, the rule of Access.Model (Protect-DomeniaSecretText) masks first.
    # This function is also called before the modules exist (bootstrap trace): it stays self-sufficient and
    # never fails when the rule is absent.
    if (-not [bool]$script:DomeniaSecretTextRuleReady) {
        $script:DomeniaSecretTextRuleReady = ($null -ne (Get-Command -Name 'Protect-DomeniaSecretText' -CommandType Function -ErrorAction SilentlyContinue))
    }
    if ([bool]$script:DomeniaSecretTextRuleReady) { try { $value = [string](Protect-DomeniaSecretText $value) } catch { } }
    # Defence in depth, not a promise to recognise every possible secret.
    $value = [regex]::Replace($value,'(?i)\b(Bearer|Basic)\s+[A-Za-z0-9_.~+/=-]+','$1 [MASQUE]')
    $value = [regex]::Replace($value,'(?i)\b(password|passwd|pwd|pass|motdepasse|mot\s+de\s+passe|secret|token|authorization|api[_-]?key|apikey|client[_-]?secret)\s*[:=]\s*(?:"[^"]*"|''[^'']*''|[^\s;,]+)','$1=[MASQUE]')
    $value = [regex]::Replace($value,'(?i)("(?:password|passwd|pwd|pass|p|motdepasse|secret|token|api[_-]?key|apikey|client[_-]?secret)"\s*:\s*)("(?:\\.|[^"\\])*"|[^,}\s]+)','$1"[MASQUE]"')
    $value = [regex]::Replace($value,'(?i)(^|\s)(-p|-rp|-pass|-password|-pwd|/p|/rp|/pass|/password|/pwd)(?:\s+|[:=])(?:"[^"]*"|''[^'']*''|\S+)','$1$2 [MASQUE]')
    $value = [regex]::Replace($value,'(?<!\d)(?:\d{6}-){7}\d{6}(?!\d)','[CLE BITLOCKER MASQUEE]')
    try {
        foreach ($row in @($script:SecretRows)) {
            $secret = [string]$row.Value
            if ($secret.Length -ge 4) { $value = $value.Replace($secret,'[SECRET MASQUE]') }
        }
        $clipboard = [string]$script:SecretClipboardValue
        if ($clipboard.Length -ge 4) { $value = $value.Replace($clipboard,'[SECRET MASQUE]') }
    } catch { }
    return $value
}

function ConvertTo-DomeniaSpreadsheetCell {
    param($Value)
    if ($null -eq $Value) { return $null }
    # Preserve numeric values, booleans and dates. Only untrusted text is escaped.
    if ($Value -isnot [string]) { return $Value }
    if ($Value -match '^[\s\p{Cf}]*[=+@\-\uFF1D\uFF0B\uFF0D\uFF20]' -or $Value -match '^[\t\r\n]') {
        return "'" + $Value
    }
    return $Value
}

function ConvertTo-DomeniaSpreadsheetSafeRow {
    [CmdletBinding()]
    param([Parameter(ValueFromPipeline=$true)]$InputObject)
    process {
        if ($null -ne $InputObject) {
            $safe = [ordered]@{}
            foreach ($property in $InputObject.PSObject.Properties) {
                if ($property.MemberType -notin @('NoteProperty','Property','AliasProperty','ScriptProperty')) { continue }
                $name = [string](ConvertTo-DomeniaSpreadsheetCell ([string]$property.Name))
                $safe[$name] = ConvertTo-DomeniaSpreadsheetCell $property.Value
            }
            [pscustomobject]$safe
        }
    }
}

function ConvertTo-DomeniaSqlLikeText {
    param([AllowEmptyString()][string]$Value)
    # SQL quoting and LIKE escaping are independent operations.
    return $Value.Replace('!','!!').Replace('%','!%').Replace('_','!_')
}

function Get-DomeniaScopeKey {
    param([Parameter(Mandatory)][string]$BaseDn)
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($BaseDn.Trim().ToLowerInvariant())
        return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').Substring(0,32).ToLowerInvariant()
    } finally { $sha.Dispose() }
}

function Get-DomeniaStoreBackupDirectory {
    $path = Join-Path ([IO.Path]::GetDirectoryName((Get-DomeniaDatabasePath))) 'Backups'
    if (-not [IO.Directory]::Exists($path)) { [void][IO.Directory]::CreateDirectory($path) }
    return $path
}

function Complete-DomeniaDetachedReadJobs {
    # Never call Dispose/EndInvoke on a running native operation on the UI thread.
    if ($null -eq $script:DetachedReadJobs) { return }
    for ($i = $script:DetachedReadJobs.Count - 1; $i -ge 0; $i--) {
        $job = $script:DetachedReadJobs[$i]
        if ($null -eq $job) { $script:DetachedReadJobs.RemoveAt($i); continue }
        $invokeDone = $false; $stopDone = $true
        try { $invokeDone = [bool]$job.Handle.IsCompleted } catch { }
        try { if ($null -ne $job.StopHandle) { $stopDone = [bool]$job.StopHandle.IsCompleted } } catch { $stopDone = $false }
        if (-not $invokeDone -or -not $stopDone) { continue }
        try { if ($null -ne $job.StopHandle) { $job.PowerShell.EndStop($job.StopHandle) } } catch { }
        try { $discarded = $job.PowerShell.EndInvoke($job.Handle); $discarded = $null } catch { }
        try { $job.PowerShell.Dispose() } catch { }
        try { $job.Runspace.Dispose() } catch { }
        $job.OnSuccess = $null; $job.OnError = $null; $job.CallbackState = $null
        $script:DetachedReadJobs.RemoveAt($i)
    }
}

function Get-DomeniaRuntimeHealthText {
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $process = [Diagnostics.Process]::GetCurrentProcess()
    try {
        $lines.Add("DOMENIA $script:Version / $script:MasterBuild")
        $lines.Add('Genere le ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'))
        $lines.Add('PowerShell : ' + [string]$PSVersionTable.PSVersion + ' ; 64 bits : ' + [Environment]::Is64BitProcess)
        $lines.Add('Memoire privee : ' + [Math]::Round($process.PrivateMemorySize64 / 1MB,1) + ' Mo')
        $lines.Add('Lecture seule : ' + [string]$script:ReadOnlyMode + ' ; etat ecriture : ' + [string]$script:WriteState)
        $lines.Add('Cache actif : ' + (Get-DomeniaDatabasePath))
        $lines.Add('Taches actives : ' + @($script:AsyncJobs.Keys).Count)
        $lines.Add('Lectures en attente de nettoyage : ' + @($script:DetachedReadJobs).Count)
        $lines.Add('')
        foreach ($job in @($script:AsyncJobs.Values) + @($script:DetachedReadJobs)) {
            if ($null -eq $job) { continue }
            $age = [int]((Get-Date) - [datetime]$job.Started).TotalSeconds
            $lines.Add(('{0} | {1}s | ecriture={2} | annulation={3} | {4}' -f $job.OperationId,$age,$job.IsWrite,$job.CancelRequested,$job.CorrelationId))
        }
        $lines.Add('')
        $lines.Add('Une lecture detachee ne renvoie plus de resultat dans le GUI, mais son appel natif peut encore etre actif.')
        $lines.Add('Les taches natives encore actives comptent dans la limite physique de concurrence.')
        return Protect-DomeniaLogText ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    } finally { $process.Dispose() }
}

function Register-DomeniaReliabilityUi {
    $copy = Get-DomeniaControl -Name 'BtnCopyUiLog'
    if ($null -ne $copy) { $copy.Add_Click({
        try {
            $box = Get-DomeniaControl -Name 'TxtUiLog'
            if ($null -ne $box -and -not [string]::IsNullOrWhiteSpace([string]$box.Text)) {
                Set-ClipboardSafe (Protect-DomeniaLogText ([string]$box.Text))
                Set-Status 'Journal copie. Les noms de comptes et de machines ne sont pas anonymises.'
            }
        } catch { Show-ErrorBox $_.Exception.Message }
    }) }
    $health = Get-DomeniaControl -Name 'BtnRuntimeHealth'
    if ($null -ne $health) { $health.Add_Click({
        try { Show-InfoBox -Message 'Etat du moteur DOMENIA' -Details (Get-DomeniaRuntimeHealthText) }
        catch { Show-ErrorBox $_.Exception.Message }
    }) }
    if ($null -ne $script:Window) { $script:Window.Add_Deactivated({
        if ([bool]$script:SecretsVisible) { $script:SecretsVisible = $false; Update-SecretsGrid }
    }) }
}

function Restart-DomeniaSecretLifetime {
    try { if ($null -ne $script:SecretLifetimeTimer) { $script:SecretLifetimeTimer.Stop() } } catch { }
    $seconds = [Math]::Max(30,[Math]::Min(1800,[int](Get-CfgValue 'Security' 'SecretMemorySeconds' 300)))
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromSeconds($seconds)
    $timer.Add_Tick({
        try { Clear-Secrets; Set-Status 'Secrets retires de la vue et references effacees apres expiration.' }
        catch { Write-AppLog 'Expiration des secrets : echec du nettoyage.' 'WARN' }
    })
    $script:SecretLifetimeTimer = $timer
    $timer.Start()
}

function Get-DomeniaSelectedSecretSource {
    $grid = Get-DomeniaControl -Name 'DgSecrets'
    if ($null -eq $grid -or $null -eq $grid.SelectedItem) { return $null }
    $row = $grid.SelectedItem
    if ($null -eq $row.PSObject.Properties['SecretIndex']) { return $null }
    $index = [int]$row.SecretIndex
    if ($index -lt 0 -or $index -ge @($script:SecretRows).Count) { return $null }
    return $script:SecretRows[$index]
}

function Assert-DomeniaWmiReadQuery {
    param([string]$ClassName,[string]$Namespace,[string]$Where,[int]$Limit)
    if ($ClassName -notmatch '^[A-Za-z_][A-Za-z0-9_]{0,127}$') { throw 'Nom de classe WMI invalide.' }
    if ($Namespace -notmatch '^root(?:\\[A-Za-z_][A-Za-z0-9_]*)*$') { throw 'Espace de noms WMI invalide.' }
    if ($ClassName -ieq 'Win32_Product') { throw 'Win32_Product est bloque : sa lecture peut declencher des verifications/reparations MSI. Utilise le panneau Logiciels.' }
    if (([string]$Where).Length -gt 2048 -or ([string]$Where).IndexOf([char]0) -ge 0) { throw 'Filtre WMI trop long ou contenant un caractere nul.' }
    if ($Limit -lt 1 -or $Limit -gt 500) { throw 'La limite WMI doit etre comprise entre 1 et 500.' }
}


function Write-DomeniaBootstrapTrace {
    param([string]$Stage,[string]$Status,[string]$Detail="")
    $Detail = Protect-DomeniaLogText $Detail
    try {
        $base = if ([string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)) { [string]$env:TEMP } else { [string]$env:LOCALAPPDATA }
        $dir = Join-Path $base "DOMENIA\Logs"
        if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
        $path = Join-Path $dir "Domenia-bootstrap.log"
        $clean = (($Detail + "") -replace "[\r\n\t]+"," ").Trim()
        $line = "{0}`tPID={1}`tHOST={2}`t{3}`t{4}`t{5}{6}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"),$PID,[System.Diagnostics.Process]::GetCurrentProcess().ProcessName,$Stage,$Status,$clean,[Environment]::NewLine
        [System.IO.File]::AppendAllText($path,$line,(New-Object System.Text.UTF8Encoding($false)))
    }
    catch { }
}

# DOMENIA reste dans le processus courant. Aucun relancement automatique cache
# n'est effectue depuis PowerShell ISE : cela evite un comportement de type
#  processus parent qui lance PowerShell en arriere-plan , souvent signale
# par les protections heuristiques. Le mode ISE reste reserve au diagnostic.
$isIseHost = $false
try { $isIseHost = ($null -ne $psISE) } catch { }
try { if ([System.Diagnostics.Process]::GetCurrentProcess().ProcessName -ieq "powershell_ise") { $isIseHost = $true } } catch { }
if ($isIseHost) {
    Write-DomeniaBootstrapTrace -Stage "ISE" -Status "WARN" -Detail "Execution directe dans PowerShell ISE ; aucun processus enfant n'est lance. Pour un test fidele, utiliser Windows PowerShell 5.1 en mode STA ou l'EXE compile."
    Write-Warning "DOMENIA s'execute directement dans PowerShell ISE. Pour un test fidele a l'EXE, utilise Windows PowerShell 5.1 avec -STA."
}

Write-DomeniaBootstrapTrace -Stage "Bootstrap" -Status "START" -Detail "Hote principal PID=$PID, processus=$([System.Diagnostics.Process]::GetCurrentProcess().ProcessName), version=$($PSVersionTable.PSVersion), 64bits=$([Environment]::Is64BitProcess)"

Set-StrictMode -Off
$ErrorActionPreference = "Stop"

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Xaml
Add-Type -AssemblyName System.DirectoryServices
Add-Type -AssemblyName System.Windows.Forms

$script:Version = "1.0"
$script:AppName = "Domenia"

$script:EmbeddedDomeniaIconBase64 = @"

"@

function Ensure-DomeniaIcon {
    try {
        $iconPath = Join-Path $script:RootDir "Domenia.ico"
        if (-not (Test-Path -LiteralPath $iconPath -PathType Leaf)) {
            [System.IO.File]::WriteAllBytes(
                $iconPath,
                [Convert]::FromBase64String($script:EmbeddedDomeniaIconBase64)
            )
        }
        return $iconPath
    }
    catch {
        return $null
    }
}


# =====================================================================
# CONTROLE CENTRAL DU GUI
# Default  : fonctionnement normal
# Disabled : controle visible, grise et totalement bloque
# Hidden   : controle masque et retire de la disposition
# Cette table est volontairement placee au debut du script.
# =====================================================================
$script:GuiElementPolicy = [ordered]@{
    # Valeurs possibles : "Default", "Disabled" ou "Hidden".
    # Modifie uniquement la valeur a droite. Le nom doit rester identique au x:Name WPF.
    "TxtLogin" = "Default"
    "PwdLogin" = "Default"
