# Capture des chemins avant toute entree dans une fonction. Dans un EXE PS2EXE,
# PSScriptRoot peut etre vide ou pointer vers un repertoire temporaire.
$script:BootstrapPSCommandPath = [string]$PSCommandPath
$script:BootstrapInvocationPath = [string]$MyInvocation.MyCommand.Path
$script:BootstrapScriptRoot = [string]$PSScriptRoot
$script:IsCompiledExecutable = $false
$script:ResolvedLaunchPath = ""

function Get-RootDir {
    [CmdletBinding()]
    param()

    $candidates = New-Object System.Collections.Generic.List[string]
    $knownHosts = @(
        "powershell", "powershell_ise", "pwsh", "wscript", "cscript",
        "cmd", "conhost", "windowsterminal", "mshta"
    )

    function Add-RootCandidate {
        param([string]$PathValue)
        if ([string]::IsNullOrWhiteSpace($PathValue)) { return }
        try {
            $expanded = [Environment]::ExpandEnvironmentVariables($PathValue.Trim().Trim('"'))
            $directory = ""
            if (Test-Path -LiteralPath $expanded -PathType Container) {
                $directory = $expanded
            }
            elseif (Test-Path -LiteralPath $expanded -PathType Leaf) {
                $directory = Split-Path -Parent $expanded
                if ([string]::IsNullOrWhiteSpace($script:ResolvedLaunchPath)) {
                    $script:ResolvedLaunchPath = [System.IO.Path]::GetFullPath($expanded)
                }
            }
            elseif ([System.IO.Path]::HasExtension($expanded)) {
                $parent = Split-Path -Parent $expanded
                if (-not [string]::IsNullOrWhiteSpace($parent) -and (Test-Path -LiteralPath $parent -PathType Container)) {
                    $directory = $parent
                }
            }
            if (-not [string]::IsNullOrWhiteSpace($directory)) {
                $full = [System.IO.Path]::GetFullPath($directory)
                if (-not $candidates.Contains($full)) { [void]$candidates.Add($full) }
            }
        }
        catch { }
    }

    # Surcharge volontaire, pratique pour les wrappers d entreprise.
    Add-RootCandidate $env:DOMENIA_ROOT
    # Compatibilite : les wrappers d entreprise deployes avant le
    # renommage utilisent encore MEGAD_ROOT.
    Add-RootCandidate $env:MEGAD_ROOT

    $processPath = ""
    $processName = ""
    try {
        $process = [System.Diagnostics.Process]::GetCurrentProcess()
        $processName = ([string]$process.ProcessName).ToLowerInvariant()
        $processPath = [string]$process.MainModule.FileName
    }
    catch { }

    $compiled = (-not [string]::IsNullOrWhiteSpace($processPath)) -and ($knownHosts -notcontains $processName)
    $script:IsCompiledExecutable = $compiled
    if ($compiled) { Add-RootCandidate $processPath }

    try {
        $arg0 = [string]([Environment]::GetCommandLineArgs()[0])
        $argName = ([System.IO.Path]::GetFileNameWithoutExtension($arg0) + "").ToLowerInvariant()
        if (($knownHosts -notcontains $argName) -and ([System.IO.Path]::GetExtension($arg0) -ieq ".exe")) {
            Add-RootCandidate $arg0
        }
    }
    catch { }

    # Mode PS1 classique.
    Add-RootCandidate $script:BootstrapPSCommandPath
    Add-RootCandidate $script:BootstrapInvocationPath
    Add-RootCandidate $script:BootstrapScriptRoot

    # BaseDirectory est fiable pour un EXE, mais souvent faux sous l hote PowerShell.
    if ($compiled) {
        try { Add-RootCandidate ([System.AppContext]::BaseDirectory) } catch { }
        try { Add-RootCandidate ([System.AppDomain]::CurrentDomain.BaseDirectory) } catch { }
    }

    try { Add-RootCandidate ([Environment]::CurrentDirectory) } catch { }
    try { Add-RootCandidate ((Get-Location).ProviderPath) } catch { }

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate -PathType Container) { return $candidate }
    }

    return [System.IO.Path]::GetFullPath(".")
}

$script:RootDir = Get-RootDir
$script:LaunchPath = if (-not [string]::IsNullOrWhiteSpace($script:ResolvedLaunchPath)) { $script:ResolvedLaunchPath } else { $script:BootstrapPSCommandPath }
$script:CfgPath = Join-Path $script:RootDir "Domenia.config.json"
$script:RegPath = "HKCU:\Software\DOMENIA"
$script:AppIconPath = Join-Path $script:RootDir "Domenia.ico"
$script:EmbeddedAppIconBase64 = ""
function Ensure-AppIconFile {
    try {
        if (Test-Path -LiteralPath $script:AppIconPath -PathType Leaf) { return [IO.Path]::GetFullPath($script:AppIconPath) }
        if (-not [string]::IsNullOrWhiteSpace([string]$script:EmbeddedAppIconBase64)) {
            [IO.File]::WriteAllBytes([string]$script:AppIconPath,[Convert]::FromBase64String([string]$script:EmbeddedAppIconBase64))
            if (Test-Path -LiteralPath $script:AppIconPath -PathType Leaf) { return [IO.Path]::GetFullPath($script:AppIconPath) }
        }
    } catch { Write-DomeniaBootstrapTrace -Stage "ICON" -Status "WARN" -Detail $_.Exception.Message }
    return ""
}

function Set-AppWindowIcon {
    param($Window)
    try {
        if ($null -eq $Window) { return }

        $iconPath = Ensure-AppIconFile
        if (-not [string]::IsNullOrWhiteSpace($iconPath)) {
            $stream = [System.IO.File]::OpenRead($iconPath)
            try {
                $decoder = New-Object -TypeName System.Windows.Media.Imaging.IconBitmapDecoder -ArgumentList @(
                    $stream,
                    [System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat,
                    [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                )
                if ($decoder.Frames.Count -gt 0) {
                    $Window.Icon = $decoder.Frames[0]
                    return
                }
            }
            finally { $stream.Dispose() }
        }

        # Dans un EXE, reutilise directement l icone du binaire sans creer
        # de fichier temporaire ni conserver de bloc Base64 dans le script.
        if ($script:IsCompiledExecutable) {
            $exePath = ""
            try { $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
            if (-not [string]::IsNullOrWhiteSpace($exePath) -and (Test-Path -LiteralPath $exePath -PathType Leaf)) {
                Add-Type -AssemblyName System.Drawing -ErrorAction SilentlyContinue
                $nativeIcon = [System.Drawing.Icon]::ExtractAssociatedIcon($exePath)
                if ($null -ne $nativeIcon) {
                    try {
                        $Window.Icon = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon(
                            $nativeIcon.Handle,
                            [System.Windows.Int32Rect]::Empty,
                            [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions()
                        )
                    }
                    finally { $nativeIcon.Dispose() }
                }
            }
        }
    }
    catch { }
}

