                                </StackPanel>
                              </Border>
                              <Border Grid.Column="1" Background="{DynamicResource BgCard}" BorderBrush="{DynamicResource BorderColor}" BorderThickness="1" CornerRadius="14" Padding="12" Margin="8,0,0,0">
