                    </Expander>
                  </StackPanel>
                </ScrollViewer>
              </TabItem>
              <TabItem x:Name="WsSearch" ToolTip="Choisissez une OU à gauche pour filtrer la recherche. Les résultats sont affichés à droite." Header="Rechercher" ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Rechercher dans l’annuaire" AutomationProperties.HelpText="Choisissez une OU à gauche pour filtrer la recherche. Les résultats sont affichés à droite.">
                <Grid Margin="0" x:Name="SearchBrowserLayout" Tag="OU">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="276" MinWidth="230" MaxWidth="420" x:Name="UxOuColumn"/>
                    <ColumnDefinition Width="12"/>
                    <ColumnDefinition Width="*" MinWidth="320"/>
                  </Grid.ColumnDefinitions>
                  <Border Style="{StaticResource Card}" Margin="0" Padding="16" Grid.Column="0" x:Name="SearchOuPanel">
                    <DockPanel LastChildFill="True">
                      <StackPanel DockPanel.Dock="Top" Margin="0,0,0,12">
                        <Grid Margin="0,0,0,6">
                          <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                          </Grid.ColumnDefinitions>
                          <TextBlock Text="Parcourir les OU" FontSize="16" FontWeight="SemiBold" VerticalAlignment="Center"/>
                          <Button Grid.Column="1" x:Name="BtnTreeRefresh" Width="34" MinWidth="34" Height="30" MinHeight="30" Padding="0" Margin="6,0,0,0" ToolTip="Recharge les branches de l’arbre. Le texte de recherche et le filtre OU courant sont conservés." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Actualiser l’arbre" AutomationProperties.HelpText="Recharge les branches de l’arbre. Le texte de recherche et le filtre OU courant sont conservés.">
                            <TextBlock Text="↻" FontFamily="Segoe UI Symbol" FontSize="19" FontWeight="SemiBold" Foreground="{DynamicResource AccentText}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                          </Button>
                        </Grid>
                        <TextBlock Text="La barre du haut cherche partout. Cliquez une OU pour consulter son contenu." FontSize="12" Foreground="{DynamicResource MutedColor}" TextWrapping="Wrap" LineHeight="17" Margin="0,0,0,12"/>
                        <Border x:Name="OuRestoreBanner" Visibility="Collapsed" Background="{DynamicResource BgReadonly}" BorderBrush="{DynamicResource AccentColor}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,12">
                          <StackPanel>
                            <TextBlock x:Name="LblOuRestoreMessage" Text="" TextWrapping="Wrap" FontSize="12" Foreground="{DynamicResource TextColor}"/>
                            <WrapPanel Margin="0,8,0,0">
                              <Button x:Name="BtnOuRestoreRetry" Content="Relire" MinHeight="30" Padding="10,2" Margin="0,0,8,0" ToolTip="Relance une seule fois la restauration de lʼOU mémorisée dans lʼarbre. Aucun autre périmètre nʼest appliqué." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Relire lʼOU mémorisée" AutomationProperties.HelpText="Relance une seule fois la restauration de lʼOU mémorisée dans lʼarbre. Aucun autre périmètre nʼest appliqué."/>
                              <Button x:Name="BtnOuRestoreDismiss" Content="Choisir une autre OU" MinHeight="30" Padding="10,2" ToolTip="Ferme cet avertissement : choisissez une OU dans lʼarbre. Le périmètre actuel nʼest pas modifié." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Choisir une autre OU" AutomationProperties.HelpText="Ferme cet avertissement : choisissez une OU dans lʼarbre. Le périmètre actuel nʼest pas modifié."/>
                            </WrapPanel>
                          </StackPanel>
                        </Border>
                        <Button Content="Tout le domaine" Margin="0,0,0,12" x:Name="BtnSearchAllDomain" ToolTip="Affiche le domaine dans le mode navigation OU. La recherche du bandeau reste indépendante." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Tout le domaine" AutomationProperties.HelpText="Affiche le domaine dans le mode navigation OU. La recherche du bandeau reste indépendante." MinHeight="36"/>
                        <Border Background="{DynamicResource BgReadonly}" CornerRadius="10" Padding="12" Margin="0,0,0,12">
                          <StackPanel>
                            <TextBlock Text="PÉRIMÈTRE SÉLECTIONNÉ" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedColor}" Margin="0,0,0,6"/>
                            <TextBlock x:Name="LblOuScopeName" Text="Tout le domaine" FontSize="14" FontWeight="SemiBold" TextWrapping="Wrap" LineHeight="20"/>
                            <TextBlock x:Name="LblOuScopePath" Text="Choisissez une OU dans l’arbre." FontSize="11.5" Foreground="{DynamicResource MutedColor}" TextTrimming="CharacterEllipsis" Margin="0,4,0,0"/>
                          </StackPanel>
                        </Border>
                        <Button x:Name="BtnSearchInOu" Content="Afficher cette OU" Margin="0,0,0,12" MinHeight="34" ToolTip="Revient à l’OU sélectionnée et réactive ses filtres. Le texte du bandeau n’est pas utilisé." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Afficher l’OU sélectionnée" AutomationProperties.HelpText="Retour au contenu de l’OU, sans perdre la recherche du bandeau."/>
                        <CheckBox x:Name="ChkSubtree" IsChecked="True" ToolTip="Coché : recherche dans la branche et ses sous-branches. Décoché : seulement ses enfants directs." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Inclure les sous-OU" AutomationProperties.HelpText="Coché : recherche dans la branche et ses sous-branches. Décoché : seulement ses enfants directs." Content="Inclure les sous-OU" Margin="0,0,0,10"/>
                        <Expander x:Name="UxOuPathDetails" Header="Voir le chemin LDAP" IsExpanded="False" Margin="0,0,0,4" FontSize="12" Foreground="{DynamicResource MutedColor}" ToolTip="Déplie le DN exact utilisé par la recherche. Cela ne change pas le périmètre et ne lance aucune requête." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Chemin complet de l’OU" AutomationProperties.HelpText="Déplie le DN exact utilisé par la recherche. Cela ne change pas le périmètre et ne lance aucune requête.">
                          <StackPanel Margin="0,8,0,2">
                            <TextBox x:Name="TxtBranchDn" IsReadOnly="True" Background="{DynamicResource BgReadonly}" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" ToolTip="Chemin LDAP complet de la branche sélectionnée. Cette racine est utilisée par la requête AD, pas seulement pour masquer des lignes." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="OU utilisée pour la recherche" AutomationProperties.HelpText="Chemin LDAP complet de la branche sélectionnée. Cette racine est utilisée par la requête AD, pas seulement pour masquer des lignes." MaxHeight="128" MinHeight="64" Padding="10,8" VerticalContentAlignment="Top" Margin="0,0,0,8" HorizontalScrollBarVisibility="Disabled"/>
                            <Button Content="Copier le chemin" MinHeight="32" Margin="0" HorizontalAlignment="Left" Padding="10,4" x:Name="BtnUxCopyOuPath" ToolTip="Copie seulement le DN de l’OU sélectionnée. Ne modifie pas le filtre et ne contacte pas l’annuaire." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Copier le chemin LDAP" AutomationProperties.HelpText="Copie seulement le DN de l’OU sélectionnée. Ne modifie pas le filtre et ne contacte pas l’annuaire."/>
                          </StackPanel>
                        </Expander>
                      </StackPanel>
                      <TextBlock x:Name="LblTreeStatus" Text="Arbre pret." Foreground="{DynamicResource MutedColor}" FontSize="11" TextWrapping="NoWrap" Margin="0,10,0,0" DockPanel.Dock="Bottom" TextTrimming="CharacterEllipsis" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}"/>
                      <TreeView x:Name="TvDirectory" ScrollViewer.HorizontalScrollBarVisibility="Auto" ScrollViewer.VerticalScrollBarVisibility="Auto" ToolTip="Développez les sous-OU ou cliquez une branche pour afficher son contenu. Le texte de la recherche globale reste conservé mais ne filtre pas cette navigation." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Arbre des OU et conteneurs" AutomationProperties.HelpText="Développez les sous-OU ou cliquez une branche pour afficher son contenu. Le texte de la recherche globale reste conservé mais ne filtre pas cette navigation."/>
                    </DockPanel>
                  </Border>
                  <GridSplitter Grid.Column="1" Width="6" HorizontalAlignment="Center" VerticalAlignment="Stretch" ResizeDirection="Columns" ResizeBehavior="PreviousAndNext" ShowsPreview="True" Background="{DynamicResource SplitterBg}" Cursor="SizeWE" x:Name="SearchOuSplitter" ToolTip="Faites glisser pour ajuster la largeur de l’arbre et des résultats." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Largeur de l’arbre des OU" AutomationProperties.HelpText="Faites glisser pour ajuster la largeur de l’arbre et des résultats."/>
                  <Grid Margin="0" Grid.Column="2">
                    <Grid.RowDefinitions>
                      <RowDefinition Height="Auto"/>
                      <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <Border Style="{StaticResource Card}" Grid.Row="0" Margin="0,0,0,12" Padding="16">
                      <StackPanel>
                        <TextBlock Text="Périmètre des résultats" FontSize="16" FontWeight="SemiBold" Margin="0,0,0,10"/>
                        <TextBlock Text="Dans : tout le domaine | Sous-OU incluses" TextWrapping="NoWrap" Margin="0,0,0,4" Foreground="{DynamicResource AccentText}" FontSize="12" x:Name="LblSearchScope" TextTrimming="CharacterEllipsis"/>
                        <TextBlock x:Name="LblSearchHint" Text="" Height="18" Margin="0,0,0,8" FontSize="11.5" Foreground="{DynamicResource MutedColor}" TextWrapping="NoWrap" TextTrimming="CharacterEllipsis"/>
                        <WrapPanel>
                          <StackPanel Width="148" Margin="0,0,12,8"><StackPanel.Style><Style TargetType="StackPanel"><Style.Triggers><DataTrigger Binding="{Binding Tag, ElementName=SearchBrowserLayout}" Value="Global"><Setter Property="IsEnabled" Value="False"/></DataTrigger></Style.Triggers></Style></StackPanel.Style>
                            <TextBlock Text="Type d’objet" Margin="0,0,0,6" FontSize="12" FontWeight="SemiBold"/>
                            <ComboBox x:Name="CmbGlobalType" Margin="0" SelectedIndex="0" ToolTip="Filtre la requête AD dans l’OU sélectionnée : tous, utilisateurs, machines, groupes, ou OU et conteneurs." MinWidth="0" ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Type d’objet" AutomationProperties.HelpText="Filtre la requête AD dans l’OU sélectionnée : tous, utilisateurs, machines, groupes, ou OU et conteneurs." MinHeight="36">
                              <ComboBoxItem Content="Tous"/>
                              <ComboBoxItem Content="Utilisateurs"/>
                              <ComboBoxItem Content="Machines"/>
                              <ComboBoxItem Content="Groupes"/>
                              <ComboBoxItem Content="OU et conteneurs"/>
                            </ComboBox>
                          </StackPanel>
                          <StackPanel Width="138" Margin="0,0,12,8"><StackPanel.Style><Style TargetType="StackPanel"><Style.Triggers><DataTrigger Binding="{Binding Tag, ElementName=SearchBrowserLayout}" Value="Global"><Setter Property="IsEnabled" Value="False"/></DataTrigger></Style.Triggers></Style></StackPanel.Style>
                            <TextBlock Text="Présence réseau" Margin="0,0,0,6" FontSize="12" FontWeight="SemiBold"/>
                            <ComboBox x:Name="CmbPresenceFilter" Margin="0" SelectedIndex="0" ToolTip="Filtre les observations réseau mémorisées en mode OU. Sans réponse au ping ne prouve pas que Windows est éteint. Aucun ping collectif." MinWidth="0" ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Présence réseau" AutomationProperties.HelpText="Filtre les observations réseau mémorisées en mode OU. Sans réponse au ping ne prouve pas que Windows est éteint. Aucun ping collectif." MinHeight="36">
                              <ComboBoxItem Content="Tous"/>
                              <ComboBoxItem Content="En ligne"/>
                              <ComboBoxItem Content="Sans réponse au ping"/>
                              <ComboBoxItem Content="Non vérifié"/>
                              <ComboBoxItem Content="Erreur de ping"/>
                            </ComboBox>
                          </StackPanel>
                          <StackPanel Width="90" Margin="0,0,12,8">
                            <TextBlock Text="Limite" Margin="0,0,0,6" FontSize="12" FontWeight="SemiBold" TextWrapping="NoWrap"/>
                            <TextBox x:Name="TxtGlobalLimit" Text="100" ToolTip="Nombre maximum de resultats affiches." Margin="0" MinWidth="0" ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Maximum de résultats" AutomationProperties.HelpText="Nombre maximum de resultats affiches." MinHeight="36"/>
                          </StackPanel>
                          <StackPanel Width="250" Margin="0,0,12,8">
                            <TextBlock Text="Vue de travail" Margin="0,0,0,6" FontSize="12" FontWeight="SemiBold"/>
                            <DockPanel>
                              <Button x:Name="BtnWorkView" DockPanel.Dock="Right" Content="Afficher" Margin="6,0,0,0" MinHeight="36" Padding="10,4" ToolTip="Lance la vue choisie en lecture seule : un filtre prêt à lʼemploi, sans compte, droit ni mode écriture. Le texte de recherche de ce mode est vidé." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Afficher la vue de travail" AutomationProperties.HelpText="Lance la vue choisie en lecture seule : un filtre prêt à lʼemploi, sans compte, droit ni mode écriture. Le texte de recherche de ce mode est vidé."/>
                              <ComboBox x:Name="CmbWorkView" MinWidth="0" MinHeight="36" ToolTip="Vues prêtes à lʼemploi : comptes expirants ou désactivés, objets modifiés récemment, postes dʼune OU ou sans connexion. Le choix seul ne lance rien." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Vue de travail" AutomationProperties.HelpText="Vues prêtes à lʼemploi : comptes expirants ou désactivés, objets modifiés récemment, postes dʼune OU ou sans connexion. Le choix seul ne lance rien."/>
                            </DockPanel>
                          </StackPanel>
                          <StackPanel Margin="0,0,0,8">
                            <TextBlock Text="Actions" Margin="0,0,0,6" FontSize="12" FontWeight="SemiBold"/>
                            <WrapPanel Margin="0">
                              <Button x:Name="BtnLoadBranch" Content="Actualiser" ToolTip="Actualise le mode affiché : recherche globale sans filtres, ou contenu de l’OU avec ses filtres." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Actualiser les résultats" AutomationProperties.HelpText="Actualise le mode affiché : recherche globale sans filtres, ou contenu de l’OU avec ses filtres." Margin="0,0,8,0" MinHeight="36"/>
