                                <DataGridTemplateColumn.CellTemplate><DataTemplate><TextBlock Text="{Binding SessionDisplay}" ToolTip="{Binding SessionDetail}" TextTrimming="CharacterEllipsis" VerticalAlignment="Center"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
                              </DataGridTemplateColumn>
                              <DataGridTextColumn Header="Vérification utilisateur" Binding="{Binding SessionState}" Width="175"/>
                              <DataGridTextColumn Header="Fraîcheur AD" Binding="{Binding DirectoryState}" Width="135"/>
                              <DataGridTextColumn Header="Login" Binding="{Binding Login}" Width="150"/>
                              <DataGridTextColumn Header="UPN / DNS" Binding="{Binding UPN}" Width="235"/>
                              <DataGridTextColumn Header="Association mémorisée" SortMemberPath="Association" Binding="{Binding Association}" Width="230">
                                <DataGridTextColumn.HeaderStyle><Style TargetType="DataGridColumnHeader" BasedOn="{StaticResource {x:Type DataGridColumnHeader}}"><Setter Property="ToolTip" Value="Utilisateur associé au poste ou postes associés au compte. Cette information mémorisée ne prouve pas une session actuelle."/></Style></DataGridTextColumn.HeaderStyle>
                              </DataGridTextColumn>
                              <DataGridTextColumn Header="Source lien" SortMemberPath="LinkSource" Binding="{Binding LinkSource}" Width="155">
                                <DataGridTextColumn.HeaderStyle><Style TargetType="DataGridColumnHeader" BasedOn="{StaticResource {x:Type DataGridColumnHeader}}"><Setter Property="ToolTip" Value="Origine de l’association mémorisée : console observée, import ou saisie manuelle."/></Style></DataGridTextColumn.HeaderStyle>
                              </DataGridTextColumn>
                              <DataGridTextColumn Header="Qualification" SortMemberPath="LinkConfidence" Binding="{Binding LinkConfidence}" Width="90">
                                <DataGridTextColumn.HeaderStyle><Style TargetType="DataGridColumnHeader" BasedOn="{StaticResource {x:Type DataGridColumnHeader}}"><Setter Property="ToolTip" Value="Badge de la source du lien (Declare, Observe, Importe, Indice, Contradictoire) ; ce nʼest jamais une probabilité de connexion actuelle."/></Style></DataGridTextColumn.HeaderStyle>
                              </DataGridTextColumn>
                              <DataGridTemplateColumn Header="Présence réseau" SortMemberPath="Presence" Width="175">
                                <DataGridTemplateColumn.CellTemplate><DataTemplate><TextBlock Text="{Binding Presence}" ToolTip="{Binding PresenceDetail}" TextTrimming="CharacterEllipsis" VerticalAlignment="Center"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
                              </DataGridTemplateColumn>
                              <DataGridTextColumn Header="Etat" Binding="{Binding State}" Width="120"/>
                              <DataGridTextColumn Header="OS" Binding="{Binding OS}" Width="180"/>
                              <DataGridTextColumn Header="Derniere connexion" Binding="{Binding LastLogon}" Width="145"/>
                              <DataGridTextColumn Header="Mail" Binding="{Binding Mail}" Width="220"/>
                              <DataGridTextColumn Header="Description" Binding="{Binding Description}" Width="250"/>
                              <DataGridTextColumn Header="Modifie" Binding="{Binding Changed}" Width="145"/>
                              <DataGridTextColumn Header="Chemin complet" Binding="{Binding DN}" Width="520"/>
                            </DataGrid.Columns>
                          </DataGrid>
                          <Border Style="{StaticResource UxEmptyResults}" x:Name="UxSearchEmpty">
                            <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" MaxWidth="360">
                              <Path Data="M17,17 L23,23 M20,11 A9,9 0 1 1 2,11 A9,9 0 1 1 20,11" Width="38" Height="38" Stretch="Uniform" Stroke="{DynamicResource AccentText}" StrokeThickness="1.7" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Margin="0,0,0,15" IsHitTestVisible="False" HorizontalAlignment="Center"/>
                              <TextBlock Text="Aucun résultat affiché" FontSize="19" FontWeight="SemiBold" TextAlignment="Center"/>
                              <TextBlock Text="Sélectionnez une OU à gauche ou saisissez un nom en haut. Les filtres OU, type et sous-OU se combinent. Une liste vide ne prouve pas une absence dans AD." TextWrapping="Wrap" TextAlignment="Center" Foreground="{DynamicResource MutedColor}" Margin="0,8,0,0"/>
                            </StackPanel>
                          </Border>
                        <Border Background="{DynamicResource BgCard}" Margin="2,36,18,18" IsHitTestVisible="False">
<Border.Style><Style TargetType="Border"><Setter Property="Visibility" Value="Collapsed"/><Style.Triggers><DataTrigger Binding="{Binding HasItems, ElementName=DgObjects}" Value="False"><Setter Property="Visibility" Value="Visible"/></DataTrigger></Style.Triggers></Style></Border.Style>
<StackPanel VerticalAlignment="Center" Margin="24"><TextBlock Text="Aucune ligne à afficher" FontSize="18" FontWeight="SemiBold" TextAlignment="Center" TextWrapping="Wrap"/><TextBlock Text="Lancez une recherche, choisissez une OU ou ajustez les filtres. Le filtre local ne parcourt pas le domaine." TextAlignment="Center" TextWrapping="Wrap" Foreground="{DynamicResource MutedColor}" Margin="0,8,0,0"/></StackPanel></Border></Grid>
                      </Grid>
                    </Border>
