                          <DataGrid.Columns>
                            <DataGridTextColumn Header="Controle" Binding="{Binding Check}" Width="210"/>
                            <DataGridTextColumn Header="Etat" Binding="{Binding Status}" Width="95"/>
                            <DataGridTextColumn Header="Methode" Binding="{Binding Method}" Width="120"/>
