function Save-DomeniaUserContact {
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur") { return }
        $changes = @(
            New-DomeniaAttributeChange "streetAddress" ([string]$script:Ctrl["TxtUserStreet"].Text)
            New-DomeniaAttributeChange "l" ([string]$script:Ctrl["TxtUserCity"].Text)
            New-DomeniaAttributeChange "st" ([string]$script:Ctrl["TxtUserState2"].Text)
            New-DomeniaAttributeChange "postalCode" ([string]$script:Ctrl["TxtUserPostalCode"].Text)
            New-DomeniaAttributeChange "co" ([string]$script:Ctrl["TxtUserCountry"].Text)
            New-DomeniaAttributeChange "homePhone" ([string]$script:Ctrl["TxtUserHomePhone"].Text)
            New-DomeniaAttributeChange "mobile" ([string]$script:Ctrl["TxtUserMobile"].Text)
            New-DomeniaAttributeChange "facsimileTelephoneNumber" ([string]$script:Ctrl["TxtUserFax"].Text)
            New-DomeniaAttributeChange "ipPhone" ([string]$script:Ctrl["TxtUserIpPhone"].Text)
            New-DomeniaAttributeChange "wWWHomePage" ([string]$script:Ctrl["TxtUserWebPage"].Text)
            New-DomeniaAttributeChange "employeeID" ([string]$script:Ctrl["TxtUserEmployeeId"].Text)
            New-DomeniaAttributeChange "profilePath" ([string]$script:Ctrl["TxtUserProfilePath"].Text)
            New-DomeniaAttributeChange "scriptPath" ([string]$script:Ctrl["TxtUserScriptPath"].Text)
            New-DomeniaAttributeChange "homeDirectory" ([string]$script:Ctrl["TxtUserHomeDirectory"].Text)
            New-DomeniaAttributeChange "homeDrive" ([string]$script:Ctrl["TxtUserHomeDrive"].Text)
            New-DomeniaAttributeChange "userWorkstations" ([string]$script:Ctrl["TxtUserWorkstations"].Text)
        )
        Start-DomeniaAttributeWrite -OperationName "Enregistrement coordonnees" -Changes $changes -Capability "Edit" -DisableControls @("BtnUserSaveContact")
    }
    catch { Show-ErrorBox "Erreur preparation coordonnees : $($_.Exception.Message)" }
}

function Fill-ComputerObject {
    param($Entry)
    Sync-DomeniaResultRowFromEntry -Entry $Entry -Type "Machine"
    $uac = Get-DeProp $Entry "userAccountControl" $null
    $script:Ctrl["TxtCompName"].Text = [string](Get-DeProp $Entry "name" "")
    $script:Ctrl["TxtCompDns"].Text = [string](Get-DeProp $Entry "dNSHostName" "")
    $script:Ctrl["TxtCompOs"].Text = [string](Get-DeProp $Entry "operatingSystem" "")
    $script:Ctrl["TxtCompOsVersion"].Text = [string](Get-DeProp $Entry "operatingSystemVersion" "")
    $script:Ctrl["TxtCompDescription"].Text = [string](Get-DeProp $Entry "description" "")
    $script:Ctrl["TxtCompLocation"].Text = [string](Get-DeProp $Entry "location" "")
    $script:Ctrl["TxtCompManagedBy"].Text = [string](Get-DeProp $Entry "managedBy" "")
    $script:Ctrl["TxtCompState"].Text = Get-UacStatusLabel $uac 0
    $script:Ctrl["TxtCompLastLogon"].Text = Convert-FileTimeLabel (Get-DeProp $Entry "lastLogonTimestamp" 0)
    $script:Ctrl["TxtCompUac"].Text = [string]$uac
    $script:Ctrl["TxtCompNewName"].Text = [string](Get-DeProp $Entry "name" "")
    try {
        $presenceName = [string](Get-DeProp $Entry "name" "")
        $presenceDns = [string](Get-DeProp $Entry "dNSHostName" "")
        if (-not $script:RenderingObjectWithoutProbes) { Start-DomeniaSelectedMachinePresence -Name $presenceName -DnsName $presenceDns }
        else {
            $row=Get-DomeniaSelectedGridRow
            $state=if($null -ne $row -and [string]$row.DN -ieq [string]$script:SelectedObject.DN -and $row.Presence){[string]$row.Presence}else{'Non verifie'}
            Set-DomeniaPresenceText -Name 'TxtCompPresence' -State $state
            Update-DomeniaObjectPresence -State $state -Target $presenceDns
        }
    }
    catch {
        Set-DomeniaPresenceText -Name "TxtCompPresence" -State "Inconnu"
        Update-DomeniaObjectPresence -State "Inconnu" -Target ""
    }
    $script:Ctrl["LstMemberOf"].Items.Clear()
    foreach ($g in (Get-DePropAll $Entry "memberOf")) { [void]$script:Ctrl["LstMemberOf"].Items.Add([string]$g) }
    $script:Ctrl["LblMemberOf"].Text = "$($script:Ctrl["LstMemberOf"].Items.Count) groupe(s)"
    try {
        $computerForLink = Normalize-LinkComputer ([string](Get-DeProp $Entry "name" ""))
        $link = Get-ExistingLinkForComputer -Computer $computerForLink
        if ($null -ne $link) {
            $script:Ctrl["TxtCompLinkedUser"].Text = [string]$link.UserLogin
            # D043: badge of the link (relation model), never a percentage.
            $confidenceText = $(if($null -ne (Get-Command Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)){(Get-DomeniaLinkQualification $link).Suffix}elseif($null -ne $link.PSObject.Properties['Confidence'] -and -not [string]::IsNullOrWhiteSpace([string]$link.Confidence)){'  confiance '+[string]$link.Confidence+'%'}else{''})
            $script:Ctrl["TxtCompLinkSource"].Text = "$($link.Source)$confidenceText  $($link.When)"
        } else {
            $script:Ctrl["TxtCompLinkedUser"].Text = "Non detecte"
            $script:Ctrl["TxtCompLinkSource"].Text = "Detection manuelle disponible"
        }
    } catch {
        $script:Ctrl["TxtCompLinkedUser"].Text = "Indisponible"
        $script:Ctrl["TxtCompLinkSource"].Text = $_.Exception.Message
    }
    try {
        $targetPc = Get-CurrentSelectedComputerName
        if (-not $script:RenderingObjectWithoutProbes -and -not [string]::IsNullOrWhiteSpace($targetPc)) {
            # Detection automatique a chaque nouvelle machine reellement chargee.
            # ProbeOncePerSession et la presence d'un lien existant evitent les
            # repetitions inutiles.
            Start-ComputerUserLinkProbe -Computer $targetPc
        }
    }
    catch { Write-AppLog "Probe automatique user-machine non lance : $($_.Exception.Message)" "WARN" }
}

