function Filter-AdCmdletReference {
    try {
        $filter = ""
        if ($script:Ctrl.ContainsKey("TxtCmdletFilter")) { $filter = ([string]$script:Ctrl["TxtCmdletFilter"].Text).Trim() }
        $module = "Tous les modules"
        if ($script:Ctrl.ContainsKey("CmbCmdletModule") -and $null -ne $script:Ctrl["CmbCmdletModule"].SelectedItem) { $module = [string]$script:Ctrl["CmbCmdletModule"].SelectedItem.Content }
        $rows = @($script:CmdletReferenceRows)
        if ($module -ne "Tous les modules") { $rows = @($rows | Where-Object { [string]$_.Module -ieq $module }) }
        if (-not [string]::IsNullOrWhiteSpace($filter)) {
            $needle = $filter.ToLowerInvariant()
            $rows = @($rows | Where-Object { (([string]$_.Name + " " + [string]$_.Module + " " + [string]$_.Parameters + " " + [string]$_.Synopsis).ToLowerInvariant()).Contains($needle) })
        }
        [void](Set-DomeniaItemsSource -Name "DgCmdlets" -Rows $rows)
        if ($script:Ctrl.ContainsKey("LblCmdletCount")) { $script:Ctrl["LblCmdletCount"].Text = "$($rows.Count) commande(s)" }
    } catch { Set-Status "Filtre cmdlets : $($_.Exception.Message)" "ERROR" }
}
function Clear-AdCmdletFilter {
    try {
        $script:Ctrl["TxtCmdletFilter"].Text = ""
        $script:Ctrl["CmbCmdletModule"].SelectedIndex = 0
        Filter-AdCmdletReference
    } catch { }
}
function Start-SelectedCmdletHelp {
    try {
        $row = $script:Ctrl["DgCmdlets"].SelectedItem
        if ($null -eq $row -or [string]::IsNullOrWhiteSpace([string]$row.Name)) { return }
        $name = [string]$row.Name
        $module = [string]$row.Module
        $script:Ctrl["TxtCmdletHelp"].Text = "Chargement de l aide de $name..."
        $code = @'
function Join-HelpText {
    param($Value)
    $parts = New-Object Collections.ArrayList
    foreach($item in @($Value)) {
        if ($null -eq $item) { continue }
        $text = ""
        try { if ($null -ne $item.PSObject.Properties["Text"]) { $text=[string]$item.Text } else { $text=[string]$item } } catch { $text=[string]$item }
        if (-not [string]::IsNullOrWhiteSpace($text)) { [void]$parts.Add($text.Trim()) }
    }
    return (@($parts) -join [Environment]::NewLine)
}
$module=[string]$Payload.Module
$name=[string]$Payload.Name
if($module -eq "ActiveDirectory"){ if(-not (Import-WAdModule $Context)){ throw "Module ActiveDirectory absent." } }
elseif($module -eq "LAPS"){ Import-Module LAPS -ErrorAction Stop }
$cmd=Get-Command -Name $name -Module $module -ErrorAction Stop | Select-Object -First 1
$help=Get-Help -Name $name -Full -ErrorAction SilentlyContinue
$syntax=(Get-Command -Name $name -Syntax -ErrorAction SilentlyContinue | Out-String -Width 220).Trim()
if([string]::IsNullOrWhiteSpace($syntax)){ $syntax=$name }
$synopsis=""; $description=""; $examples=""; $notes=""; $links=""
if($null -ne $help){
    try{$synopsis=[string]$help.Synopsis}catch{}
    try{$description=Join-HelpText $help.Description}catch{}
    try{
        $exampleLines=New-Object Collections.ArrayList
        foreach($ex in @($help.Examples.Example)){
            $title=[string]$ex.Title; $codeText=[string]$ex.Code; $remarks=Join-HelpText $ex.Remarks
            [void]$exampleLines.Add((($title,$codeText,$remarks | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) -join [Environment]::NewLine))
        }
        $examples=@($exampleLines) -join ([Environment]::NewLine+[Environment]::NewLine)
    }catch{}
    try{$notes=Join-HelpText $help.AlertSet.Alert}catch{}
    try{$links=(@($help.RelatedLinks.NavigationLink | ForEach-Object { ([string]$_.LinkText + " " + [string]$_.Uri).Trim() }) -join [Environment]::NewLine)}catch{}
}
$helpParamDescriptions=@{}
try {
    foreach($hp in @($help.Parameters.Parameter)){
        $hpName=[string]$hp.Name
        if(-not [string]::IsNullOrWhiteSpace($hpName)){ $helpParamDescriptions[$hpName]=Join-HelpText $hp.Description }
    }
} catch {}
$paramLines=New-Object Collections.ArrayList
foreach($p in @($cmd.Parameters.Values | Sort-Object Name)){
    $aliases=@($p.Aliases) -join ", "
    $sets=New-Object Collections.ArrayList
    foreach($kv in @($p.ParameterSets.GetEnumerator())){
        $meta=$kv.Value
        [void]$sets.Add(("{0}: obligatoire={1}, position={2}, pipeline={3}, propriete pipeline={4}, reste={5}" -f $kv.Key,$meta.IsMandatory,$meta.Position,$meta.ValueFromPipeline,$meta.ValueFromPipelineByPropertyName,$meta.ValueFromRemainingArguments))
    }
    $line="-{0} <{1}>" -f $p.Name,$p.ParameterType.Name
    if(-not [string]::IsNullOrWhiteSpace($aliases)){ $line += " | alias: $aliases" }
    if($sets.Count -gt 0){ $line += [Environment]::NewLine + "    " + (@($sets) -join ([Environment]::NewLine+"    ")) }
    $descriptionText=""
    if($helpParamDescriptions.ContainsKey([string]$p.Name)){ $descriptionText=[string]$helpParamDescriptions[[string]$p.Name] }
    if(-not [string]::IsNullOrWhiteSpace($descriptionText)){ $line += [Environment]::NewLine + "    Description : " + $descriptionText }
    [void]$paramLines.Add($line)
}
$fullHelp=""
try{$fullHelp=($help | Out-String -Width 220).Trim()}catch{}
$sections=New-Object Collections.ArrayList
[void]$sections.Add("COMMANDE`r`n$name")
[void]$sections.Add("MODULE / TYPE`r`n$module / $($cmd.CommandType)")
[void]$sections.Add("SYNOPSIS`r`n$(if([string]::IsNullOrWhiteSpace($synopsis)){"Aucun synopsis installe."}else{$synopsis})")
[void]$sections.Add("DESCRIPTION`r`n$(if([string]::IsNullOrWhiteSpace($description)){"Description locale indisponible. Utilise Update-Help pour installer l aide complete."}else{$description})")
[void]$sections.Add("SYNTAXE`r`n$syntax")
[void]$sections.Add("PARAMETRES`r`n$(@($paramLines) -join ([Environment]::NewLine+[Environment]::NewLine))")
if(-not [string]::IsNullOrWhiteSpace($examples)){[void]$sections.Add("EXEMPLES`r`n$examples")}
if(-not [string]::IsNullOrWhiteSpace($notes)){[void]$sections.Add("NOTES`r`n$notes")}
if(-not [string]::IsNullOrWhiteSpace($links)){[void]$sections.Add("LIENS`r`n$links")}
if(-not [string]::IsNullOrWhiteSpace($fullHelp)){[void]$sections.Add("AIDE POWERSHELL COMPLETE`r`n$fullHelp")}
[pscustomobject]@{Name=$name;Module=$module;Syntax=$syntax;Text=(@($sections) -join ("`r`n`r`n"+('-'*78)+"`r`n`r`n"))}
'@
        Start-UiTask -Name "Aide cmdlet $name" -OperationId "CmdletHelp" -Code $code -Payload ([pscustomobject]@{Name=$name;Module=$module}) -ReplaceKey "cmdlethelp" -DisableControls @("BtnCopyCmdletSyntax","BtnCopyCmdletHelp") -TimeoutSeconds 35 -StatusText "Chargement de l aide $name..." -OnSuccess {
            param($result)
            $script:CurrentCmdletSyntax = [string]$result.Syntax
            $script:CurrentCmdletHelp = [string]$result.Text
            $script:Ctrl["TxtCmdletHelp"].Text = [string]$result.Text
            Set-Status "Aide de $([string]$result.Name) chargee."
        } -OnError {
            param($message)
            $script:CurrentCmdletSyntax = ""
            $script:CurrentCmdletHelp = "Erreur : $message"
            $script:Ctrl["TxtCmdletHelp"].Text = $script:CurrentCmdletHelp
            Set-Status "Aide cmdlet : $message" "ERROR"
        } | Out-Null
    } catch { Set-Status "Aide cmdlet : $($_.Exception.Message)" "ERROR" }
}

function Toggle-PasswordBox {
    param([string]$PwdName, [string]$TxtName, [string]$BtnName, [string]$FlagName)
    $flag = [bool](Get-Variable -Name $FlagName -Scope Script -ValueOnly -ErrorAction SilentlyContinue)
    if ($flag) {
        $script:Ctrl[$PwdName].Password = $script:Ctrl[$TxtName].Text
        $script:Ctrl[$TxtName].Visibility = [System.Windows.Visibility]::Collapsed
        $script:Ctrl[$PwdName].Visibility = [System.Windows.Visibility]::Visible
        $script:Ctrl[$BtnName].Content = "👁"
        $script:Ctrl[$BtnName].ToolTip = "Afficher le mot de passe."
        Set-Variable -Name $FlagName -Scope Script -Value $false
    }
    else {
        $script:Ctrl[$TxtName].Text = $script:Ctrl[$PwdName].Password
        $script:Ctrl[$PwdName].Visibility = [System.Windows.Visibility]::Collapsed
        $script:Ctrl[$TxtName].Visibility = [System.Windows.Visibility]::Visible
        $script:Ctrl[$BtnName].Content = "🙈"
        $script:Ctrl[$BtnName].ToolTip = "Masquer le mot de passe."
        Set-Variable -Name $FlagName -Scope Script -Value $true
    }
}



