function Export-CurrentResults {
    try {
        $grid=Get-DomeniaControl 'DgObjects'
        if($null -eq $grid){return}
        $rows = @(Get-DomeniaExperienceExportRows -VisibleRows @(Get-DomeniaExperienceVisibleRows) -SelectedRows @($grid.SelectedItems))
        if ($rows.Count -eq 0) { Set-Status "Aucun resultat a exporter." "WARN"; return }
        $dlg = New-DomeniaFileRequest -Mode Save
        $dlg.Filter = "CSV UTF-8 (*.csv)|*.csv"
        $dlg.FileName = "Domenia-AD-$((Get-Date).ToString("yyyyMMdd-HHmmss")).csv"
        if ($dlg.ShowDialog()) { $rows | ConvertTo-DomeniaSpreadsheetSafeRow | Export-Csv -LiteralPath $dlg.FileName -NoTypeInformation -Encoding UTF8; Set-Status "$($rows.Count) ligne(s) exportee(s)." }
    } catch { Show-ErrorBox "Erreur export : $($_.Exception.Message)" }
}

function Clear-DomeniaSecretClipboard {
    param([switch]$Silent)
    try { if ($null -ne $script:SecretClipboardTimer) { $script:SecretClipboardTimer.Stop() } } catch { }
    $script:SecretClipboardTimer = $null
    $expected = [string]$script:SecretClipboardValue
    try {
        if (-not [string]::IsNullOrEmpty($expected) -and [System.Windows.Clipboard]::ContainsText() -and [System.Windows.Clipboard]::GetText() -ceq $expected) {
            [System.Windows.Clipboard]::Clear()
            if (-not $Silent) { Set-Status "Presse-papiers secret efface." }
        }
    }
    catch { try { Write-AppLog "Effacement du presse-papiers secret impossible : $($_.Exception.Message)" "WARN" } catch { } }
    finally { $script:SecretClipboardValue = "" }
}

function Clear-Secrets {
    Clear-DomeniaSecretClipboard -Silent
    $script:ActiveSecretRequestId = ''
    try { if ($null -ne $script:SecretLifetimeTimer) { $script:SecretLifetimeTimer.Stop() } } catch { }
    try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { }
    foreach ($row in @($script:SecretRows)) { try { $row.Value = '' } catch { } }
    $script:SecretRows = @()
    $script:SecretsVisible = $false
    $script:RevealedSecretIndex = -1
    $script:BitLockerKeyList = @()
    $script:BitLockerKeyContext = $null
    try { $script:Ctrl["DgSecrets"].ItemsSource = $null; $script:Ctrl["BtnToggleSecrets"].Content = "Afficher les secrets"; $script:Ctrl["LblSecretsStatus"].Text = "Aucun secret conserve en memoire." } catch { }
    try { Update-DomeniaSecretActionUi } catch { }
}

function Update-SecretsGrid {
    $rows = New-Object 'System.Collections.Generic.List[object]'
    $index = 0
    # D059: with a single reveal, only the row chosen by an explicit gesture is shown ($script:RevealedSecretIndex);
    # -1 keeps the previous whole-grid reveal (Features.SecretSingleCopy = false).
    $revealedIndex = -1
    if ($null -ne $script:RevealedSecretIndex) { $revealedIndex = [int]$script:RevealedSecretIndex }
    foreach ($r in @($script:SecretRows)) {
        $hasValue = -not [string]::IsNullOrWhiteSpace([string]$r.Value)
        $shown = ($script:SecretsVisible -and ($revealedIndex -lt 0 -or $revealedIndex -eq $index))
        $display = if (-not $hasValue) { '' } elseif ($shown) { [string]$r.Value } else { '********' }
        $rows.Add([pscustomobject]@{ Kind=$r.Kind; Account=$r.Account; DisplayValue=$display; Timestamp=$r.Timestamp; Source=$r.Source; Detail=$r.Detail; SecretIndex=$index; HasValue=$hasValue })
        $index++
    }
    [void](Set-DomeniaItemsSource -Name 'DgSecrets' -Rows $rows.ToArray())
    $toggle = Get-DomeniaControl -Name 'BtnToggleSecrets'
    if ($null -ne $toggle) { $toggle.Content = if ($script:SecretsVisible) { 'Masquer les secrets' } else { 'Afficher les secrets' } }
    try { Update-DomeniaSecretActionUi } catch { }
}

function Test-DomeniaSecretCallbackCurrent {
    param($State)
    if ($null -eq $State -or $null -eq $script:SelectedObject) { return $false }
    if ([string]$script:ActiveSecretRequestId -ne [string]$State.RequestId) { return $false }
    if ([int64]$script:SelectedObjectGeneration -ne [int64]$State.Generation) { return $false }
    if ([string]$script:SelectedObject.DN -ine [string]$State.DN) { return $false }
    $currentGuid = ""
    try { $currentGuid = [string]$script:SelectedObject.Safety.Guid } catch { }
    if (-not [string]::IsNullOrWhiteSpace([string]$State.ObjectGuid) -and $currentGuid -ine [string]$State.ObjectGuid) { return $false }
    return $true
}

function Clear-DomeniaSecretResultValues {
    param($Result)
    try { foreach ($row in @($Result.Rows)) { if ($null -ne $row.PSObject.Properties["Value"]) { $row.Value = "" } } } catch { }
}

function Stop-DomeniaSecretReadTasks {
    foreach ($taskId in @($script:AsyncJobs.Keys)) {
        $job = $script:AsyncJobs[$taskId]
        if ($null -ne $job -and [string]$job.ReplaceKey -eq "secrets" -and -not [bool]$job.IsWrite) {
            try { Request-UiTaskStop -Id ([string]$taskId) -Silent -Force -Superseded } catch { }
        }
    }
    $script:ActiveSecretRequestId = ""
}

function Complete-DomeniaSecretLoadUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows","Mode","Success")
    if ($null -eq $effective) { Fail-DomeniaSecretLoadUi -Message "Le worker n'a retourne aucun resultat exploitable." -State $State; return }
    if (-not (Test-DomeniaSecretCallbackCurrent -State $State)) {
        Clear-DomeniaSecretResultValues -Result $effective
        Write-AppLog "Resultat secret obsolete ignore pour $([string]$State.DN), requete $([string]$State.RequestId)." "WARN"
        return
    }
    $script:ActiveSecretRequestId = ""
    # D057: LAPS read and LAPS decryption are distinct. The worker returns metadata (Meta) without any password;
    # ConvertTo-DomeniaLapsView turns it into an explained state and facts (source, publication, expiration, decryptor).
    $lapsView = $null
    if ($effective.Mode -eq "LAPS" -and $null -ne $effective.PSObject.Properties["Meta"] -and $null -ne $effective.Meta) {
        try { $lapsView = ConvertTo-DomeniaLapsView -Result $effective.Meta } catch { $lapsView = $null }
    }
    $lapsFacts = ""
    if ($null -ne $lapsView) { $lapsFacts = ((@($lapsView.Facts) | ForEach-Object { [string]$_.Fait + " : " + [string]$_.Valeur }) -join " ; ") }
    if (-not [bool]$effective.Success) {
        Clear-DomeniaSecretResultValues -Result $effective
        $detail = if (-not [string]::IsNullOrWhiteSpace([string]$effective.ErrorMessage)) { [string]$effective.ErrorMessage } else { "Aucune valeur secrete lisible n'a ete retournee." }
        $errorKind = ""
        try { $errorKind = [string]$effective.ErrorKind } catch { }
        if($errorKind -eq 'LogonFailure' -and $null -ne $script:AccessState){$scope=if($State.Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'};$script:AccessState.Faults[$scope]=$true}
        # A decryption refusal is not a read refusal: the resource is not marked denied, no fault is recorded and
        # BitLocker is untouched. Only a refused READ marks this resource for this computer.
        $readDenied = ($errorKind -eq "AccessDenied" -and ($null -eq $lapsView -or [string]$lapsView.State -eq 'ReadDenied'))
        if ($readDenied) {
            Set-DomeniaSecretDenied -Mode ([string]$State.Mode) -DN ([string]$State.DN)
            Write-AppLog "Lecture $($State.Mode) refusee. L autre ressource reste disponible." 'WARN'
        }
        Update-SecretsGrid
        if ($null -ne $lapsView) {
            $script:Ctrl["LblSecretsStatus"].Text = ("Lecture LAPS : " + [string]$lapsView.Message + $(if ($lapsFacts) { " " + $lapsFacts + "." } else { "" }))
        }
        else { $script:Ctrl["LblSecretsStatus"].Text = "Lecture impossible : $detail" }
        $op=if($State.Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
        $offerValue = if ($errorKind -eq 'AccessDenied') { 'Acces refuse. '+$detail } else { $detail }
        $offerPossible = ($errorKind -eq 'NoReadableValue' -or ($null -ne $lapsView -and [string]$lapsView.State -eq 'Unconfirmed'))
        $offered = $false
        if ($null -eq $lapsView -or [bool]$lapsView.OfferOtherAccount -or $errorKind -eq 'LogonFailure') {
            $offered=Request-DomeniaAccessRecovery -Operation "Lecture $($State.Mode)" -ErrorValue $offerValue -OperationId $op -DN ([string]$State.DN) -Interactive:([int]$State.RetryAttempt -eq 0) -Possible:$offerPossible
        }
        [void](Show-DomeniaOperationError -Operation "Lecture $($State.Mode)" -ErrorRecordOrException $detail -NoPopup:$offered)
        return
    }
    Set-DomeniaSecretDenied -Mode ([string]$State.Mode) -DN ([string]$State.DN) -Denied $false
    foreach($oldSecret in @($script:SecretRows)){try{$oldSecret.Value=''}catch{}}
    $script:SecretRows = @($effective.Rows | Where-Object { $null -ne $_ })
    $script:SecretsVisible = $false
    Restart-DomeniaSecretLifetime
    Update-SecretsGrid
    $count = @($script:SecretRows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Value) }).Count
    $extra = ""
    if ($effective.Mode -eq "LAPS" -and $null -ne $effective.PSObject.Properties["ModuleState"]) { $extra = " Module : $([string]$effective.ModuleState)  $([string]$effective.ModuleDetail)" }
    if ($effective.Mode -eq "BitLocker" -and $null -ne $effective.PSObject.Properties["RecoveryObjectsFound"] -and [int]$effective.RecoveryObjectsFound -eq 0) {
        $script:Ctrl["LblSecretsStatus"].Text = "Aucun objet de recuperation visible avec ce compte. L absence de resultat ne prouve pas l absence de cle."
        Set-Status "BitLocker : aucun objet de recuperation visible avec ce compte." "WARN"
        [void](Request-DomeniaAccessRecovery -Operation 'Lecture BitLocker' -ErrorValue 'Aucune cle visible.' -OperationId 'ReadBitLocker' -DN ([string]$State.DN) -Possible -Interactive:([int]$State.RetryAttempt -eq 0))
        try { [void](Save-DomeniaSecretIndexEntry -Computer (Get-CurrentSelectedComputerName) -BitLockerKeys 0 -Verdict "aucune cle visible avec ce compte") } catch { }
        return
    }
    $lapsSuffix = if ($lapsFacts) { " " + $lapsFacts + "." } else { "" }
    $script:Ctrl["LblSecretsStatus"].Text = "$count valeur(s) $($effective.Mode) chargee(s). Valeurs masquees et uniquement en memoire.$extra$lapsSuffix"
    try {
        $verdict = "lisible par ton compte"
        if ($count -eq 0) { $verdict = "present mais non lisible par ton compte" }
        [void](Update-DomeniaSecretIndexFromRows -Computer (Get-CurrentSelectedComputerName) -Mode ([string]$effective.Mode) -Rows $script:SecretRows -Verdict $verdict)
    }
    catch { }

    try {
        $secretGrid = Get-DomeniaControl -Name "DgSecrets"
        if ($null -ne $secretGrid -and $secretGrid.Items.Count -gt 0) {
            $firstReadable = $secretGrid.Items | Where-Object {
                $null -ne $_ -and [bool]$_.HasValue
            } | Select-Object -First 1
            if ($null -ne $firstReadable) {
                $secretGrid.SelectedItem = $firstReadable
                try { $secretGrid.ScrollIntoView($firstReadable) } catch { }
            }
        }
        Update-DomeniaSecretActionUi
    }
    catch { }

    Set-Status "$($effective.Mode) : $count valeur(s) lisible(s).$extra"
}

function Fail-DomeniaSecretLoadUi {
    param($Message,$State)
    if ($null -ne $State -and -not (Test-DomeniaSecretCallbackCurrent -State $State)) { return }
    $script:ActiveSecretRequestId = ''
    $mode=if($null -ne $State){[string]$State.Mode}else{'LAPS'}
    $kind=Get-DomeniaAccessFailureKind $Message
    # D057: an explicit decryption refusal does not mark the LAPS read as denied for this computer.
    $decryptOnly=$false
    try{$decryptOnly=([string](Get-DomeniaErrorDecision -Structured (Get-DomeniaStructuredError $Message) -Text ([string]$Message)).Category -eq 'DecryptionDenied')}catch{}
    if($kind -eq 'AccessDenied' -and -not $decryptOnly -and $null -ne $State){Set-DomeniaSecretDenied -Mode $mode -DN ([string]$State.DN)}
    Update-SecretsGrid
    [void](Set-DomeniaControlText 'LblSecretsStatus' ("Lecture $mode non confirmee : "+$Message))
    $op=if($mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
    $offered=Request-DomeniaAccessRecovery -Operation "Lecture $mode" -ErrorValue $Message -OperationId $op -DN ([string]$State.DN) -Interactive:([int]$State.RetryAttempt -eq 0)
    [void](Show-DomeniaOperationError -Operation "Lecture $mode" -ErrorRecordOrException $Message -NoPopup:$offered)
}

function Start-LoadComputerSecrets {
    param([ValidateSet("BitLocker","LAPS")][string]$Mode,[ValidateRange(0,1)][int]$RetryAttempt=0)
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") { Set-Status "Selectionne une machine." "WARN"; return }
        $opScope=if($Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
        # D055: the current Windows token, or the account already chosen for this resource, is used without any
        # prompt. Another account is asked only after a refusal for this resource (Get-DomeniaOperationAuthNeed).
        $authNeed = Get-DomeniaSecretIdentityReason -Mode $Mode
        if ([bool]$authNeed.Prompt) {
            [void](Request-DomeniaAccessRecovery -Operation "Lecture $Mode" -ErrorValue 'Acces refuse avec ce compte.' -OperationId $opScope -DN ([string]$script:SelectedObject.DN) -Interactive -Force)
            return
        }
        if ($script:CurrentCapabilities.ContainsKey("Secrets") -and $script:CurrentCapabilities["Secrets"] -eq "Refuse") {
            Write-AppLog "L'estimation ACL indique un refus pour la lecture des secrets sur $([string]$script:SelectedObject.DN). Tentative reelle maintenue ; le DC ou Windows LAPS reste l'autorite finale." "WARN"
            Set-Status "ACL estimee defavorable ; tentative reelle de lecture maintenue et controlee par AD." "WARN"
        }
        $dn = [string]$script:SelectedObject.DN
        $name = [string]$script:Ctrl["TxtCompName"].Text
        $secretOperationId = if ($Mode -eq "BitLocker") { "ReadBitLocker" } else { "ReadLaps" }
        $successHandler = "Complete-DomeniaSecretLoadUi"
        if ($Mode -eq "BitLocker" -and (Test-DomeniaBitLockerKeySelection)) {
            # D058 (Features.BitLockerKeySelection): metadata first. No recovery password is requested here;
            # one key is read later, on an explicit reveal or copy of the chosen line (ReadBitLockerKey).
            $code = Get-DomeniaBitLockerListWorkerCode
            $secretOperationId = "ReadBitLockerList"
            $successHandler = "Complete-DomeniaBitLockerListUi"
        }
        elseif ($Mode -eq "BitLocker") {
            $code = @'
$s = New-WSearcher $Context ([string]$Payload.DN) "(objectClass=msFVE-RecoveryInformation)" @("name","distinguishedName","msFVE-RecoveryPassword","msFVE-RecoveryGuid","whenCreated","whenChanged") "OneLevel" 0
$rows = New-Object Collections.ArrayList
$objectCount = 0
foreach ($r in @($s.FindAll())) {
    $objectCount++
    $p = $r.Properties
    $value = [string](Get-WPropFirst $p "msfve-recoverypassword" "")
    $rid = Convert-WGuid (Get-WPropFirst $p "msfve-recoveryguid" "")
    if ([string]::IsNullOrWhiteSpace($rid)) { $rid = [string](Get-WPropFirst $p "name" "") }
    if (-not [string]::IsNullOrWhiteSpace($value)) { [void]$rows.Add([pscustomobject]@{ Kind="BitLocker"; Account=$rid; Value=$value; Timestamp=(Convert-WDate (Get-WPropFirst $p "whencreated" "")); Source="msFVE-RecoveryInformation"; Detail=[string](Get-WPropFirst $p "distinguishedname" "") }) }
}
$readableCount = @($rows).Count
$success = ($objectCount -eq 0 -or $readableCount -gt 0)
$errorMessage = if ($objectCount -gt 0 -and $readableCount -eq 0) { "Des objets de recuperation existent, mais aucune cle n'est lisible avec le compte utilise." } else { "" }
[pscustomobject]@{ Rows=@($rows); Mode="BitLocker"; Success=$success; ErrorKind=$(if($success){""}else{"AccessDenied"}); ErrorMessage=$errorMessage; RecoveryObjectsFound=$objectCount; ReadableValues=$readableCount }
'@
        }
        else {
            $code = @'
$de=$null
$rows=[Collections.Generic.List[object]]::new()
$errorKind='';$errorMessage='';$moduleState='Non requis';$moduleDetail=''
$lapsSource='';$lapsPublished=$false;$lapsExpiration='';$lapsAccount='';$lapsDecryptor='';$decryptStatus='NotAttempted'
try{
    $de=New-WEntry $Context ([string]$Payload.DN)
    $p=Get-WAllProperties -Entry $de -PropertyNames @('ms-Mcs-AdmPwd','ms-Mcs-AdmPwdExpirationTime','msLAPS-Password','msLAPS-PasswordExpirationTime','msLAPS-EncryptedPassword')
    function FirstValue([string]$name){foreach($key in @($p.Keys)){if([string]$key -ieq $name){$v=@($p[$key]);if($v.Count){return $v[0]}}};return ''}
    function ExpirationUtc($value){$i=Convert-WLargeInteger $value;if($i -le 0 -or $i -eq 9223372036854775807){return ''};try{return [DateTime]::FromFileTimeUtc($i).ToString('o')}catch{return ''}}
    # Metadata only (D057): source, publication and expiration. No password value ever goes into Meta.
    $legacyExpiry=FirstValue 'ms-Mcs-AdmPwdExpirationTime'
    if($legacyExpiry){$lapsSource='LegacyLaps';$lapsPublished=$true;$lapsExpiration=ExpirationUtc $legacyExpiry}
    $modernExpiry=FirstValue 'msLAPS-PasswordExpirationTime'
    if($modernExpiry){$lapsSource='WindowsLaps';$lapsPublished=$true;$lapsExpiration=ExpirationUtc $modernExpiry}
    if(FirstValue 'msLAPS-EncryptedPassword'){$lapsSource='WindowsLaps';$lapsPublished=$true}
    $legacy=FirstValue 'ms-Mcs-AdmPwd'
    if($legacy){$lapsSource='LegacyLaps';$lapsPublished=$true;$decryptStatus='NotEncrypted';$lapsAccount='Administrateur local';$rows.Add([pscustomobject]@{Kind='LAPS historique';Account='Administrateur local';Value=$legacy;Timestamp=(Convert-WFileTime (FirstValue 'ms-Mcs-AdmPwdExpirationTime'));Source='ms-Mcs-AdmPwd';Detail='Lecture attribut LAPS historique'})}
    $modern=FirstValue 'msLAPS-Password'
    if($modern){
        try{$o=$modern|ConvertFrom-Json -ErrorAction Stop;if([string]$o.p){$lapsSource='WindowsLaps';$lapsPublished=$true;$decryptStatus='NotEncrypted';$lapsAccount=[string]$o.n;$rows.Add([pscustomobject]@{Kind='Windows LAPS';Account=[string]$o.n;Value=[string]$o.p;Timestamp=(Convert-WFileTime (FirstValue 'msLAPS-PasswordExpirationTime'));Source='msLAPS-Password';Detail='Lecture attribut Windows LAPS'})}}
        catch{throw 'Attribut LAPS JSON invalide. Son contenu brut n est pas journalise.'}
    }
    if(-not $rows.Count){
        $cmd=Get-Command Get-LapsADPassword -ErrorAction SilentlyContinue
        if($null -eq $cmd){
            try{Import-Module LAPS -ErrorAction Stop;$cmd=Get-Command Get-LapsADPassword -ErrorAction Stop}
            catch{$errorKind='ModuleMissing';throw 'Module Windows LAPS absent. Aucun decryptage possible. Le changement de compte ne remplace pas ce module.'}
        }
        $params=@{Identity=[string]$Payload.DN;ErrorAction='Stop'}
        if($cmd.Parameters.ContainsKey('AsPlainText')){$params.AsPlainText=$true}
        if($cmd.Parameters.ContainsKey('DomainController') -and $Context.Server){$params.DomainController=[string]$Context.Server}
        $cred=Get-WAdCredential $Context
        if($null -ne $cred){
            if(-not $cmd.Parameters.ContainsKey('Credential')){throw 'Cette version du module LAPS ne prend pas en charge le compte choisi.'}
            $params.Credential=$cred
            if($cmd.Parameters.ContainsKey('DecryptionCredential')){$params.DecryptionCredential=$cred}
        }
        # One call with the chosen identity; no fallback to Windows or another principal.
        $values=@(Get-LapsADPassword @params)
        foreach($v in $values){
            $lapsSource='WindowsLaps'
            if([string]$v.Account){$lapsAccount=[string]$v.Account}
            if($null -ne $v.PSObject.Properties['AuthorizedDecryptor']){$lapsDecryptor=[string]$v.AuthorizedDecryptor}
            if($null -ne $v.PSObject.Properties['ExpirationTimestamp'] -and $null -ne $v.ExpirationTimestamp){try{$lapsExpiration=([datetime]$v.ExpirationTimestamp).ToUniversalTime().ToString('o')}catch{}}
            $plain=''
            if($v.Password -is [Security.SecureString]){$plain=([Management.Automation.PSCredential]::new('value',$v.Password)).GetNetworkCredential().Password}else{$plain=[string]$v.Password}
            if($plain){$lapsPublished=$true;$decryptStatus='OK';$rows.Add([pscustomobject]@{Kind='Windows LAPS';Account=[string]$v.Account;Value=$plain;Timestamp=[string]$v.ExpirationTimestamp;Source='Get-LapsADPassword';Detail='Lecture et decryptage avec le compte explicitement choisi'})}
            elseif([string]$v.DecryptionStatus -match '(?i)Unauthorized|AccessDenied'){
                # Published and read, decryption refused: neither an empty password nor a refusal of the whole account.
                $lapsPublished=$true;$decryptStatus='Unauthorized';$errorKind='DecryptionDenied';$errorMessage='Le compte ne dispose pas du droit de dechiffrement LAPS.'
            }
            $plain=''
        }
        $moduleState='Disponible';$moduleDetail='Une demande Windows LAPS, aucune variante automatique.'
    }
}catch{
    if(-not $errorKind){
        $errorKind=if($_.Exception.Message -match '(?i)access.*denied|acc[eè]s.*refus|unauthori[sz]ed'){'AccessDenied'}elseif($_.Exception.Message -match '(?i)logon failure|mot de passe.*incorrect|invalid.*credential'){'LogonFailure'}else{'ReadFailed'}
    }
    $errorMessage=$_.Exception.Message;$moduleDetail=$errorMessage
}finally{if($null -ne $de){try{$de.Dispose()}catch{}}}
if(-not $rows.Count -and -not $errorMessage){$errorKind='NoReadableValue';$errorMessage='Aucune valeur LAPS visible avec ce compte : publication ou droits a verifier.'}
$readStatus='OK'
if($errorKind -eq 'ModuleMissing'){$readStatus='ModuleMissing'}
elseif($errorKind -eq 'AccessDenied'){$readStatus='AccessDenied'}
elseif($errorKind -in @('LogonFailure','ReadFailed')){$readStatus='Failed'}
elseif($errorKind -eq 'NoReadableValue'){$readStatus='Unconfirmed'}
$reader=[string]$Context.BindUser;if(-not $reader){$reader=[string]$Context.ProcessIdentity}
$meta=[pscustomobject]@{Source=$lapsSource;Published=$lapsPublished;ExpirationUtc=$lapsExpiration;Account=$lapsAccount;Decryptor=$lapsDecryptor;PasswordPresent=($rows.Count -gt 0);ReadStatus=$readStatus;DecryptStatus=$decryptStatus;Reader=$reader}
[pscustomobject]@{Rows=$rows.ToArray();Mode='LAPS';Success=($rows.Count -gt 0);ErrorKind=$errorKind;ErrorMessage=$errorMessage;ModuleState=$moduleState;ModuleDetail=$moduleDetail;Meta=$meta}
'@
        }
        $requestId = [guid]::NewGuid().ToString("N")
        $script:ActiveSecretRequestId = $requestId
        $objectGuid = ""
        try { $objectGuid = [string]$script:SelectedObject.Safety.Guid } catch { }
        $callbackState = [pscustomobject]@{
            RequestId=$requestId; DN=$dn; ObjectGuid=$objectGuid
            Generation=[int64]$script:SelectedObjectGeneration; Mode=$Mode; RetryAttempt=$RetryAttempt
        }
        Start-UiTask -Name "Lecture $Mode" -OperationId $secretOperationId -Code $code -Payload ([pscustomobject]@{ DN=$dn; Name=$name }) -CallbackState $callbackState -ReplaceKey "secrets" -DisableControls @("BtnLoadBitLocker","BtnLoadLaps") -TimeoutSeconds 40 -StatusText ("Lecture $Mode en arriere-plan... Identite : " + [string]$authNeed.Reason) -SuccessHandler $successHandler -ErrorHandler "Fail-DomeniaSecretLoadUi" | Out-Null
    }
    catch {
        $script:ActiveSecretRequestId = ""
        [void](Show-DomeniaOperationError -Operation "Lecture $Mode" -ErrorRecordOrException $_)
    }
}

function Toggle-SecretsVisibility {
    if (@($script:SecretRows).Count -eq 0) { return }
    if (Test-DomeniaSecretSingleExposure) {
        # D058/D059 (Features.SecretSingleCopy): only the selected value is revealed, after this explicit gesture,
        # for the exposure policy duration. A BitLocker line holding metadata only triggers the read of that ONE key.
        try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { }
        if ($script:SecretsVisible) { $script:SecretsVisible = $false; $script:RevealedSecretIndex = -1; Update-SecretsGrid; return }
        $grid = Get-DomeniaControl -Name 'DgSecrets'
        $selectedCount = 0
        if ($null -ne $grid -and $null -ne $grid.SelectedItem) { $selectedCount = 1 }
        if (-not (Test-DomeniaSecretRevealAllowed -Trigger 'ExplicitReveal' -SelectedCount $selectedCount)) { Set-Status "Selectionnez la valeur a afficher. Une seule valeur est revelee a la fois."; return }
        $source = Get-DomeniaSelectedSecretSource
        if ($null -eq $source) { return }
        if ([string]::IsNullOrWhiteSpace([string]$source.Value)) {
            if ([bool](Get-DomeniaMember $source 'Metadata' $false)) { [void](Request-DomeniaBitLockerKey -Trigger 'ExplicitReveal') }
            return
        }
        [void](Start-DomeniaSecretReveal -Index (Get-DomeniaSelectedSecretIndex))
        return
    }
    $script:RevealedSecretIndex = -1
    $script:SecretsVisible = -not $script:SecretsVisible
    try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { }
    if ($script:SecretsVisible) {
        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromSeconds(60)
        $timer.Add_Tick({
            $script:SecretRevealTimer.Stop()
            $script:SecretsVisible = $false
            Update-SecretsGrid
        })
        $script:SecretRevealTimer = $timer
        $timer.Start()
    }
    Update-SecretsGrid
}

function Start-SecretClipboardAutoClear {
    param([string]$Value)
    try {
        if ($null -ne $script:SecretClipboardTimer) { $script:SecretClipboardTimer.Stop() }
        $script:SecretClipboardValue = $Value
        $seconds = [int](Get-CfgValue "Security" "AutoClearSecretClipboardSeconds" 30)
        if ($seconds -le 0) { return }
        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [System.TimeSpan]::FromSeconds($seconds)
        $timer.Add_Tick({
            try {
                Clear-DomeniaSecretClipboard
                Set-Status "Presse-papiers secret efface automatiquement."
            }
            catch { try { Write-AppLog "Timer presse-papiers secret : $($_.Exception.ToString())" "WARN" } catch { } }
        })
        $script:SecretClipboardTimer = $timer
        $timer.Start()
    } catch { try { Write-AppLog "Programmation de l'effacement du presse-papiers impossible : $($_.Exception.ToString())" "WARN" } catch { } }
}

function Copy-SelectedSecret {
    try {
        $row = Get-DomeniaSelectedSecretSource
        # D059: the limits of third-party clipboard history stay explicit at every copy.
        $clipboardLimit = [string](Get-DomeniaSecretExposurePolicy).ClipboardLimit
        if ($null -ne $row -and [string]::IsNullOrWhiteSpace([string]$row.Value) -and [bool](Get-DomeniaMember $row 'Metadata' $false)) {
            # D058: a BitLocker line holding metadata only. The chosen key is read, then copied, after this confirmation.
            if (-not (Confirm-Action ("Lire puis copier temporairement la cle BitLocker " + [string]$row.Account + " ? Seule cette cle est lue. " + $clipboardLimit))) { return }
            [void](Request-DomeniaBitLockerKey -Trigger 'ExplicitCopy')
            return
        }
        if ($null -eq $row -or [string]::IsNullOrWhiteSpace([string]$row.Value)) { Set-Status "Aucun secret selectionne." "WARN"; return }
        if (-not (Confirm-Action ("Copier temporairement ce secret dans le presse-papiers ? " + $clipboardLimit))) { return }
        Set-DomeniaProtectedClipboard -Value ([string]$row.Value) -MaxLength 1024
        Start-SecretClipboardAutoClear ([string]$row.Value)
        Write-AppLog "Secret copie temporairement : $($row.Kind) / $($row.Account)" "WARN"
        Set-Status ("Secret copie. Effacement automatique programme. " + $clipboardLimit)
    } catch { Show-ErrorBox "Erreur copie secret : $($_.Exception.Message)" }
}

function Copy-AllSecrets {
    # D059 (Features.SecretSingleCopy): one value at a time. The previous "copy all" stays available only when the switch is off.
    if (Test-DomeniaSecretSingleExposure) { Set-Status "Copie groupee desactivee : copiez la seule valeur necessaire." "WARN"; return }
    if(-not (Confirm-Action -Title 'Copie de plusieurs secrets' -Message 'Copier toutes les valeurs augmente leur exposition. Preferez la copie de la seule valeur necessaire. Continuer ?')){return}
    try {
        $usable = @($script:SecretRows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Value) })
        if ($usable.Count -eq 0) { return }
        if (-not (Confirm-Action "Copier les $($usable.Count) secrets dans le presse-papiers ?")) { return }
        $value = (($usable | ForEach-Object { "$($_.Kind) | $($_.Account) | $($_.Value) | $($_.Timestamp)" }) -join [Environment]::NewLine)
        Set-DomeniaProtectedClipboard -Value $value
        Start-SecretClipboardAutoClear $value
        Write-AppLog "$($usable.Count) secrets copies temporairement." "WARN"
    } catch { Show-ErrorBox "Erreur copie secrets : $($_.Exception.Message)" }
}

function Toggle-MachineCredentialPassword {
    try {
        if ($script:__MachineCredentialReveal) {
            $script:Ctrl["PwdMachineAdmin"].Password = $script:Ctrl["TxtMachineAdminVisible"].Text
            $script:Ctrl["TxtMachineAdminVisible"].Visibility = [System.Windows.Visibility]::Collapsed
            $script:Ctrl["PwdMachineAdmin"].Visibility = [System.Windows.Visibility]::Visible
            $script:Ctrl["BtnRevealMachineAdmin"].Content = "👁"
            $script:__MachineCredentialReveal = $false
        } else {
            $script:Ctrl["TxtMachineAdminVisible"].Text = $script:Ctrl["PwdMachineAdmin"].Password
            $script:Ctrl["PwdMachineAdmin"].Visibility = [System.Windows.Visibility]::Collapsed
            $script:Ctrl["TxtMachineAdminVisible"].Visibility = [System.Windows.Visibility]::Visible
            $script:Ctrl["BtnRevealMachineAdmin"].Content = "🙈"
            $script:__MachineCredentialReveal = $true
        }
    } catch { }
}

function Set-MachineCredentialFromUi {
    try {
        $user = ($script:Ctrl["TxtMachineAdminUser"].Text + "").Trim()
        $pwd = if ($script:__MachineCredentialReveal) { $script:Ctrl["TxtMachineAdminVisible"].Text } else { $script:Ctrl["PwdMachineAdmin"].Password }
        if ([string]::IsNullOrWhiteSpace($user)) { throw "Compte poste vide." }
        if ([string]::IsNullOrWhiteSpace($pwd)) { throw "Mot de passe poste vide." }
        $script:MachineCredential = New-Object System.Management.Automation.PSCredential -ArgumentList @($user,(ConvertTo-DomeniaSecureString -Text ([string]$pwd)))
        $script:Ctrl["LblMachineCredential"].Text = "Operations poste : credential memoire $user. Rien ne sera enregistre."
        $script:Ctrl["PwdMachineAdmin"].Password = ""; $script:Ctrl["TxtMachineAdminVisible"].Text = ""
        Set-Status "Credential poste charge uniquement en memoire."
    } catch { Show-ErrorBox "Erreur credential poste : $($_.Exception.Message)" }
}

function Clear-MachineCredential {
    $script:MachineCredential = $null
    try { $script:Ctrl["PwdMachineAdmin"].Password = ""; $script:Ctrl["TxtMachineAdminVisible"].Text = ""; $script:Ctrl["LblMachineCredential"].Text = "Operations poste : session Windows courante ($script:ProcessIdentityDisplay)." } catch { }
    Set-Status "Credential poste efface de la memoire."
}


# =====================================================================
# Inventaire poste : collecte CIM/WMI source par source.
# Chaque source est isolee afin qu un refus d acces sur l une n empeche
# pas les autres, et le rapport d acces indique exactement ce qui a
# repondu, ce qui a ete refuse et ce qui est indisponible.
# =====================================================================
function Get-DomeniaInventoryWorkerCode {
    return @'
$rows = New-Object Collections.ArrayList
$access = New-Object Collections.ArrayList
$computer = [string]$Payload.Computer
$deep = [bool]$Payload.Deep
$cred = Get-WMachineCredential $Context
$totalWatch = [System.Diagnostics.Stopwatch]::StartNew()
$budgetMs = [Math]::Max(20000,[int]$Payload.BudgetMs)

$script:PrimarySession = $null
$script:AltSession = $null
$script:AltTried = $false
$script:PrimaryLabel = 'DCOM'
$script:AltLabel = 'WinRM'
$script:CollectorDeadline = [long]0
$script:CollectorTruncated = ''
$script:CollectorTransport = ''
$script:WinrmReady = $false

function Add-Item {
    param([string]$Category,[string]$Name,$Value,[string]$Source)
    $text = ''
    if ($null -ne $Value) { $text = ([string]$Value).Trim() }
    if ([string]::IsNullOrWhiteSpace($text)) { $text = '(vide)' }
    [void]$rows.Add([pscustomobject]@{ Category=$Category; Item=$Name; Value=$text; Source=$Source })
}
function Add-Access {
    param([string]$Category,[string]$Status,[string]$Detail,[int]$Ms,[int]$Count)
    [void]$access.Add([pscustomobject]@{ Category=$Category; Status=$Status; Items=$Count; DurationMs=$Ms; Detail=$Detail })
}
function Format-Size {
    param($Bytes)
    $v = 0.0
    try { $v = [double]$Bytes } catch { return '' }
    if ($v -le 0) { return '0 o' }
    $units = @('o','Ko','Mo','Go','To')
    $i = 0
    while ($v -ge 1024 -and $i -lt 4) { $v = $v / 1024.0; $i++ }
    $rounded = [Math]::Round($v,2)
    $unit = $units[$i]
    return ('' + $rounded + ' ' + $unit)
}
function Get-CimDate {
    param($Value)
    if ($null -eq $Value) { return '' }
    try { return ([datetime]$Value).ToString('dd/MM/yyyy HH:mm:ss') } catch { return [string]$Value }
}
function Test-Budget { return ($totalWatch.ElapsedMilliseconds -lt $budgetMs) }
function Test-CollectorBudget {
    if ($script:CollectorDeadline -le 0) { return $true }
    if (-not (Test-Budget)) { return $false }
    return ($totalWatch.ElapsedMilliseconds -lt $script:CollectorDeadline)
}
function Set-CollectorTruncated { param([string]$Reason) $script:CollectorTruncated = $Reason }

function Get-FailureStatus {
    param([string]$Message)
    if ($Message -match '(?i)access is denied|acces refuse|refus|denied|0x80070005|authoris') { return 'REFUSE' }
    if ($Message -match '(?i)invalid class|invalid namespace|not supported|introuvable|not found|non pris en charge|0x80041010') { return 'INDISPONIBLE' }
    if ($Message -match '(?i)timeout|delai|expire|RPC server is unavailable|serveur RPC|WinRM cannot complete') { return 'INJOIGNABLE' }
    return 'ERREUR'
}
function Invoke-InventoryTaskFallback {
    param([string]$ClassicError)
    $sw=[Diagnostics.Stopwatch]::StartNew()
    try {
        $local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
        $fb=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{Deep=$deep}) ([Math]::Min(75,[int]$Context.TaskFallbackTimeoutSeconds)) $ClassicError
        $fallbackLabel=if([string]$fb.DomeniaTransport -eq 'PsExec'){'PsExec'}else{'Tache planifiee'}
        foreach($rr in @($fb.Rows)) { Add-Item ([string]$rr.Category) ([string]$rr.Item) ([string]$rr.Value) ($fallbackLabel+' local SYSTEM / '+[string]$rr.Source) }
        $sw.Stop(); Add-Access ('Fallback '+$fallbackLabel) 'OK' ('Collecte locale SYSTEM terminee via '+$fallbackLabel+'.') ([int]$sw.ElapsedMilliseconds) @($fb.Rows).Count
        $bytes=0;try{$bytes=[long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived}catch{}
        return [pscustomobject]@{Computer=$computer;Rows=@($rows);Access=@($access);DurationMs=[long]$totalWatch.ElapsedMilliseconds;Success=$true;FallbackTasks=1;TaskBytes=$bytes}
    }
    catch {
        $sw.Stop(); Add-Access 'Fallbacks PsExec / tache' (Get-FailureStatus ([string]$_.Exception.Message)) ([string]$_.Exception.Message) ([int]$sw.ElapsedMilliseconds) 0
        return [pscustomobject]@{Computer=$computer;Rows=@($rows);Access=@($access);DurationMs=[long]$totalWatch.ElapsedMilliseconds;Success=$false;FallbackTasks=1;TaskBytes=0}
    }
}

function Invoke-Collector {
    param([string]$Category,[scriptblock]$Action,[int]$MaxMs = 12000)
    if (-not (Test-Budget)) { Add-Access $Category 'IGNORE' 'Budget global epuise avant cette source.' 0 0; return }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $before = $rows.Count
    $script:CollectorDeadline = [long]$totalWatch.ElapsedMilliseconds + [long]$MaxMs
    $script:CollectorTruncated = ''
    $script:CollectorTransport = ''
    try {
        & $Action
        $sw.Stop()
        $produced = $rows.Count - $before
        $status = 'OK'
        $detail = ''
        if ($produced -eq 0) { $status = 'VIDE'; $detail = 'La source a repondu sans aucune donnee.' }
        elseif (-not [string]::IsNullOrWhiteSpace($script:CollectorTruncated)) { $status = 'PARTIEL'; $detail = $script:CollectorTruncated }
        if (-not [string]::IsNullOrWhiteSpace($script:CollectorTransport)) {
            $prefix = 'Transport ' + $script:CollectorTransport + '.'
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = $prefix } else { $detail = $prefix + ' ' + $detail }
        }
        Add-Access $Category $status $detail ([int]$sw.ElapsedMilliseconds) $produced
    }
    catch {
        $sw.Stop()
        $message = [string]$_.Exception.Message
        Add-Access $Category (Get-FailureStatus $message) $message ([int]$sw.ElapsedMilliseconds) ($rows.Count - $before)
    }
    finally { $script:CollectorDeadline = 0 }
}

function New-InventorySession {
    param([string]$Protocol,[int]$TimeoutSeconds = 18)
    $option = New-CimSessionOption -Protocol $Protocol -ErrorAction Stop
    $params = @{ ComputerName=$computer; SessionOption=$option; ErrorAction='Stop' }
    if ($null -ne $cred) { $params['Credential'] = $cred }
    try {
        $command = Get-Command New-CimSession -ErrorAction Stop
        if ($command.Parameters.ContainsKey('OperationTimeoutSec')) { $params['OperationTimeoutSec'] = [Math]::Max(2,$TimeoutSeconds) }
    }
    catch { }
    return New-CimSession @params
}

function Get-AltSession {
    # Ouverture paresseuse du transport de repli : on ne paie son cout que si
    # une source echoue reellement sur le transport principal.
    if ($null -ne $script:AltSession) { return $script:AltSession }
    if ($script:AltTried) { return $null }
    $script:AltTried = $true
    $protocol = 'Wsman'
    if ($script:PrimaryLabel -eq 'WinRM') { $protocol = 'Dcom' }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $script:AltSession = New-InventorySession $protocol 15
        $sw.Stop()
        Add-Access 'Repli de transport' 'OK' ('Session ' + $script:AltLabel + ' ouverte en repli du transport principal.') ([int]$sw.ElapsedMilliseconds) 0
    }
    catch {
        $sw.Stop()
        $message = [string]$_.Exception.Message
        Add-Access 'Repli de transport' (Get-FailureStatus $message) ('Repli ' + $script:AltLabel + ' impossible : ' + $message) ([int]$sw.ElapsedMilliseconds) 0
        $script:AltSession = $null
    }
    return $script:AltSession
}

function Get-Cim {
    param([string]$Class,[string]$Namespace = 'root\cimv2',[string]$Filter = '',[string]$Query = '')
    $build = {
        param($Session)
        $p = @{ CimSession=$Session; Namespace=$Namespace; ErrorAction='Stop' }
        if (-not [string]::IsNullOrWhiteSpace($Query)) { $p['Query'] = $Query }
        else {
            $p['ClassName'] = $Class
            if (-not [string]::IsNullOrWhiteSpace($Filter)) { $p['Filter'] = $Filter }
        }
        return @(Get-CimInstance @p)
    }
    try {
        $result = & $build $script:PrimarySession
        if ([string]::IsNullOrWhiteSpace($script:CollectorTransport)) { $script:CollectorTransport = $script:PrimaryLabel }
        return $result
    }
    catch {
        $primaryError = [string]$_.Exception.Message
        $alt = Get-AltSession
        if ($null -eq $alt) { throw }
        $result = & $build $alt
        $script:CollectorTransport = $script:AltLabel + ' apres echec ' + $script:PrimaryLabel
        return $result
    }
}

function Invoke-Remote {
    # Execution distante par WinRM. Un aller-retour unique remplace des
    # centaines d appels registre, quand le service le permet.
    param([Parameter(Mandatory=$true)][scriptblock]$ScriptBlock,[int]$TimeoutSeconds = 25)
    if (-not $script:WinrmReady) { throw 'WinRM indisponible sur ce poste.' }
    $option = New-PSSessionOption -OpenTimeout ($TimeoutSeconds * 1000) -OperationTimeout ($TimeoutSeconds * 1000)
    $params = @{ ComputerName=$computer; ScriptBlock=$ScriptBlock; SessionOption=$option; ErrorAction='Stop' }
    if ($null -ne $cred) { $params['Credential'] = $cred; $params['Authentication'] = 'Default' }
    return @(Invoke-Command @params)
}

$HKLM = [uint32]2147483650
function Get-RegString {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    $session = $script:PrimarySession
    $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetStringValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop
    if ([int]$r.ReturnValue -ne 0) { return '' }
    return [string]$r.sValue
}
function Get-RegDword {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    $session = $script:PrimarySession
    $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetDWORDValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop
    if ([int]$r.ReturnValue -ne 0) { return $null }
    return $r.uValue
}
function Get-RegSubKeys {
    param([uint32]$Hive,[string]$Key)
    $session = $script:PrimarySession
    $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop
    if ([int]$r.ReturnValue -ne 0) { return @() }
    return @($r.sNames)
}
function Test-RegKey {
    param([uint32]$Hive,[string]$Key)
    try {
        $session = $script:PrimarySession
        $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop
        return ([int]$r.ReturnValue -eq 0)
    }
    catch { return $false }
}

# ---------------------------------------------------------------------
# Sonde des ports. Elle determine le transport principal et evite
# d attendre le delai complet d une session sur un poste injoignable.
# ---------------------------------------------------------------------
$portMap = @(
    @{ Port=135;  Label='RPC / DCOM' },
    @{ Port=5985; Label='WinRM HTTP' },
    @{ Port=5986; Label='WinRM HTTPS' },
    @{ Port=445;  Label='SMB' },
    @{ Port=3389; Label='Bureau a distance' }
)
$openPorts = @{}
$probeWatch = [System.Diagnostics.Stopwatch]::StartNew()
foreach ($entry in $portMap) {
    $isOpen = $false
    try { $isOpen = Test-WTcpPort $computer ([int]$entry.Port) 1800 } catch { }
    $openPorts[[int]$entry.Port] = $isOpen
    $state = 'ferme ou filtre'
    if ($isOpen) { $state = 'ouvert' }
    Add-Item 'Joignabilite' ([string]$entry.Label + ' (' + [string]$entry.Port + ')') $state 'Sonde TCP'
}
$probeWatch.Stop()
$dcomOpen = [bool]$openPorts[135]
$winrmOpen = ([bool]$openPorts[5985] -or [bool]$openPorts[5986])
$script:WinrmReady = $winrmOpen

if (-not $dcomOpen -and -not $winrmOpen) {
    Add-Access 'Joignabilite' 'INJOIGNABLE' 'Ni RPC 135 ni WinRM 5985/5986 ne repondent. Fallback PsExec puis tache planifiee.' ([int]$probeWatch.ElapsedMilliseconds) @($rows).Count
    $fallback=Invoke-InventoryTaskFallback 'Ni DCOM ni WinRM disponibles.'
    $totalWatch.Stop(); $fallback.DurationMs=[long]$totalWatch.ElapsedMilliseconds
    return $fallback
}
Add-Access 'Joignabilite' 'OK' ('Sonde TCP terminee. DCOM ouvert : ' + $dcomOpen + '. WinRM ouvert : ' + $winrmOpen + '.') ([int]$probeWatch.ElapsedMilliseconds) @($rows).Count

try {
    $sessionWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $order = @()
    if ($dcomOpen) { $order += @{ Protocol='Dcom'; Label='DCOM' } }
    if ($winrmOpen) { $order += @{ Protocol='Wsman'; Label='WinRM' } }
    if ([bool]$Payload.PreferWinrm -and $winrmOpen) {
        $order = @(@{ Protocol='Wsman'; Label='WinRM' }) + @($order | Where-Object { [string]$_.Protocol -ne 'Wsman' })
    }
    $lastError = ''
    foreach ($candidate in $order) {
        try {
            $script:PrimarySession = New-InventorySession ([string]$candidate.Protocol) 18
            $script:PrimaryLabel = [string]$candidate.Label
            if ($script:PrimaryLabel -eq 'DCOM') { $script:AltLabel = 'WinRM' } else { $script:AltLabel = 'DCOM' }
            break
        }
        catch { $lastError = [string]$_.Exception.Message }
    }
    $sessionWatch.Stop()
    if ($null -eq $script:PrimarySession) {
        Add-Access 'Connexion CIM' (Get-FailureStatus $lastError) ('Aucun transport classique utilisable. Dernier message : ' + $lastError) ([int]$sessionWatch.ElapsedMilliseconds) 0
        $fallback=Invoke-InventoryTaskFallback $lastError
        $totalWatch.Stop(); $fallback.DurationMs=[long]$totalWatch.ElapsedMilliseconds
        return $fallback
    }
    $identity = 'session Windows du poste DOMENIA'
    if ($null -ne $cred) { $identity = [string]$cred.UserName }
    Add-Access 'Connexion CIM' 'OK' ('Transport principal ' + $script:PrimaryLabel + ', identite ' + $identity + '.') ([int]$sessionWatch.ElapsedMilliseconds) 0

    Invoke-Collector 'Systeme' {
        foreach ($cs in (Get-Cim 'Win32_ComputerSystem')) {
            Add-Item 'Systeme' 'Nom' $cs.Name 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Domaine' $cs.Domain 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Fabricant' $cs.Manufacturer 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Modele' $cs.Model 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Memoire physique totale' (Format-Size $cs.TotalPhysicalMemory) 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Processeurs logiques' $cs.NumberOfLogicalProcessors 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Utilisateur connecte' $cs.UserName 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Role dans le domaine' $cs.DomainRole 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Type de systeme' $cs.SystemType 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Demarrage PXE ou etat' $cs.BootupState 'Win32_ComputerSystem'
        }
        foreach ($se in (Get-Cim 'Win32_SystemEnclosure')) {
            Add-Item 'Systeme' 'Numero de serie chassis' $se.SerialNumber 'Win32_SystemEnclosure'
            Add-Item 'Systeme' 'Type de chassis' (@($se.ChassisTypes) -join ', ') 'Win32_SystemEnclosure'
        }
        foreach ($cp in (Get-Cim 'Win32_ComputerSystemProduct')) {
            Add-Item 'Systeme' 'Identifiant materiel UUID' $cp.UUID 'Win32_ComputerSystemProduct'
            Add-Item 'Systeme' 'Reference produit' $cp.Name 'Win32_ComputerSystemProduct'
        }
    }

    Invoke-Collector 'BIOS et firmware' {
        foreach ($b in (Get-Cim 'Win32_BIOS')) {
            Add-Item 'BIOS et firmware' 'Fabricant' $b.Manufacturer 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Version' (@($b.BIOSVersion) -join ' / ') 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Version SMBIOS' $b.SMBIOSBIOSVersion 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Date' (Get-CimDate $b.ReleaseDate) 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Numero de serie' $b.SerialNumber 'Win32_BIOS'
        }
        $secureBoot = ''
        try { $secureBoot = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control\SecureBoot\State' 'UEFISecureBootEnabled' } catch { }
        if ([string]::IsNullOrWhiteSpace($secureBoot)) {
            $present = Test-RegKey $HKLM 'SYSTEM\CurrentControlSet\Control\SecureBoot\State'
            $label = 'Non expose'
            if ($present) { $label = 'Cle presente, valeur non lisible' }
            Add-Item 'BIOS et firmware' 'Secure Boot' $label 'Registre SecureBoot'
        }
        else {
            $label = 'Desactive'
            if ($secureBoot -eq '1') { $label = 'Active' }
            Add-Item 'BIOS et firmware' 'Secure Boot' $label 'Registre SecureBoot'
        }
        $firmware = 'BIOS herite'
        try {
            $pe = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control' 'PEFirmwareType'
            if ($pe -eq '2') { $firmware = 'UEFI' }
        }
        catch { $firmware = 'Non determine' }
        Add-Item 'BIOS et firmware' 'Type de firmware' $firmware 'Registre Control'
    }

    Invoke-Collector 'Carte mere' {
        foreach ($bb in (Get-Cim 'Win32_BaseBoard')) {
            Add-Item 'Carte mere' 'Fabricant' $bb.Manufacturer 'Win32_BaseBoard'
            Add-Item 'Carte mere' 'Produit' $bb.Product 'Win32_BaseBoard'
            Add-Item 'Carte mere' 'Numero de serie' $bb.SerialNumber 'Win32_BaseBoard'
        }
    }

    Invoke-Collector 'Processeur' {
        $index = 0
        foreach ($cpu in (Get-Cim 'Win32_Processor')) {
            $index++
            $prefix = 'CPU ' + $index
            Add-Item 'Processeur' ($prefix + ' modele') $cpu.Name 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' coeurs') $cpu.NumberOfCores 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' processeurs logiques') $cpu.NumberOfLogicalProcessors 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' frequence max MHz') $cpu.MaxClockSpeed 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' charge actuelle %') $cpu.LoadPercentage 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' virtualisation firmware') $cpu.VirtualizationFirmwareEnabled 'Win32_Processor'
        }
    }

    Invoke-Collector 'Memoire' {
        $total = 0
        $index = 0
        foreach ($m in (Get-Cim 'Win32_PhysicalMemory')) {
            $index++
            try { $total = $total + [double]$m.Capacity } catch { }
            $label = 'Barrette ' + $index
            $slot = [string]$m.DeviceLocator
            $size = Format-Size $m.Capacity
            $speed = [string]$m.Speed
            $value = $size + ' a ' + $speed + ' MHz, emplacement ' + $slot
            Add-Item 'Memoire' $label $value 'Win32_PhysicalMemory'
        }
        if ($index -gt 0) { Add-Item 'Memoire' 'Total installe' (Format-Size $total) 'Win32_PhysicalMemory' }
        foreach ($os in (Get-Cim 'Win32_OperatingSystem')) {
            Add-Item 'Memoire' 'Memoire libre' (Format-Size ([double]$os.FreePhysicalMemory * 1024)) 'Win32_OperatingSystem'
        }
        foreach ($pf in (Get-Cim 'Win32_PageFileUsage')) {
            $value = 'taille ' + [string]$pf.AllocatedBaseSize + ' Mo, pic ' + [string]$pf.PeakUsage + ' Mo'
            Add-Item 'Memoire' ('Fichier d echange ' + [string]$pf.Name) $value 'Win32_PageFileUsage'
        }
    }

    Invoke-Collector 'Systeme d exploitation' {
        foreach ($os in (Get-Cim 'Win32_OperatingSystem')) {
            Add-Item 'Systeme d exploitation' 'Nom' $os.Caption 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Version' $os.Version 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Build' $os.BuildNumber 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Architecture' $os.OSArchitecture 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Installe le' (Get-CimDate $os.InstallDate) 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Dernier demarrage' (Get-CimDate $os.LastBootUpTime) 'Win32_OperatingSystem'
            try {
                $uptime = (Get-Date) - [datetime]$os.LastBootUpTime
                $days = [int]$uptime.Days
                $hours = [int]$uptime.Hours
                $minutes = [int]$uptime.Minutes
                Add-Item 'Systeme d exploitation' 'Duree de fonctionnement' ('' + $days + ' j ' + $hours + ' h ' + $minutes + ' min') 'Win32_OperatingSystem'
            }
            catch { }
            Add-Item 'Systeme d exploitation' 'Repertoire Windows' $os.WindowsDirectory 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Langue' $os.OSLanguage 'Win32_OperatingSystem'
        }
        $release = ''
        try { $release = Get-RegString $HKLM 'SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'DisplayVersion' } catch { }
        if (-not [string]::IsNullOrWhiteSpace($release)) { Add-Item 'Systeme d exploitation' 'Version commerciale' $release 'Registre CurrentVersion' }
        $ubr = $null
        try { $ubr = Get-RegDword $HKLM 'SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'UBR' } catch { }
        if ($null -ne $ubr) { Add-Item 'Systeme d exploitation' 'Revision de build' $ubr 'Registre CurrentVersion' }
        foreach ($tz in (Get-Cim 'Win32_TimeZone')) {
            Add-Item 'Systeme d exploitation' 'Fuseau horaire' $tz.Caption 'Win32_TimeZone'
        }
    }

    Invoke-Collector 'Appartenance et site' {
        $domain = ''
        try { $domain = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Tcpip\Parameters' 'Domain' } catch { }
        Add-Item 'Appartenance et site' 'Suffixe DNS principal' $domain 'Registre Tcpip'
        $site = ''
        try { $site = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' 'DynamicSiteName' } catch { }
        if ([string]::IsNullOrWhiteSpace($site)) {
            try { $site = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' 'SiteName' } catch { }
        }
        Add-Item 'Appartenance et site' 'Site Active Directory' $site 'Registre Netlogon'
        $proxy = ''
        try { $proxy = Get-RegString $HKLM 'SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings' 'ProxyServer' } catch { }
        Add-Item 'Appartenance et site' 'Proxy machine' $proxy 'Registre Internet Settings'
    }

    Invoke-Collector 'Disques logiques' {
        foreach ($d in (Get-Cim 'Win32_LogicalDisk' 'root\cimv2' 'DriveType=3')) {
            $free = 0.0
            $size = 0.0
            try { $free = [double]$d.FreeSpace } catch { }
            try { $size = [double]$d.Size } catch { }
            $pct = 0
            if ($size -gt 0) { $pct = [Math]::Round(100.0 * $free / $size,1) }
            $value = (Format-Size $size) + ' dont ' + (Format-Size $free) + ' libres (' + $pct + ' %)'
            $label = [string]$d.DeviceID + ' ' + [string]$d.VolumeName
            Add-Item 'Disques logiques' $label $value 'Win32_LogicalDisk'
            if ($pct -lt 10 -and $size -gt 0) { Add-Item 'Disques logiques' ($label + ' alerte') 'Espace libre inferieur a 10 pour cent' 'Win32_LogicalDisk' }
        }
    }

    Invoke-Collector 'Disques physiques' {
        $index = 0
        foreach ($d in (Get-Cim 'Win32_DiskDrive')) {
            $index++
            $label = 'Disque ' + $index
            $value = [string]$d.Model + ', ' + (Format-Size $d.Size) + ', interface ' + [string]$d.InterfaceType
            Add-Item 'Disques physiques' $label $value 'Win32_DiskDrive'
            Add-Item 'Disques physiques' ($label + ' numero de serie') $d.SerialNumber 'Win32_DiskDrive'
            Add-Item 'Disques physiques' ($label + ' etat SMART') $d.Status 'Win32_DiskDrive'
        }
        try {
            foreach ($pd in (Get-Cim 'MSFT_PhysicalDisk' 'root\Microsoft\Windows\Storage')) {
                $media = 'Inconnu'
                if ([int]$pd.MediaType -eq 3) { $media = 'HDD' }
                elseif ([int]$pd.MediaType -eq 4) { $media = 'SSD' }
                $health = 'Sain'
                if ([int]$pd.HealthStatus -eq 1) { $health = 'Avertissement' }
                elseif ([int]$pd.HealthStatus -eq 2) { $health = 'Defaillant' }
                Add-Item 'Disques physiques' ('Support ' + [string]$pd.DeviceId) ($media + ', etat ' + $health) 'MSFT_PhysicalDisk'
            }
        }
        catch { }
    }

    Invoke-Collector 'BitLocker' {
        foreach ($v in (Get-Cim 'Win32_EncryptableVolume' 'root\cimv2\Security\MicrosoftVolumeEncryption')) {
            $protection = 'Desactive'
            if ([int]$v.ProtectionStatus -eq 1) { $protection = 'Active' }
            elseif ([int]$v.ProtectionStatus -eq 2) { $protection = 'Inconnu' }
            $label = 'Volume ' + [string]$v.DriveLetter
            Add-Item 'BitLocker' $label ('Protection ' + $protection) 'Win32_EncryptableVolume'
            Add-Item 'BitLocker' ($label + ' methode') $v.EncryptionMethod 'Win32_EncryptableVolume'
        }
    }

    Invoke-Collector 'TPM' {
        foreach ($t in (Get-Cim 'Win32_Tpm' 'root\cimv2\Security\MicrosoftTpm')) {
            $enabled = 'Non'
            if ([bool]$t.IsEnabled_InitialValue) { $enabled = 'Oui' }
            $activated = 'Non'
            if ([bool]$t.IsActivated_InitialValue) { $activated = 'Oui' }
            Add-Item 'TPM' 'Present' 'Oui' 'Win32_Tpm'
            Add-Item 'TPM' 'Active' $enabled 'Win32_Tpm'
            Add-Item 'TPM' 'Operationnel' $activated 'Win32_Tpm'
            Add-Item 'TPM' 'Version specification' $t.SpecVersion 'Win32_Tpm'
            Add-Item 'TPM' 'Fabricant' $t.ManufacturerIdTxt 'Win32_Tpm'
        }
    }

    Invoke-Collector 'Reseau' {
        foreach ($n in (Get-Cim 'Win32_NetworkAdapterConfiguration' 'root\cimv2' 'IPEnabled=True')) {
            $label = [string]$n.Description
            Add-Item 'Reseau' ($label + ' adresses IP') (@($n.IPAddress) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' masque') (@($n.IPSubnet) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' passerelle') (@($n.DefaultIPGateway) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' DNS') (@($n.DNSServerSearchOrder) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' MAC') $n.MACAddress 'Win32_NetworkAdapterConfiguration'
            $dhcp = 'Non'
            if ([bool]$n.DHCPEnabled) { $dhcp = 'Oui' }
            Add-Item 'Reseau' ($label + ' DHCP') $dhcp 'Win32_NetworkAdapterConfiguration'
            if ([bool]$n.DHCPEnabled) {
                Add-Item 'Reseau' ($label + ' serveur DHCP') $n.DHCPServer 'Win32_NetworkAdapterConfiguration'
                Add-Item 'Reseau' ($label + ' bail obtenu') (Get-CimDate $n.DHCPLeaseObtained) 'Win32_NetworkAdapterConfiguration'
                Add-Item 'Reseau' ($label + ' bail expire') (Get-CimDate $n.DHCPLeaseExpires) 'Win32_NetworkAdapterConfiguration'
            }
        }
    }

    Invoke-Collector 'Cartes reseau' {
        foreach ($a in (Get-Cim 'Win32_NetworkAdapter' 'root\cimv2' 'PhysicalAdapter=True')) {
            $speed = ''
            try { if ([double]$a.Speed -gt 0) { $speed = ', ' + [Math]::Round([double]$a.Speed / 1000000.0,0) + ' Mb/s' } } catch { }
            Add-Item 'Cartes reseau' $a.Name ([string]$a.NetConnectionStatus + $speed) 'Win32_NetworkAdapter'
        }
    }

    Invoke-Collector 'Pare-feu' {
        foreach ($profile in @(
            @{ Key='SOFTWARE\Policies\Microsoft\WindowsFirewall\DomainProfile'; Label='Profil domaine (strategie)' },
            @{ Key='SOFTWARE\Policies\Microsoft\WindowsFirewall\StandardProfile'; Label='Profil prive (strategie)' },
            @{ Key='SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile'; Label='Profil public (strategie)' },
            @{ Key='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\DomainProfile'; Label='Profil domaine' },
            @{ Key='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\StandardProfile'; Label='Profil prive' },
            @{ Key='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\PublicProfile'; Label='Profil public' }
        )) {
            $value = $null
            try { $value = Get-RegDword $HKLM ([string]$profile.Key) 'EnableFirewall' } catch { }
            if ($null -eq $value) { continue }
            $state = 'Desactive'
            if ([int]$value -eq 1) { $state = 'Active' }
            Add-Item 'Pare-feu' ([string]$profile.Label) $state 'Registre FirewallPolicy'
        }
    }

    Invoke-Collector 'Antivirus' {
        foreach ($av in (Get-Cim 'AntiVirusProduct' 'root\SecurityCenter2')) {
            $state = 0
            try { $state = [int]$av.productState } catch { }
            $hex = '{0:X6}' -f $state
            $enabled = 'Inconnu'
            $updated = 'Inconnu'
            try {
                $mid = [Convert]::ToInt32($hex.Substring(2,2),16)
                $low = [Convert]::ToInt32($hex.Substring(4,2),16)
                if ($mid -ge 16) { $enabled = 'Actif' } else { $enabled = 'Inactif' }
                if ($low -eq 0) { $updated = 'A jour' } else { $updated = 'Signatures obsoletes' }
            }
            catch { }
            Add-Item 'Antivirus' $av.displayName ($enabled + ', ' + $updated) 'root\SecurityCenter2'
        }
    }

    Invoke-Collector 'Correctifs' {
        $all = @(Get-Cim 'Win32_QuickFixEngineering')
        Add-Item 'Correctifs' 'Nombre total' (@($all).Count) 'Win32_QuickFixEngineering'
        foreach ($h in ($all | Sort-Object -Property InstalledOn -Descending | Select-Object -First 15)) {
            Add-Item 'Correctifs' $h.HotFixID ([string]$h.Description + ' installe le ' + (Get-CimDate $h.InstalledOn)) 'Win32_QuickFixEngineering'
        }
    } 12000

    Invoke-Collector 'Windows Update' {
        foreach ($entry in @(
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Detect'; Label='Derniere recherche' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Download'; Label='Dernier telechargement' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install'; Label='Derniere installation' }
        )) {
            $value = ''
            try { $value = Get-RegString $HKLM ([string]$entry.Key) 'LastSuccessTime' } catch { }
            if (-not [string]::IsNullOrWhiteSpace($value)) { Add-Item 'Windows Update' ([string]$entry.Label) $value 'Registre WindowsUpdate' }
        }
        $wsus = ''
        try { $wsus = Get-RegString $HKLM 'SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' 'WUServer' } catch { }
        if (-not [string]::IsNullOrWhiteSpace($wsus)) { Add-Item 'Windows Update' 'Serveur WSUS' $wsus 'Registre WindowsUpdate' }
    }

    Invoke-Collector 'Logiciels installes' {
        $seen = @{}
        $names = New-Object Collections.ArrayList
        $source = ''

        # 1. Inventaire SCCM : une seule requete.
        try {
            foreach ($p in (Get-Cim 'Win32Reg_AddRemovePrograms')) {
                $display = [string]$p.DisplayName
                if ([string]::IsNullOrWhiteSpace($display)) { continue }
                $key = $display.ToLowerInvariant()
                if ($seen.ContainsKey($key)) { continue }
                $seen[$key] = $true
                [void]$names.Add([pscustomobject]@{ Name=$display; Version=[string]$p.Version })
            }
            if (@($names).Count -gt 0) { $source = 'Win32Reg_AddRemovePrograms' }
        }
        catch { }

        # 2. WinRM : un aller-retour unique remplace des centaines d appels.
        if ([string]::IsNullOrWhiteSpace($source) -and $script:WinrmReady) {
            try {
                $remote = Invoke-Remote -TimeoutSeconds 30 -ScriptBlock {
                    $paths = @(
                        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
                        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
                    )
                    Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue |
                        Where-Object { $_.DisplayName } |
                        Select-Object DisplayName,DisplayVersion,Publisher,InstallDate
                }
                foreach ($p in @($remote)) {
                    $display = [string]$p.DisplayName
                    if ([string]::IsNullOrWhiteSpace($display)) { continue }
                    $key = $display.ToLowerInvariant()
                    if ($seen.ContainsKey($key)) { continue }
                    $seen[$key] = $true
                    [void]$names.Add([pscustomobject]@{ Name=$display; Version=[string]$p.DisplayVersion })
                }
                if (@($names).Count -gt 0) { $source = 'Registre via WinRM' ; $script:CollectorTransport = 'WinRM (un seul aller-retour)' }
            }
            catch { }
        }

        # 3. Repli registre par appels unitaires, borne en cles et en temps.
        if ([string]::IsNullOrWhiteSpace($source)) {
            $source = 'Registre Uninstall'
            $maxKeys = [Math]::Max(50,[int]$Payload.MaxSoftwareKeys)
            $scanned = 0
            $stopped = $false
            foreach ($base in @('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall','SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall')) {
                if ($stopped) { break }
                $subKeys = @()
                try { $subKeys = Get-RegSubKeys $HKLM $base } catch { continue }
                foreach ($sub in $subKeys) {
                    if ($scanned -ge $maxKeys) { Set-CollectorTruncated ('Lecture arretee apres ' + $maxKeys + ' cles de registre.'); $stopped = $true; break }
                    if (-not (Test-CollectorBudget)) { Set-CollectorTruncated ('Lecture arretee apres ' + $scanned + ' cles : budget de la source atteint.'); $stopped = $true; break }
                    $scanned++
                    $key = $base + '\' + [string]$sub
                    $display = ''
                    try { $display = Get-RegString $HKLM $key 'DisplayName' } catch { continue }
                    if ([string]::IsNullOrWhiteSpace($display)) { continue }
                    $dedupe = $display.ToLowerInvariant()
                    if ($seen.ContainsKey($dedupe)) { continue }
                    $seen[$dedupe] = $true
                    $version = ''
                    try { $version = Get-RegString $HKLM $key 'DisplayVersion' } catch { }
                    [void]$names.Add([pscustomobject]@{ Name=$display; Version=$version })
                }
            }
        }

        Add-Item 'Logiciels installes' 'Nombre detecte' (@($names).Count) $source
        foreach ($n in ($names.ToArray() | Sort-Object -Property Name)) { Add-Item 'Logiciels installes' $n.Name $n.Version $source }
    } 20000

    Invoke-Collector 'Demarrage automatique' {
        foreach ($s in (@(Get-Cim 'Win32_StartupCommand') | Select-Object -First 40)) {
            Add-Item 'Demarrage automatique' ([string]$s.Name + ' (' + [string]$s.User + ')') ([string]$s.Command + ' depuis ' + [string]$s.Location) 'Win32_StartupCommand'
        }
    }

    Invoke-Collector 'Services en defaut' {
        $stopped = @(Get-Cim 'Win32_Service' 'root\cimv2' 'StartMode="Auto" AND State="Stopped"')
        foreach ($s in (@($stopped) | Select-Object -First 40)) {
            Add-Item 'Services en defaut' $s.DisplayName ('Demarrage automatique mais arrete. Nom : ' + [string]$s.Name) 'Win32_Service'
        }
        if (@($stopped).Count -eq 0) { Add-Item 'Services en defaut' 'Etat' 'Aucun service automatique arrete' 'Win32_Service' }
    }

    Invoke-Collector 'Peripheriques en erreur' {
        $bad = @(Get-Cim 'Win32_PnPEntity' 'root\cimv2' 'ConfigManagerErrorCode<>0')
        foreach ($d in (@($bad) | Select-Object -First 30)) {
            Add-Item 'Peripheriques en erreur' ([string]$d.Name) ('Code ' + [string]$d.ConfigManagerErrorCode + ', ' + [string]$d.DeviceID) 'Win32_PnPEntity'
        }
        if (@($bad).Count -eq 0) { Add-Item 'Peripheriques en erreur' 'Etat' 'Aucun peripherique en erreur' 'Win32_PnPEntity' }
    } 15000

    Invoke-Collector 'Affichage' {
        foreach ($g in (Get-Cim 'Win32_VideoController')) {
            $ram = Format-Size $g.AdapterRAM
            Add-Item 'Affichage' ([string]$g.Name) ($ram + ', pilote ' + [string]$g.DriverVersion + ', resolution ' + [string]$g.CurrentHorizontalResolution + 'x' + [string]$g.CurrentVerticalResolution) 'Win32_VideoController'
        }
        try {
            $index = 0
            foreach ($m in (Get-Cim 'WmiMonitorID' 'root\wmi')) {
                $index++
                $name = ''
                try { $name = -join ([char[]]@($m.UserFriendlyName | Where-Object { $_ -gt 0 })) } catch { }
                $serial = ''
                try { $serial = -join ([char[]]@($m.SerialNumberID | Where-Object { $_ -gt 0 })) } catch { }
                Add-Item 'Affichage' ('Ecran ' + $index) ($name + ', serie ' + $serial + ', annee ' + [string]$m.YearOfManufacture) 'WmiMonitorID'
            }
        }
        catch { }
    }

    Invoke-Collector 'Batterie' {
        $found = 0
        foreach ($b in (Get-Cim 'Win32_Battery')) {
            $found++
            Add-Item 'Batterie' ([string]$b.Name) ('Charge ' + [string]$b.EstimatedChargeRemaining + ' %, etat ' + [string]$b.BatteryStatus) 'Win32_Battery'
        }
        if ($found -eq 0) { Add-Item 'Batterie' 'Etat' 'Aucune batterie : poste fixe ou alimentation secteur uniquement' 'Win32_Battery' }
    }

    Invoke-Collector 'Pilotes non signes' {
        $unsigned = @(Get-Cim 'Win32_PnPSignedDriver' 'root\cimv2' 'IsSigned=False')
        foreach ($d in (@($unsigned) | Select-Object -First 25)) {
            Add-Item 'Pilotes non signes' ([string]$d.DeviceName) ([string]$d.DriverProviderName + ' version ' + [string]$d.DriverVersion) 'Win32_PnPSignedDriver'
        }
        if (@($unsigned).Count -eq 0) { Add-Item 'Pilotes non signes' 'Etat' 'Tous les pilotes remontes sont signes' 'Win32_PnPSignedDriver' }
    } 20000

    Invoke-Collector 'Comptes et sessions' {
        foreach ($u in (Get-Cim 'Win32_UserAccount' 'root\cimv2' 'LocalAccount=True')) {
            $flags = New-Object Collections.ArrayList
            if ([bool]$u.Disabled) { [void]$flags.Add('desactive') } else { [void]$flags.Add('actif') }
            if ([bool]$u.Lockout) { [void]$flags.Add('verrouille') }
            if ([bool]$u.PasswordRequired) { [void]$flags.Add('mot de passe requis') }
            if ([bool]$u.PasswordExpires) { [void]$flags.Add('mot de passe expirable') }
            Add-Item 'Comptes et sessions' ('Compte local ' + [string]$u.Name) (@($flags) -join ', ') 'Win32_UserAccount'
        }
        foreach ($l in (@(Get-Cim 'Win32_LogonSession' 'root\cimv2' 'LogonType=2 OR LogonType=10') | Select-Object -First 20)) {
            $type = 'interactive'
            if ([int]$l.LogonType -eq 10) { $type = 'bureau a distance' }
            Add-Item 'Comptes et sessions' ('Session ' + [string]$l.LogonId) ($type + ' ouverte le ' + (Get-CimDate $l.StartTime)) 'Win32_LogonSession'
        }
    }

    Invoke-Collector 'Administrateurs locaux' {
        $group = @(Get-Cim 'Win32_Group' 'root\cimv2' 'LocalAccount=True AND SID="S-1-5-32-544"') | Select-Object -First 1
        if ($null -eq $group) { throw 'Groupe Administrateurs local introuvable.' }
        $groupName = [string]$group.Name
        $quote = [string][char]39
        $query = 'SELECT * FROM Win32_GroupUser WHERE GroupComponent="Win32_Group.Domain=' + $quote + $quote + [string]$computer + $quote + $quote + ',Name=' + $quote + $quote + $groupName + $quote + $quote + '"'
        $members = @(Get-Cim '' 'root\cimv2' '' $query)
        foreach ($m in $members) {
            $part = [string]$m.PartComponent
            $clean = $part
            try {
                $domainMatch = [regex]::Match($part,'Domain="([^"]+)"')
                $nameMatch = [regex]::Match($part,'Name="([^"]+)"')
                if ($domainMatch.Success -and $nameMatch.Success) { $clean = $domainMatch.Groups[1].Value + '\' + $nameMatch.Groups[1].Value }
            }
            catch { }
            Add-Item 'Administrateurs locaux' 'Membre' $clean 'Win32_GroupUser'
        }
        if (@($members).Count -eq 0) { Add-Item 'Administrateurs locaux' 'Etat' 'Aucun membre lisible' 'Win32_GroupUser' }
    }

    Invoke-Collector 'Partages' {
        foreach ($s in (Get-Cim 'Win32_Share')) {
            Add-Item 'Partages' $s.Name ([string]$s.Path + ' ' + [string]$s.Description) 'Win32_Share'
        }
    }

    Invoke-Collector 'Imprimantes' {
        foreach ($p in (@(Get-Cim 'Win32_Printer') | Select-Object -First 40)) {
            $default = ''
            if ([bool]$p.Default) { $default = ' (par defaut)' }
            Add-Item 'Imprimantes' $p.Name ([string]$p.PortName + ' ' + [string]$p.DriverName + $default) 'Win32_Printer'
        }
    }

    Invoke-Collector 'Redemarrage en attente' {
        $reasons = New-Object Collections.ArrayList
        foreach ($c in @(
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'; Label='Maintenance de composants' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'; Label='Windows Update' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootInProgress'; Label='Maintenance en cours' }
        )) {
            if (Test-RegKey $HKLM ([string]$c.Key)) { [void]$reasons.Add([string]$c.Label) }
        }
        $pendingRename = ''
        try { $pendingRename = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control\Session Manager' 'PendingFileRenameOperations' } catch { }
        if (-not [string]::IsNullOrWhiteSpace($pendingRename)) { [void]$reasons.Add('Renommage de fichiers en attente') }
        if (@($reasons).Count -eq 0) { Add-Item 'Redemarrage en attente' 'Etat' 'Aucun redemarrage en attente' 'Registre' }
        else { Add-Item 'Redemarrage en attente' 'Etat' ('Redemarrage requis : ' + (@($reasons) -join ', ')) 'Registre' }
    }

    if ($deep) {
        Invoke-Collector 'Processus' {
            foreach ($p in (@(Get-Cim 'Win32_Process') | Sort-Object WorkingSetSize -Descending | Select-Object -First 12)) {
                Add-Item 'Processus' ([string]$p.Name + ' (PID ' + [string]$p.ProcessId + ')') (Format-Size $p.WorkingSetSize) 'Win32_Process'
            }
        } 12000

        Invoke-Collector 'Evenements systeme' {
            $since = (Get-Date).AddDays(-3)
            $stamp = $since.ToUniversalTime().ToString('yyyyMMddHHmmss') + '.000000+000'
            $query = 'SELECT * FROM Win32_NTLogEvent WHERE Logfile="System" AND EventType=1 AND TimeGenerated>="' + $stamp + '"'
            $events = @(Get-Cim '' 'root\cimv2' '' $query | Select-Object -First 15)
            foreach ($e in $events) {
                $msg = [string]$e.Message
                if ($msg.Length -gt 220) { $msg = $msg.Substring(0,220) + '...' }
                Add-Item 'Evenements systeme' ([string]$e.SourceName + ' ID ' + [string]$e.EventCode) ((Get-CimDate $e.TimeGenerated) + ' : ' + $msg) 'Win32_NTLogEvent'
            }
            if (@($events).Count -eq 0) { Add-Item 'Evenements systeme' 'Etat' 'Aucune erreur systeme sur 3 jours' 'Win32_NTLogEvent' }
        } 30000

        Invoke-Collector 'Taches planifiees' {
            $tasks = Invoke-Remote -TimeoutSeconds 30 -ScriptBlock {
                Get-ScheduledTask -ErrorAction SilentlyContinue |
                    Where-Object { $_.State -ne 'Disabled' -and $_.TaskPath -notlike '\Microsoft\*' } |
                    Select-Object TaskName,TaskPath,State
            }
            foreach ($t in (@($tasks) | Select-Object -First 40)) {
                Add-Item 'Taches planifiees' ([string]$t.TaskName) ([string]$t.TaskPath + ' etat ' + [string]$t.State) 'Get-ScheduledTask via WinRM'
            }
            if (@($tasks).Count -eq 0) { Add-Item 'Taches planifiees' 'Etat' 'Aucune tache hors Microsoft active' 'Get-ScheduledTask via WinRM' }
        } 35000

        Invoke-Collector 'Certificats machine' {
            $certs = Invoke-Remote -TimeoutSeconds 25 -ScriptBlock {
                Get-ChildItem -Path 'Cert:\LocalMachine\My' -ErrorAction SilentlyContinue |
                    Select-Object Subject,NotAfter,Thumbprint,Issuer
            }
            foreach ($c in (@($certs) | Select-Object -First 25)) {
                $days = 0
                try { $days = [int]((([datetime]$c.NotAfter) - (Get-Date)).TotalDays) } catch { }
                $flag = ''
                if ($days -lt 0) { $flag = ' EXPIRE' }
                elseif ($days -lt 30) { $flag = ' expire bientot' }
                Add-Item 'Certificats machine' ([string]$c.Subject) ('valide jusqu au ' + [string]$c.NotAfter + ', ' + $days + ' jour(s)' + $flag) 'Cert:\LocalMachine\My via WinRM'
            }
            if (@($certs).Count -eq 0) { Add-Item 'Certificats machine' 'Etat' 'Aucun certificat machine' 'WinRM' }
        } 30000

        Invoke-Collector 'Connexions reseau' {
            $conns = Invoke-Remote -TimeoutSeconds 25 -ScriptBlock {
                Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue |
                    Select-Object -First 30 LocalPort,RemoteAddress,RemotePort,OwningProcess
            }
            foreach ($c in @($conns)) {
                Add-Item 'Connexions reseau' ('Port local ' + [string]$c.LocalPort) ('vers ' + [string]$c.RemoteAddress + ':' + [string]$c.RemotePort + ', PID ' + [string]$c.OwningProcess) 'Get-NetTCPConnection via WinRM'
            }
            if (@($conns).Count -eq 0) { Add-Item 'Connexions reseau' 'Etat' 'Aucune connexion etablie remontee' 'WinRM' }
        } 30000
    }
}
finally {
    try { Remove-WDomeniaCimSession $script:PrimarySession } catch { }
    try { Remove-WDomeniaCimSession $script:AltSession } catch { }
}

$totalWatch.Stop()
[pscustomobject]@{
    Computer = $computer
    Rows = @($rows)
    Access = @($access)
    DurationMs = [long]$totalWatch.ElapsedMilliseconds
    Success = $true
}

'@
}

function Apply-DomeniaInventoryFilter {
    try {
        $rows = @($script:InventoryRows)
        $category = [string]$script:InventoryCategory
        if (-not [string]::IsNullOrWhiteSpace($category) -and $category -ne "Toutes") {
            $rows = @($rows | Where-Object { [string]$_.Category -eq $category })
        }
        [void](Set-DomeniaItemsSource -Name "DgInventory" -Rows $rows)
    }
    catch { Add-DomeniaUiLog -Level "ERROR" -Area "Inventaire" -Text $_.Exception.Message }
}

function Update-DomeniaInventoryCategories {
    $combo = Get-DomeniaControl -Name "CmbInventoryCategory"
    if ($null -eq $combo) { return }
    $categories = New-Object System.Collections.Generic.List[string]
    [void]$categories.Add("Toutes")
    foreach ($row in @($script:InventoryRows)) {
        $c = [string]$row.Category
        if (-not [string]::IsNullOrWhiteSpace($c) -and -not $categories.Contains($c)) { [void]$categories.Add($c) }
    }
    $script:SuppressInventoryCategoryEvent = $true
    try {
        $combo.Items.Clear()
        foreach ($c in $categories) {
            $item = New-Object System.Windows.Controls.ComboBoxItem
            $item.Content = $c
            [void]$combo.Items.Add($item)
        }
        $combo.SelectedIndex = 0
        $script:InventoryCategory = "Toutes"
    }
    finally { $script:SuppressInventoryCategoryEvent = $false }
}

function Complete-DomeniaInventoryUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Access")
    if ($null -eq $effective) { throw "Resultat d inventaire vide ou invalide." }

    $script:InventoryRows = @($effective.Rows)
    $script:InventoryAccess = @($effective.Access)
    Update-DomeniaInventoryCategories
    Apply-DomeniaInventoryFilter
    [void](Set-DomeniaItemsSource -Name "DgInventoryAccess" -Rows $script:InventoryAccess)

    $ok = @($script:InventoryAccess | Where-Object { [string]$_.Status -eq "OK" }).Count
    $refused = @($script:InventoryAccess | Where-Object { [string]$_.Status -eq "REFUSE" }).Count
    $unavailable = @($script:InventoryAccess | Where-Object { [string]$_.Status -eq "INDISPONIBLE" }).Count
    $other = @($script:InventoryAccess).Count - $ok - $refused - $unavailable
    $summary = "{0} : {1} element(s) sur {2} source(s) accessibles, {3} refusee(s), {4} indisponible(s), {5} autre(s), en {6} ms." -f `
        ([string]$State.Computer),@($script:InventoryRows).Count,$ok,$refused,$unavailable,$other,([long]$effective.DurationMs)
    [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text $summary)
    Set-Status $summary
    Add-DomeniaUiLog -Area "Inventaire" -Text $summary
    $inventoryMethods = New-Object System.Collections.Generic.List[string]
    foreach($a in @($script:InventoryAccess | Where-Object { [string]$_.Status -eq "OK" })) {
        $d=[string]$a.Detail
        if([string]$a.Category -match '(?i)Fallback PsExec' -or $d -match '(?i)via PsExec|Transport PsExec'){ if(-not $inventoryMethods.Contains("PsExec")){$inventoryMethods.Add("PsExec")} }
        elseif([string]$a.Category -match '(?i)Fallback Tache|Fallback Task' -or $d -match '(?i)tache planifiee|TaskScheduler'){ if(-not $inventoryMethods.Contains("TaskScheduler")){$inventoryMethods.Add("TaskScheduler")} }
        elseif($d -match '(?i)WinRM'){ if(-not $inventoryMethods.Contains("WinRM")){$inventoryMethods.Add("WinRM")} }
        elseif($d -match '(?i)DCOM|CIM|WMI'){ if(-not $inventoryMethods.Contains("CIM/DCOM")){$inventoryMethods.Add("CIM/DCOM")} }
    }
    if($inventoryMethods.Count -gt 0){ Add-DomeniaUiLog -Area "Inventaire" -Text ("{0} : methodes d'acquisition = {1}." -f [string]$State.Computer,($inventoryMethods -join ", ")) }
    try { Register-DomeniaOperationSample -Operation "ComputerInventory" -Mode $(if([int]$effective.FallbackTasks -gt 0){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $(if([long]$effective.TaskBytes -gt 0){[long]$effective.TaskBytes}else{250000}) -RemoteAttempts 1 -FallbackTasks ([int]$effective.FallbackTasks) -SuccessCount $(if([bool]$effective.Success){1}else{0}) -FailureCount $(if([bool]$effective.Success){0}else{1}) } catch { }
}

function Fail-DomeniaInventoryUi {
    param($Message,$State)
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text ("Inventaire impossible : " + $detail))
    Set-Status ("Inventaire impossible : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "Inventaire" -Level "ERROR" -Text $detail
}

function Start-DomeniaComputerInventory {
    param([switch]$Deep)
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") {
            Set-Status "Selectionne une machine avant de lancer l inventaire." "WARN"
            return
        }
        $computer = Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName)
        $script:InventoryRows = @()
        $script:InventoryAccess = @()
        [void](Set-DomeniaItemsSource -Name "DgInventory" -Rows @())
        [void](Set-DomeniaItemsSource -Name "DgInventoryAccess" -Rows @())
        $mode = "rapide"
        if ($Deep) { $mode = "complet" }
        [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text ("Inventaire " + $mode + " en cours sur " + $computer + "..."))

        # Le budget interne doit rester nettement inferieur au delai de la
        # tache : le worker s arrete de lui-meme et rend un resultat partiel,
        # au lieu d etre tue et de tout perdre.
        $budget = 55000
        $softwareKeys = 250
        $timeout = 110
        if ($Deep) { $budget = 150000; $softwareKeys = 1200; $timeout = 260 }

        Start-UiTask `
            -Name "Inventaire poste" `
            -OperationId "ComputerInventory" `
            -Code (Get-DomeniaInventoryWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; Deep=[bool]$Deep; BudgetMs=$budget; MaxSoftwareKeys=$softwareKeys; PreferWinrm=[bool](Get-CfgValue "Inventory" "PreferWinrm" $false) }) `
            -CallbackState ([pscustomobject]@{ Computer=$computer; DN=[string]$script:SelectedObject.DN }) `
            -ReplaceKey "inventory" `
            -DisableControls @("BtnRunInventory","BtnRunInventoryDeep") `
            -TimeoutSeconds $timeout `
            -StatusText ("Inventaire " + $mode + " de " + $computer + " en arriere-plan...") `
            -SuccessHandler "Complete-DomeniaInventoryUi" `
            -ErrorHandler "Fail-DomeniaInventoryUi" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Inventaire poste" -ErrorRecordOrException $_) }
}

function Get-DomeniaInventoryReportText {
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("=== INVENTAIRE POSTE ===")
    $current = ""
    foreach ($row in @($script:InventoryRows)) {
        $c = [string]$row.Category
        if ($c -ne $current) { $current = $c; [void]$lines.Add(""); [void]$lines.Add("[" + $c + "]") }
        [void]$lines.Add(("  {0} = {1}" -f [string]$row.Item,[string]$row.Value))
    }
    [void]$lines.Add("")
    [void]$lines.Add("=== RAPPORT D ACCES ===")
    foreach ($row in @($script:InventoryAccess)) {
        [void]$lines.Add(("  {0,-26} {1,-14} {2,4} element(s) {3,6} ms  {4}" -f `
            [string]$row.Category,[string]$row.Status,[int]$row.Items,[int]$row.DurationMs,[string]$row.Detail))
    }
    return ([string]::Join([Environment]::NewLine,$lines.ToArray()))
}

function Copy-DomeniaInventory {
    if (@($script:InventoryRows).Count -eq 0 -and @($script:InventoryAccess).Count -eq 0) {
        Set-Status "Aucun inventaire a copier." "WARN"
        return
    }
    Set-ClipboardSafe (Get-DomeniaInventoryReportText)
    Set-Status "Inventaire copie dans le presse-papiers."
}

function Export-DomeniaInventory {
    try {
        if (@($script:InventoryRows).Count -eq 0) { Set-Status "Aucun inventaire a exporter." "WARN"; return }
        $dir = Join-Path ([string]$script:DataDir) "Diagnostics"
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
        $stamp = (Get-Date).ToString("yyyyMMdd-HHmmss")
        $computer = "poste"
        try { $computer = [string]$script:InventoryRows[0].Value } catch { }
        $path = Join-Path $dir ("Domenia-inventaire-" + $stamp + ".csv")
        @($script:InventoryRows) | ConvertTo-DomeniaSpreadsheetSafeRow | Export-Csv -LiteralPath $path -NoTypeInformation -Encoding UTF8
        $accessPath = Join-Path $dir ("Domenia-inventaire-acces-" + $stamp + ".csv")
        @($script:InventoryAccess) | ConvertTo-DomeniaSpreadsheetSafeRow | Export-Csv -LiteralPath $accessPath -NoTypeInformation -Encoding UTF8
        Set-Status ("Inventaire exporte : " + $path)
        Add-DomeniaUiLog -Area "Inventaire" -Text ("Export CSV : " + $path + " et " + $accessPath)
        [void](Show-InfoBox ("Inventaire exporte." + [Environment]::NewLine + [Environment]::NewLine + $path + [Environment]::NewLine + $accessPath))
    }
    catch { [void](Show-DomeniaOperationError -Operation "Export de l inventaire" -ErrorRecordOrException $_) }
}


# =====================================================================
# Vue domaine : lecture seule. Chaque section est isolee afin qu un refus
# de droits sur l une n empeche pas les autres de remonter.
# =====================================================================
function Get-DomeniaDomainWorkerCode {
    return @'
$rows = New-Object Collections.ArrayList
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$count = [bool]$Payload.Count
$baseDn = [string]$Context.BaseDn
if ([string]::IsNullOrWhiteSpace($baseDn)) { throw 'Base DN vide : analyse du domaine impossible.' }

function Add-Row {
    param([string]$Category,[string]$Name,$Value,[string]$Status = 'OK')
    $text = ''
    if ($null -ne $Value) { $text = ([string]$Value).Trim() }
    if ([string]::IsNullOrWhiteSpace($text)) { $text = '(vide)' }
    [void]$rows.Add([pscustomobject]@{ Category=$Category; Item=$Name; Value=$text; Status=$Status })
}
function Invoke-Section {
    param([string]$Category,[scriptblock]$Action)
    $before = $rows.Count
    try {
        & $Action
        if ($rows.Count -eq $before) { Add-Row $Category 'Resultat' 'Aucune donnee retournee' 'VIDE' }
    }
    catch {
        $message = [string]$_.Exception.Message
        $status = 'ERREUR'
        if ($message -match '(?i)access|denied|refus|droit') { $status = 'REFUSE' }
        elseif ($message -match '(?i)introuvable|not found|invalid|inexistant') { $status = 'INDISPONIBLE' }
        Add-Row $Category 'Erreur' $message $status
    }
}
function Get-BehaviorLabel {
    param($Value)
    $v = -1
    try { $v = [int]$Value } catch { return 'Inconnu' }
    switch ($v) {
        0 { return 'Windows 2000' }
        1 { return 'Windows Server 2003 interim' }
        2 { return 'Windows Server 2003' }
        3 { return 'Windows Server 2008' }
        4 { return 'Windows Server 2008 R2' }
        5 { return 'Windows Server 2012' }
        6 { return 'Windows Server 2012 R2' }
        7 { return 'Windows Server 2016' }
        default { return ('Niveau ' + $v) }
    }
}
function Convert-Duration {
    param($Value)
    $ticks = Convert-WLargeInteger $Value
    if ($ticks -eq 0) { return 'Jamais' }
    try {
        $span = [TimeSpan]::FromTicks([Math]::Abs($ticks))
        if ($span.TotalDays -ge 1) { return ('' + [Math]::Round($span.TotalDays,2) + ' jour(s)') }
        if ($span.TotalHours -ge 1) { return ('' + [Math]::Round($span.TotalHours,2) + ' heure(s)') }
        return ('' + [Math]::Round($span.TotalMinutes,1) + ' minute(s)')
    }
    catch { return [string]$ticks }
}

$rootDse = $null
$configNc = ''
$schemaNc = ''
try {
    $rootDse = New-WRootDse $Context
    $rootDse.RefreshCache(@('defaultNamingContext','configurationNamingContext','schemaNamingContext','rootDomainNamingContext','dnsHostName','serverName','domainFunctionality','forestFunctionality','domainControllerFunctionality','supportedCapabilities','highestCommittedUSN','currentTime','namingContexts'))
    $configNc = [string]$rootDse.Properties['configurationNamingContext'].Value
    $schemaNc = [string]$rootDse.Properties['schemaNamingContext'].Value
}
catch { }

