function Add-UserMachineLinkIfMissing {
    param([string]$UserLogin,[string]$Computer,[string]$Source="Manual",[string]$Details="",[int]$Confidence=100,[bool]$VerifiedInAD=$true,[string]$UserGuid="",[string]$ComputerGuid="",[string]$UserDn="",[string]$ComputerDn="",[string]$Declarant="")
    try {
        $u=Normalize-LinkUser $UserLogin; $c=Normalize-LinkComputer $Computer
        if ([string]::IsNullOrWhiteSpace($u) -or [string]::IsNullOrWhiteSpace($c)) { return $false }
        $userRow = Find-DomeniaCachedUserRow -Login $u -Guid $UserGuid
        $computerRow = Find-DomeniaCachedComputerRow -Computer $c -Guid $ComputerGuid
        $userGuid = if ($UserGuid) { $UserGuid } elseif ($null -ne $userRow) { [string]$userRow.Guid } else { "" }
        $computerGuid = if ($ComputerGuid) { $ComputerGuid } elseif ($null -ne $computerRow) { [string]$computerRow.Guid } else { "" }
        $userDn = if ($UserDn) { $UserDn } elseif ($null -ne $userRow) { [string]$userRow.DN } else { "" }
        $computerDn = if ($ComputerDn) { $ComputerDn } elseif ($null -ne $computerRow) { [string]$computerRow.DN } else { "" }
        if ($null -ne $userRow -and $null -ne $computerRow) { $VerifiedInAD = $true }

        if (Get-DomeniaFeatureFlag 'RelationsSymmetry' $true) {
            # D042/D049/D050: one relation per user, workstation and nature (Resolve-DomeniaRelationUpsert in
            # Add-DomeniaRelation). Another account on the same workstation never overwrites a relation, a declared
            # assignment is never replaced by an observation, and no fixed score is stored (Confidence=0, unmeasured).
            $incoming = [pscustomobject]@{ UserLogin=$u; Computer=$c; Source=$Source; Confidence=0; VerifiedInAD=$VerifiedInAD; When=(Get-Date -Format "yyyy-MM-dd HH:mm:ss"); Details=$Details; UserGuid=$userGuid; ComputerGuid=$computerGuid; UserDn=$userDn; ComputerDn=$computerDn; Kind=(Get-DomeniaRelationKind $Source) }
            $outcome = Add-DomeniaRelation -Relation $incoming -Declarant $Declarant
            $badge = Get-DomeniaEvidenceBadge $incoming
            if ($outcome.SaveFailed) { $msg = "Lien non enregistre : $u -> $c. $($outcome.Reason)"; Set-Status $msg "WARN"; Write-AppLog $msg "WARN"; return $false }
            if ($outcome.Action -eq 'Refresh') { Write-AppLog "Lien actualise : $u -> $c ($Source, $($badge.Badge))." "INFO"; Refresh-AssociationContext; return $false }
            if ($outcome.Placement -eq 'Session') { $msg = "Relation $u -> $c ($Source, $($badge.Badge)) conservee pour la session. $($outcome.Reason)"; Set-Status $msg; Write-AppLog $msg "INFO"; Refresh-AssociationContext; return $false }
            $msg = "Lien ajoute : $u -> $c ($Source, $($badge.Badge))."
            if ($outcome.Placement -eq 'Replace' -and $null -ne $outcome.Demoted) { $msg += " Relation precedente ($([string]$outcome.Demoted.UserLogin)) conservee pour la session." }
            Set-Status $msg; [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $msg); Write-AppLog $msg
            return $true
        }

        $existing=Get-ExistingLinkForComputer $c
        if ($null -ne $existing) {
            $sameUser = ((Normalize-LinkUser ([string]$existing.UserLogin)) -ieq $u)
            $existingConfidence = 0
            try { $existingConfidence = [int]$existing.Confidence } catch { }
            $existingSource = [string]$existing.Source
            $isManualExisting = ($existingSource -match '^(?i:Saisie manuelle|Manual)')
            $isManualNew = ([string]$Source -match '^(?i:Saisie manuelle|Manual)')
            $ageHours = 99999.0
            try { $ageHours = ((Get-Date) - [datetime]([string]$existing.When)).TotalHours } catch { }
            $staleHours = [double](Get-CfgValue "UserMachineLink" "LinkStaleHours" 24)
            $mayReplace = $isManualNew -or ((-not $isManualExisting) -and ($Confidence -ge $existingConfidence -or $ageHours -ge $staleHours))

            if($isManualExisting -and -not $isManualNew){
                Write-AppLog ("Association manuelle conservée pour "+$c+" ; observation distincte non substituée.") 'INFO'
                return $false
            }
            if ($sameUser) {
                if ($Confidence -ge $existingConfidence -or $ageHours -ge $staleHours -or $isManualNew) {
                    $existing.Source=$Source; $existing.Confidence=$Confidence; $existing.VerifiedInAD=$VerifiedInAD; $existing.When=(Get-Date -Format "yyyy-MM-dd HH:mm:ss"); $existing.Details=$Details
                    foreach ($pair in @(@('UserGuid',$userGuid),@('ComputerGuid',$computerGuid),@('UserDn',$userDn),@('ComputerDn',$computerDn))) {
                        if ($existing.PSObject.Properties.Name -notcontains $pair[0]) { $existing | Add-Member -NotePropertyName $pair[0] -NotePropertyValue $pair[1] } else { $existing.PSObject.Properties[[string]$pair[0]].Value = $pair[1] }
                    }
                    [void](Save-UserMachineLinks)
                    Write-AppLog "Lien actualise : $u -> $c ($Source, confiance $Confidence)." "INFO"
                }
                Refresh-AssociationContext
                return $false
            }

            if (-not $mayReplace) {
                $msg="Lien conserve pour $c : $($existing.UserLogin) ($existingSource, confiance $existingConfidence). Nouvelle observation $u ignoree car moins fiable ou lien manuel."
                Set-Status $msg; Write-AppLog $msg "INFO"; Refresh-AssociationContext
                return $false
            }

            $oldUser=[string]$existing.UserLogin
            $existing.UserLogin=$u; $existing.Source=$Source; $existing.Confidence=$Confidence; $existing.VerifiedInAD=$VerifiedInAD; $existing.When=(Get-Date -Format "yyyy-MM-dd HH:mm:ss"); $existing.Details=$Details
            foreach ($pair in @(@('UserGuid',$userGuid),@('ComputerGuid',$computerGuid),@('UserDn',$userDn),@('ComputerDn',$computerDn))) {
                if ($existing.PSObject.Properties.Name -notcontains $pair[0]) { $existing | Add-Member -NotePropertyName $pair[0] -NotePropertyValue $pair[1] } else { $existing.PSObject.Properties[[string]$pair[0]].Value = $pair[1] }
            }
            [void](Save-UserMachineLinks)
            $msg="Lien mis a jour : $c passe de $oldUser a $u ($Source, confiance $Confidence)."
            Set-Status $msg; Write-AppLog $msg "INFO"
            return $true
        }

        $item=[pscustomobject]@{ UserLogin=$u; Computer=$c; Source=$Source; Confidence=$Confidence; VerifiedInAD=$VerifiedInAD; When=(Get-Date -Format "yyyy-MM-dd HH:mm:ss"); Details=$Details; UserGuid=$userGuid; ComputerGuid=$computerGuid; UserDn=$userDn; ComputerDn=$computerDn }
        $previousLinks = @($script:UserMachineLinks)
        $script:UserMachineLinks=@($script:UserMachineLinks)+$item
        if (-not (Save-UserMachineLinks)) {
            $script:UserMachineLinks = $previousLinks
            Rebuild-UserMachineLinkIndex
            return $false
        }
        $msg="Lien ajoute : $u -> $c ($Source, confiance $Confidence)."
        Set-Status $msg; try { $script:Ctrl["LblLinkProbeStatus"].Text=$msg } catch { }; Write-AppLog $msg
        return $true
    }
    catch {
        $detail = "Erreur ajout lien user-machine : $($_.Exception.Message)"
        Write-AppLog $detail "ERROR"
        Set-Status $detail "ERROR"
        [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $detail)
        return $false
    }
}

function Remove-SelectedLink {
    try {
        if(Test-DomeniaAccessBusyWrite){return}
        $activeGrid=Get-DomeniaRelationsActiveGrid
        $row=if($null -ne $activeGrid){$activeGrid.SelectedItem}else{$null}
        if ($null -eq $row) { Set-Status "Selectionne un lien a supprimer." "WARN"; return }
        if (Get-DomeniaFeatureFlag 'RelationsSymmetry' $true) {
            # D050: the removal is journaled (declarant, source, dates) and can be restored; AD is never touched.
            # The exact row is removed, not every row sharing its login, workstation and date.
            Request-DomeniaRelationRemoval -Relation $row
            return
        }
        if (-not (Confirm-Action "Supprimer ce lien user-machine ?`n$($row.UserLogin) -> $($row.Computer)")) { return }
        $previousLinks = @($script:UserMachineLinks)
        $script:UserMachineLinks = @($script:UserMachineLinks | Where-Object { -not (($_.UserLogin -eq $row.UserLogin) -and ($_.Computer -eq $row.Computer) -and ($_.When -eq $row.When)) })
        if (-not (Save-UserMachineLinks)) {
            $script:UserMachineLinks = $previousLinks
            Rebuild-UserMachineLinkIndex
            Refresh-LinkGrid
            return
        }
        Set-Status "Lien user-machine supprime."
    }
    catch { Show-ErrorBox "Erreur suppression lien : $($_.Exception.Message)" }
}


function Show-DomeniaCommandPalette {
    $window = New-Object System.Windows.Window
    $window.Title = "DOMENIA  Actions rapides"
    $window.Width = 620
    $window.Height = 520
    $window.MinWidth = 520
    $window.MinHeight = 420
    $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    $window.ResizeMode = [System.Windows.ResizeMode]::CanResize
    $window.Background = [System.Windows.Media.Brushes]::White
    try { $owner=Get-DomeniaDialogOwner; if($null -ne $owner){$window.Owner=$owner} } catch {}
    $root=New-Object System.Windows.Controls.Grid
    $root.Margin="18"
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{Height="Auto"}))
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{Height="Auto"}))
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{Height="*"}))
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{Height="Auto"}))
    $title=New-Object System.Windows.Controls.TextBlock
    $title.Text="Actions rapides"
    $title.FontSize=20
    $title.FontWeight=[System.Windows.FontWeights]::SemiBold
    [void]$root.Children.Add($title)
    $search=New-Object System.Windows.Controls.TextBox
    $search.Margin="0,12,0,12"
    $search.Height=34
    $search.VerticalContentAlignment="Center"
    $search.ToolTip="Tape quelques lettres pour filtrer les actions."
    [System.Windows.Controls.Grid]::SetRow($search,1)
    [void]$root.Children.Add($search)
    $list=New-Object System.Windows.Controls.ListBox
    [System.Windows.Controls.Grid]::SetRow($list,2)
    [void]$root.Children.Add($list)
    $items=@(
        [pscustomobject]@{Name="Rechercher dans Active Directory";Key="search"},
        [pscustomobject]@{Name="Revenir a la racine du domaine";Key="root"},
        [pscustomobject]@{Name="Actualiser l'arborescence";Key="refresh"},
        [pscustomobject]@{Name="Copier le resume de l'objet";Key="summary"},
        [pscustomobject]@{Name="Ouvrir le conteneur parent";Key="parent"},
        [pscustomobject]@{Name="Diagnostic reseau de la selection";Key="batch"},
        [pscustomobject]@{Name="Lancer l'auto-verification DOMENIA";Key="selfcheck"},
        [pscustomobject]@{Name="Ouvrir la gestion des comptes";Key="accounts"},
        [pscustomobject]@{Name="Ouvrir les relations utilisateur / poste";Key="relations"},
        [pscustomobject]@{Name="Ouvrir le journal detaille";Key="log"},
        [pscustomobject]@{Name="Atelier : comprendre la fiche";Key="support"},
        [pscustomobject]@{Name="Atelier : comparer les captures";Key="supportdiff"}
    )
    foreach($i in $items){[void]$list.Items.Add($i)}
    $list.DisplayMemberPath="Name"
    $footer=New-Object System.Windows.Controls.TextBlock
    $footer.Text="Entree : executer      Echap : fermer      Ctrl+F : recherche      F5 : arborescence"
    $footer.Foreground=[System.Windows.Media.Brushes]::Gray
    $footer.Margin="0,12,0,0"
    [System.Windows.Controls.Grid]::SetRow($footer,3)
    [void]$root.Children.Add($footer)
    $refresh={
        $term=([string]$search.Text).Trim()
        $list.Items.Clear()
        foreach($i in $items){
            if([string]::IsNullOrWhiteSpace($term) -or ([string]$i.Name).IndexOf($term,[StringComparison]::OrdinalIgnoreCase) -ge 0){[void]$list.Items.Add($i)}
        }
        if($list.Items.Count -gt 0){$list.SelectedIndex=0}
    }
    $search.Add_TextChanged($refresh)
    $run={
        $item=$list.SelectedItem
        if($null -eq $item){return}
        Set-DomeniaSurfaceResult $window $true
        switch([string]$item.Key){
            "search" { $c=Get-DomeniaControl -Name "TxtGlobalSearch"; if($null -ne $c){$c.Focus();$c.SelectAll()} }
            "root" { Go-RootBranch }
            "refresh" { Load-TreeRoot -ForceRefresh }
            "summary" { Copy-ObjectSummary }
            "parent" { Open-SelectedParentBranch }
            "batch" { Show-DomeniaBatchNetworkReport -Rows (Get-DomeniaSelectedMachineRows) }
            "selfcheck" { Start-SelfCheck }
            "accounts" { Select-DomeniaWorkspace -Workspace "TabAccounts"; Update-DomeniaAccountUi }
            "relations" { Select-DomeniaWorkspace -Workspace "TabRelations"; Refresh-LinkGrid }
            "log" { Select-DomeniaWorkspace -Workspace "TabApplicationTools" -Inner "ApplicationToolTabs" -Tab "TabLog" }
            "support" { Invoke-DomeniaSafeUiAction -Operation "Atelier" -Action { Select-DomeniaWorkspace -Workspace "TabSupport" -Inner "SupportTabs" -Tab "SupportAnalysisTab"; Update-DomeniaSupportView -Force } }
            "supportdiff" { Select-DomeniaWorkspace -Workspace "TabSupport" -Inner "SupportTabs" -Tab "SupportCompareTab" }
        }
    }
    $list.Add_MouseDoubleClick({&$run})
    $search.Add_KeyDown({param($s,$e) if($e.Key -eq "Enter"){&$run;$e.Handled=$true}elseif($e.Key -eq "Down"){ $list.Focus(); if($list.Items.Count -gt 0){$list.SelectedIndex=0};$e.Handled=$true }elseif($e.Key -eq "Escape"){$window.Close();$e.Handled=$true}})
    $list.Add_KeyDown({param($s,$e) if($e.Key -eq "Enter"){&$run;$e.Handled=$true}elseif($e.Key -eq "Escape"){$window.Close();$e.Handled=$true}})
    # Copy the host resources for this owned window; native styles preserve selection contrast.
    if ($null -ne $script:Window) {
        foreach ($key in $script:Window.Resources.Keys) { $window.Resources[$key]=$script:Window.Resources[$key] }
        $window.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty,'WindowBg')
        $window.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty,'TextColor')
        $search.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty,'BgInput')
        $search.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty,'TextColor')
        $list.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty,'BgCard')
        $list.SetResourceReference([System.Windows.Controls.Control]::ForegroundProperty,'TextColor')
        $footer.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty,'MutedColor')
    }
    $window.Content=$root
    Register-DomeniaSurfaceReady $window ({$search.Focus();$list.SelectedIndex=0})
    [void](Invoke-DomeniaHostWindow -Window $window)
}


function Get-DomeniaCredentialUserName {
    param($Credential)
    try {
        if ($null -ne $Credential) { return ([string]$Credential.UserName).Trim() }
    } catch { }
    return ""
}

function New-DomeniaAccountAuthRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$UserName,
        [Parameter(Mandatory=$true)][System.Security.SecureString]$Password,
        [ValidateRange(2,45)][int]$TimeoutSeconds = 8
    )
    $user = ([string]$UserName).Trim()
    if ([string]::IsNullOrWhiteSpace($user)) { throw 'Identifiant vide.' }
    if ($null -eq $Password -or $Password.Length -eq 0) { throw 'Mot de passe vide.' }
    if ($null -eq $script:Conn) { throw 'Connecte-toi a Active Directory avant de tester un compte secondaire.' }
    if ([bool]$script:DemoMode) {
        # D003: alternate account in demonstration. The typed password never leaves this panel: the request
        # carries no credential and the authentication runspace answers from the demo identity only.
        if (-not (Test-DomeniaDemoIdentity $user)) { throw 'Identite de demonstration attendue (DEMO\nom).' }
        return [pscustomobject]@{
            Login=$user; Credential=$null; UseCurrentCredentials=$false; DemoOnly=$true; DemoIdentity=$user
            ConfiguredServer=''; ConfiguredBase=([string]$script:Conn.BaseDn).Trim()
            Domain=[string]$script:Conn.Domain; Netbios=[string]$script:Conn.Netbios
            MaxServers=1; OverallTimeoutSeconds=$TimeoutSeconds; PerServerTimeoutSeconds=$TimeoutSeconds
        }
    }
    $server = ([string]$script:Conn.Server).Trim()
    $baseDn = ([string]$script:Conn.BaseDn).Trim()
    if ([string]::IsNullOrWhiteSpace($server) -or [string]::IsNullOrWhiteSpace($baseDn)) {
        throw 'Contexte AD incomplet : reconnecte DOMENIA pour obtenir le controleur et la base AD.'
    }
    # Reutiliser exactement le moteur du login et son contexte deja decouvert.
    # Aucun mot de passe utilise pour essayer une succession de domaines/identites.
    # Copie privee : la fermeture du champ WPF ne peut pas invalider le worker.
    $passwordCopy = $Password.Copy()
    try {
        $passwordCopy.MakeReadOnly()
        $credential = [System.Management.Automation.PSCredential]::new($user,$passwordCopy)
        return [pscustomobject]@{
            Login=$user; Credential=$credential; UseCurrentCredentials=$false
            ConfiguredServer=$server; ConfiguredBase=$baseDn
            Domain=[string]$script:Conn.Domain; Netbios=[string]$script:Conn.Netbios
            MaxServers=1; OverallTimeoutSeconds=$TimeoutSeconds; PerServerTimeoutSeconds=$TimeoutSeconds
        }
    }
    catch { $passwordCopy.Dispose(); throw }
}

function Test-DomeniaCredentialBind {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$UserName,[Parameter(Mandatory=$true)][Security.SecureString]$Password,[string]$Operation='Test du compte',[ValidateRange(2,45)][int]$TimeoutSeconds=12)
    return Start-DomeniaAccountValidation -UserName $UserName -Password $Password -Operation $Operation -TimeoutSeconds $TimeoutSeconds
}

function Test-DomeniaActiveDirectoryCredential {
    [CmdletBinding()]
    param([string]$UserName)
    $credential = $script:Conn.Credential
    if ($null -eq $credential) { throw 'Aucun compte AD explicite actif. Utilise Relogger...' }
    $activeUser = ([string]$credential.UserName).Trim()
    $requestedUser = ([string]$UserName).Trim()
    if ([string]::IsNullOrWhiteSpace($requestedUser)) { throw 'Identifiant AD vide.' }
    $sameIdentity = ($requestedUser -ieq $activeUser)
    if (-not $sameIdentity -and -not $requestedUser.Contains('\') -and -not $requestedUser.Contains('@')) {
        $netbios = ([string]$script:Conn.Netbios).Trim()
        $sameIdentity = (-not [string]::IsNullOrWhiteSpace($netbios) -and ("$netbios\$requestedUser" -ieq $activeUser))
    }
    if (-not $sameIdentity) {
        throw 'Le champ identifiant AD a ete modifie. Utilise Utiliser / relogger pour ce nouveau compte. Le mot de passe de la session active ne sera jamais teste sous un autre nom.'
    }
    return Test-DomeniaCredentialBind -UserName $activeUser -Password $credential.Password -Operation 'Test compte AD'
}

function Update-DomeniaAccountUi {
    # IMPORTANT : cette fonction ne touche JAMAIS aux champs editables.
    # Les evenements GotFocus/Click remontent depuis les enfants du TabItem ;
    # recharger TxtAccount* ici effacait donc la saisie des que l utilisateur
    # changeait de champ ou cliquait sur Tester/Activer.
    try {
        $ad = Get-DomeniaControl -Name "LblAccountAdIdentity"
        $adStatus = Get-DomeniaControl -Name "LblAccountAdStatus"
        $remote = Get-DomeniaControl -Name "LblAccountRemoteIdentity"
        $remoteStatus = Get-DomeniaControl -Name "LblAccountRemoteStatus"
        $secrets = Get-DomeniaControl -Name "LblAccountSecretsIdentity"
        $secretsStatus = Get-DomeniaControl -Name "LblAccountSecretsStatus"

        Update-DomeniaExperienceIdentity
        $currentAd = [string]$script:Conn.BindUser
        if ([string]::IsNullOrWhiteSpace($currentAd)) { $currentAd = [string]$script:Conn.User }
        if ($null -ne $ad) { $ad.Text = if ($currentAd) { "$currentAd  |  $([string]$script:Conn.Server)" } else { "Aucune identite active." } }
        if ($null -ne $adStatus) { $adStatus.Text = if ($currentAd) { "Compte actuellement utilise pour les operations AD." } else { "Aucune connexion AD active." } }

        $remoteCred = $script:RemoteAdminCredential
        $remoteName = Get-DomeniaCredentialUserName $remoteCred
        if ($null -ne $remote) { $remote.Text = if ($remoteName) { "$remoteName  |  compte distant actif" } else { "Repli sur le compte AD courant." } }
        if ($null -ne $remoteStatus) { $remoteStatus.Text = if ($remoteName) { "Les operations poste utilisent ce compte en priorite. Mot de passe uniquement en memoire." } else { "Aucun compte poste dedie. DOMENIA reutilise le compte AD courant." } }

        $secretCred = $script:SecretsCredential
        $secretName = Get-DomeniaCredentialUserName $secretCred
        if ($null -ne $secrets) { $secrets.Text = if ($secretName) { "$secretName  |  compte secrets actif" } else { "Repli sur le compte AD courant." } }
        if ($null -ne $secretsStatus) { $secretsStatus.Text = if ($secretName) { "LAPS et BitLocker utilisent ce compte en priorite. Mot de passe uniquement en memoire." } else { "Aucun compte secrets dedie. DOMENIA reutilise le compte AD courant." } }

        try {
            $remoteClear = Get-DomeniaControl -Name "BtnAccountRemoteClear"
            $secretClear = Get-DomeniaControl -Name "BtnAccountSecretsClear"
            if ($null -ne $remoteClear) { $remoteClear.IsEnabled = ($null -ne $remoteCred) }
            if ($null -ne $secretClear) { $secretClear.IsEnabled = ($null -ne $secretCred) }
        } catch { }
    }
    catch { Write-AppLog "Mise a jour du panneau Comptes impossible : $($_.Exception.Message)" "WARN" }
}

function Save-DomeniaSecondaryCredential {
    [CmdletBinding()]
    param([ValidateSet('Remote','Secrets')][string]$Scope,[string]$UserName,[Security.SecureString]$Password)
    [void](Start-DomeniaAccountValidation -UserName $UserName -Password $Password -Operation ('Activation compte '+$Scope) -ActivateScope $Scope)
}

function Clear-DomeniaSecondaryCredential {
    param([ValidateSet("Remote","Secrets")][string]$Scope)
    if ($Scope -eq "Remote") {
        $script:RemoteAdminCredential = $null
        Set-DomeniaSetting -Name "RemoteCredentialUser" -Value ""
        $pwd = Get-DomeniaControl -Name "PwdAccountRemote"; if ($null -ne $pwd) { $pwd.Password = "" }
        Add-DomeniaUiLog -Area "Comptes" -Text "Compte Remote efface de la memoire."
    } else {
        $script:SecretsCredential = $null
        Set-DomeniaSetting -Name "SecretsCredentialUser" -Value ""
        $pwd = Get-DomeniaControl -Name "PwdAccountSecrets"; if ($null -ne $pwd) { $pwd.Password = "" }
        Add-DomeniaUiLog -Area "Comptes" -Text "Compte Secrets efface de la memoire."
    }
    if($null -ne $script:AccessState){
        $scopes=if($Scope -eq 'Secrets'){@('ReadLaps','ReadBitLocker')}else{@('Remote')}
        foreach($k in $scopes){[void]$script:AccessState.Credentials.Remove($k);[void]$script:AccessState.Faults.Remove($k)}
        if($Scope -eq 'Secrets'){$script:AccessState.Denied=@{}}
    }
    Update-DomeniaAccountUi
    Set-Status "Compte $Scope efface. Repli sur le compte AD courant."
}

function Start-DomeniaAccountRelogin {
    try {
        Complete-DomeniaDetachedReadJobs
        if (@($script:AsyncJobs.Keys).Count -gt 0 -or @($script:DetachedReadJobs).Count -gt 0) {
            Show-InfoBox 'Changement de compte refuse pendant une operation. Termine ou annule les lectures, puis attends leur nettoyage. Une ecriture envoyee au DC ne doit pas etre interrompue.'
            return
        }
        if ([string]$script:WriteState -in @('Running','Unknown','UnknownPending')) {
            Show-InfoBox 'Une ecriture reste a verifier. Recontrole son resultat avant de changer de session.'
            return
        }
        # Persist dirty data using the previous connection scope, before opening the login.
        if ([bool]$script:IndexDirty -and -not (Flush-DomeniaIndex)) {
            throw 'Le cache modifie ne peut pas etre enregistre. Changement de session interrompu pour conserver les donnees en memoire.'
        }
        $previousBase = [string]$script:Conn.BaseDn
        $user = ([string](Get-DomeniaControl -Name 'TxtAccountAdUser').Text).Trim()
        if (-not [string]::IsNullOrWhiteSpace($user)) { Set-DomeniaSetting -Name 'LastLogin' -Value $user }
        try { if ($null -ne $script:LiveSearchTimer) { $script:LiveSearchTimer.Stop() } } catch { }
        Stop-DomeniaSelectionOpenTimer
        if (-not (Show-LoginWindow)) { Set-Status 'Relogin annule. La session courante est conservee.' 'WARN'; return }

        $script:SessionEpoch = [long]$script:SessionEpoch + 1
    try { Reset-DomeniaSupportSession } catch { }
        $script:GlobalSearchGeneration++
        $script:PresenceScanGeneration++
        $script:SelectedObjectGeneration++
        Clear-DomeniaTreeRenderJobs
        Clear-Secrets
        Clear-ObjectDetails
        $script:SelectedObject = $null
        $script:LastLoadedEntry = $null
        $script:PendingObjectSelection = $null
        $script:CurrentObjectRequestId = ''
        $script:CurrentObjectRequestDn = ''
        $script:DeferredRawDn = ''; $script:DeferredPermissionsDn = ''; $script:DeferredTargetDn = ''
        $script:VisitCache = @{}; $script:PresenceCache = @{}
        $script:StartupWarmCache = $null; $script:ShowingCachedObject = $false
        $script:ActualSecretDeniedDn = ''; $script:ComputerDiagRows = @()
        $script:LinkIndexGeneration++
        $script:CurrentCapabilities = @{}; $script:ActualDeniedCapabilities = @{}
        $script:PermissionRows = @(); $script:SelfCheckRows = @()
        $script:IndexRows = @(); $script:IndexInfo = $null; $script:IndexDirty = $false
        $script:IndexUsersByLogin = @{}; $script:IndexUsersByGuid = @{}
        $script:IndexComputersByName = @{}; $script:IndexComputersByGuid = @{}
        $script:UserMachineLinks = @(); $script:LinkByComputer = @{}; $script:LinksByUser = @{}; $script:LinkIndexCount = -1
        $script:ParkState = @{}
        $script:InventoryRows = @(); $script:InventoryAccess = @()
        $script:SoftwareRows = @(); $script:SoftwareAccess = @()
        $script:DomainRows = @(); $script:WmiNamespaces = @(); $script:WmiClasses = @(); $script:WmiSchema = @(); $script:WmiInstances = @()
        $script:WorkerContextStatic = $null
        $script:DirectoryCredentialFaulted = $false; $script:DirectoryCredentialFaultMessage = ''
        $script:DatabaseScopeIdentity = ''; $script:DatabaseScopedPath = ''; $script:DomeniaDatabaseReady = $false
        $script:ReadOnlyMode = $true
        $readOnly = Get-DomeniaControl -Name 'ChkReadOnlyMode'
        if ($null -ne $readOnly) { $readOnly.IsChecked = $true }
        # Clear all previously bound result grids, including cached permission reports.
        foreach ($control in @($script:Ctrl.Values)) {
            if ($control -is [System.Windows.Controls.DataGrid]) { $control.ItemsSource = $null }
        }
        if ($previousBase -ine [string]$script:Conn.BaseDn) {
            $script:RemoteAdminCredential = $null; $script:SecretsCredential = $null; $script:MachineCredential = $null
            Add-DomeniaUiLog -Area 'Comptes' -Level 'WARN' -Text 'Perimetre AD change : comptes secondaires retires pour eviter leur envoi dans un autre domaine.'
        }
        [void](Load-DomeniaIndexMetadata)
        Load-UserMachineLinks
        Load-TreeRoot
        Update-DomeniaAccountUi
        Apply-CurrentPermissionUi
        Request-DomeniaDashboardRefresh
        Set-Status ('Nouvelle session AD : ' + [string]$script:Conn.BindUser + '. Vues rechargees, lecture seule active.')
    }
    catch { [void](Show-DomeniaOperationError -Operation 'Relogin AD' -ErrorRecordOrException $_) }
}

function Initialize-DomeniaAccountPanel {
    try {
        $savedRemote = [string](Get-DomeniaSetting "RemoteCredentialUser" "")
        $savedSecrets = [string](Get-DomeniaSetting "SecretsCredentialUser" "")
        $currentAd = [string]$script:Conn.BindUser
        if ([string]::IsNullOrWhiteSpace($currentAd)) { $currentAd = [string]$script:Conn.User }
        $adUser = Get-DomeniaControl -Name "TxtAccountAdUser"
        $remoteUser = Get-DomeniaControl -Name "TxtAccountRemoteUser"
        $secretUser = Get-DomeniaControl -Name "TxtAccountSecretsUser"
        if ($null -ne $adUser) { $adUser.Text = $currentAd }
        if ($null -ne $remoteUser) { $remoteUser.Text = if ($savedRemote) { $savedRemote } else { $currentAd } }
        if ($null -ne $secretUser) { $secretUser.Text = if ($savedSecrets) { $savedSecrets } else { $currentAd } }
        Update-DomeniaAccountUi
        Add-DomeniaUiLog -Area "Comptes" -Text "Panneau comptes initialise. Les champs editables ne sont plus recharges lors des changements de focus ; aucun mot de passe persiste."
    }
    catch { Add-DomeniaUiLog -Area "Comptes" -Level "WARN" -Text "Initialisation panneau comptes : $($_.Exception.Message)" }
}

function Wire-Events {
    Register-DomeniaReliabilityUi
    Add-DomeniaUiLog -Area "Interface" -Level "INFO" -Text "Branchement des evenements de l'interface."

    

    if ($script:Ctrl.ContainsKey("BtnCommandPalette")) {
        $script:Ctrl["BtnCommandPalette"].Add_Click({ Show-DomeniaCommandPalette })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountsHeader")) {
        $script:Ctrl["BtnAccountsHeader"].Add_Click({ Select-DomeniaWorkspace -Workspace "TabAccounts"; Update-DomeniaAccountUi })
    }
    if ($script:Ctrl.ContainsKey("BtnThemeToggle")) {
        $script:Ctrl["BtnThemeToggle"].IsEnabled = $true
        $script:Ctrl["BtnThemeToggle"].IsHitTestVisible = $true
        $script:Ctrl["BtnThemeToggle"].Add_Click({ Toggle-DomeniaTheme })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountAdRelogin")) {
        $script:Ctrl["BtnAccountAdRelogin"].Add_Click({ Start-DomeniaAccountRelogin })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountAdTest")) {
        $script:Ctrl["BtnAccountAdTest"].Add_Click({
            try {
                $u = ([string]$script:Ctrl["TxtAccountAdUser"].Text).Trim()
                [void](Test-DomeniaActiveDirectoryCredential -UserName $u)
            } catch { [void](Show-DomeniaOperationError -Operation "Test compte AD" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountAdUse")) {
        $script:Ctrl["BtnAccountAdUse"].Add_Click({
            $u = ([string]$script:Ctrl["TxtAccountAdUser"].Text).Trim()
            if (-not [string]::IsNullOrWhiteSpace($u)) { Set-DomeniaSetting -Name "LastLogin" -Value $u }
            Start-DomeniaAccountRelogin
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteTest")) {
        $script:Ctrl["BtnAccountRemoteTest"].Add_Click({
            try {
                $u = ([string]$script:Ctrl["TxtAccountRemoteUser"].Text).Trim()
                $p = $script:Ctrl["PwdAccountRemote"].SecurePassword
                [void](Test-DomeniaCredentialBind -UserName $u -Password $p -Operation "Test compte Remote")
            } catch { [void](Show-DomeniaOperationError -Operation "Test compte Remote" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteSave")) {
        $script:Ctrl["BtnAccountRemoteSave"].Add_Click({
            try {
                Save-DomeniaSecondaryCredential -Scope Remote -UserName ([string]$script:Ctrl["TxtAccountRemoteUser"].Text) -Password ($script:Ctrl["PwdAccountRemote"].SecurePassword)
            } catch { [void](Show-DomeniaOperationError -Operation "Activation compte Remote" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteClear")) {
        $script:Ctrl["BtnAccountRemoteClear"].Add_Click({ Clear-DomeniaSecondaryCredential -Scope Remote })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsTest")) {
        $script:Ctrl["BtnAccountSecretsTest"].Add_Click({
            try {
                $u = ([string]$script:Ctrl["TxtAccountSecretsUser"].Text).Trim()
                $p = $script:Ctrl["PwdAccountSecrets"].SecurePassword
                [void](Test-DomeniaCredentialBind -UserName $u -Password $p -Operation "Test compte Secrets")
            } catch { [void](Show-DomeniaOperationError -Operation "Test compte Secrets" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsSave")) {
        $script:Ctrl["BtnAccountSecretsSave"].Add_Click({
            try {
                Save-DomeniaSecondaryCredential -Scope Secrets -UserName ([string]$script:Ctrl["TxtAccountSecretsUser"].Text) -Password ($script:Ctrl["PwdAccountSecrets"].SecurePassword)
            } catch { [void](Show-DomeniaOperationError -Operation "Activation compte Secrets" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsClear")) {
        $script:Ctrl["BtnAccountSecretsClear"].Add_Click({ Clear-DomeniaSecondaryCredential -Scope Secrets })
    }
    Initialize-DomeniaRelationsUi
    if ($script:Ctrl.ContainsKey("TabAccounts")) {
        $script:Ctrl["TabAccounts"].Add_GotFocus({ try { Update-DomeniaAccountUi } catch { } })
    }

    if ($script:Ctrl.ContainsKey("BtnClearUiLog")) {
        $script:Ctrl["BtnClearUiLog"].Add_Click({
            Add-DomeniaUiLog -Area "Interface" -Level "INFO" -Text "Effacement manuel du journal demande."
            Clear-DomeniaUiLog
        })
    }
    
    if ($script:Ctrl.ContainsKey("CmbPresenceFilter")) {
        $script:Ctrl["CmbPresenceFilter"].Add_SelectionChanged({
            try {
                $item = $script:Ctrl["CmbPresenceFilter"].SelectedItem
                $script:CurrentPresenceFilter = if ($null -ne $item) { [string]$item.Content } else { "Tous" }
                if (-not $script:RestoringSettings) { Set-DomeniaSetting -Name "PresenceFilter" -Value $script:CurrentPresenceFilter }
                Apply-DomeniaPresenceFilter
                # Presence is only filtered from known data; no implicit scan on a filter change.
                Add-DomeniaUiLog -Area "Filtre" -Text "Presence : $($script:CurrentPresenceFilter)"
            }
            catch { }
        })
    }
    if ($script:Ctrl.ContainsKey("CmbUiProfile")) {
        $script:Ctrl["CmbUiProfile"].Add_SelectionChanged({
            try {
                $item = $script:Ctrl["CmbUiProfile"].SelectedItem
                $profile = if ($null -ne $item -and [string]$item.Tag -eq "Admin") { "Admin" } else { "Tech" }
                if ($profile -ne $script:CurrentUiProfile) { Apply-DomeniaUiProfile -Profile $profile }
            }
            catch { }
        })
    }

    $script:Ctrl["BtnTreeRefresh"].Add_Click({ Load-TreeRoot -ForceRefresh })
    $script:Ctrl["BtnSearchAllDomain"].Add_Click({ Reset-DomeniaSearchScope })
    $script:Ctrl["BtnSearchInOu"].Add_Click({ Invoke-DomeniaSearchFilterChanged })
    $script:Ctrl["ChkSubtree"].Add_Checked({ Invoke-DomeniaSearchFilterChanged })
    $script:Ctrl["ChkSubtree"].Add_Unchecked({ Invoke-DomeniaSearchFilterChanged })
    $script:Ctrl["CmbGlobalType"].Add_SelectionChanged({ Invoke-DomeniaSearchFilterChanged })
    $script:Ctrl["BtnLoadBranch"].Add_Click({ Load-BranchObjects -Browse })
    $script:Ctrl["BtnClearBranch"].Add_Click({ Clear-DomeniaGlobalSearch })
    $script:Ctrl["BtnGlobalSearch"].Add_Click({
        try { Invoke-GlobalSearch -SearchMode Global }
        catch {
            Write-AppLog "Clic Recherche : $($_.Exception.ToString())" "ERROR"
            Set-Status "La recherche n'a pas pu etre lancee : $($_.Exception.Message)" "ERROR"
        }
    })
    $script:Ctrl["BtnGlobalClear"].Add_Click({ Clear-DomeniaGlobalSearch })
    $script:Ctrl["TxtGlobalSearch"].Add_KeyDown({
        param($s,$e)
        if ($e.Key -eq "Enter") {
            $e.Handled = $true
            try { Invoke-GlobalSearch -SearchMode Global }
            catch {
                Write-AppLog "Recherche Entree : $($_.Exception.ToString())" "ERROR"
                Set-Status "La recherche n'a pas pu etre lancee : $($_.Exception.Message)" "ERROR"
            }
        }
    })
    $script:Ctrl["BtnDashRoot"].Add_Click({ Go-RootBranch })
    $script:Ctrl["BtnDashCopy"].Add_Click({ Copy-DashboardSummary })
    $script:Ctrl["TxtBranchSearch"].Add_KeyDown({ param($s,$e) if ($e.Key -eq "Enter") { Load-BranchObjects -Browse } })
    $script:Ctrl["CmbObjectFilter"].Add_SelectionChanged({ if ($script:Window -and $script:Conn.Connected -and -not [string]::IsNullOrWhiteSpace($script:SelectedBranchDn)) { Load-BranchObjects -Browse } })
    Initialize-DomeniaSelectionPreload
    $script:Ctrl["DgObjects"].Add_SelectionChanged({
        param($sender,$e)
        if($e.OriginalSource -eq $sender){Queue-DomeniaSelectedObjectOpen}
    })
    $script:Ctrl["DgObjects"].Add_PreviewMouseRightButtonDown({
        param($sender,$e)
        try {
            $node = $e.OriginalSource
            while ($null -ne $node -and -not ($node -is [System.Windows.Controls.DataGridRow])) {
                try { $node = [System.Windows.Media.VisualTreeHelper]::GetParent($node) }
                catch { try { $node = $node.Parent } catch { $node = $null } }
            }
            if ($null -ne $node -and $null -ne $node.Item) {
                $sender.SelectedItem = $node.Item
                $sender.CurrentItem = $node.Item
                $node.IsSelected = $true
            }
        }
        catch { }
    })
    $script:Ctrl["DgObjects"].Add_PreviewMouseLeftButtonUp({
        param($sender,$e)
        $container=[Windows.Controls.ItemsControl]::ContainerFromElement($sender,$e.OriginalSource)
        if($container -is [Windows.Controls.DataGridRow]){Queue-DomeniaSelectedObjectOpen}
    })
    $script:Ctrl["DgObjects"].Add_MouseDoubleClick({
        param($sender,$e)
        $container=[Windows.Controls.ItemsControl]::ContainerFromElement($sender,$e.OriginalSource)
        if($container -is [Windows.Controls.DataGridRow] -and @($sender.SelectedItems).Count -eq 1){
            Open-SelectedObject
            $e.Handled=$true
        }
    })
    $script:Ctrl["DgObjects"].Add_KeyDown({
        param($s,$e)
        if ($e.Key -eq "Enter" -and @($s.SelectedItems).Count -eq 1) {
            Open-SelectedObject
            $e.Handled = $true
        }
    })
    $script:Ctrl["BtnCopyObjectSummary"].Add_Click({ Copy-ObjectSummary })
    if ($script:Ctrl.ContainsKey("TxtObjDn")) {
        $dnMenu = New-Object System.Windows.Controls.ContextMenu
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Copier le DN" -Action {
            if ($null -ne $script:SelectedObject -and -not [string]::IsNullOrWhiteSpace([string]$script:SelectedObject.DN)) {
                Set-ClipboardSafe ([string]$script:SelectedObject.DN)
                Set-Status "DN copie."
            }
        }))
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Copier le nom" -Action {
            if ($null -ne $script:SelectedObject) { Set-ClipboardSafe ([string]$script:SelectedObject.Name); Set-Status "Nom copie." }
        }))
        [void]$dnMenu.Items.Add((New-Object System.Windows.Controls.Separator))
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Ouvrir le parent" -Action { Open-SelectedParentBranch }))
        $script:Ctrl["TxtObjDn"].ContextMenu = $dnMenu
    }
    $script:Ctrl["BtnOpenParentBranch"].Add_Click({ Open-SelectedParentBranch })
    $script:Ctrl["BtnDeleteObject"].Add_Click({ Delete-SelectedObject })
    $script:Ctrl["BtnUserSave"].Add_Click({ Save-UserProfile })
    $script:Ctrl["BtnUserUnlock"].Add_Click({ Unlock-UserAccount })
    $script:Ctrl["BtnUserEnable"].Add_Click({ Set-AccountDisabled $false })
    $script:Ctrl["BtnUserDisable"].Add_Click({ Set-AccountDisabled $true })
    $script:Ctrl["BtnRevealUserNew"].Add_Click({ Toggle-PasswordBox "PwdUserNew" "TxtUserNewVisible" "BtnRevealUserNew" "__UserNewReveal" })
    $script:Ctrl["BtnRevealUserConfirm"].Add_Click({ Toggle-PasswordBox "PwdUserConfirm" "TxtUserConfirmVisible" "BtnRevealUserConfirm" "__UserConfirmReveal" })
    $script:Ctrl["BtnUserResetPwd"].Add_Click({ Reset-UserPassword })
    $script:Ctrl["BtnApplyAccountOptions"].Add_Click({ Apply-UserAccountOptions })
    $script:Ctrl["BtnSetExpiration"].Add_Click({ Set-UserExpiration $false })
    $script:Ctrl["BtnNeverExpires"].Add_Click({ Set-UserExpiration $true })
    $script:Ctrl["BtnExpirePwdNow"].Add_Click({ Expire-UserPasswordNow })
