    if ($script:Ctrl.ContainsKey("BtnCompRestart")) { $script:Ctrl["BtnCompRestart"].Add_Click({ Invoke-ComputerTool "Restart" }) }
    if ($script:Ctrl.ContainsKey("BtnOpenLinkedUser")) { $script:Ctrl["BtnOpenLinkedUser"].Add_Click({ Open-LinkedUserFromMachine }) }
    if ($script:Ctrl.ContainsKey("BtnOpenLinkedComputer")) { $script:Ctrl["BtnOpenLinkedComputer"].Add_Click({ Open-LinkedComputerFromUser }) }
    if ($script:Ctrl.ContainsKey("BtnRefreshMachineLink")) { $script:Ctrl["BtnRefreshMachineLink"].Add_Click({ Start-ProbeForSelectedComputer -Force }) }
    if ($script:Ctrl.ContainsKey("TxtUserLinkedComputers")) { $script:Ctrl["TxtUserLinkedComputers"].Add_MouseDoubleClick({ Open-LinkedComputerFromUser }) }
    if (
        $script:Ctrl.ContainsKey("TxtGlobalSearch") -and
        [bool](Get-CfgValue "Browser" "AllowLiveGlobalSearch" $false) -and
        [bool](Get-CfgValue "Browser" "LiveGlobalSearch" $false)
    ) {
        $script:Ctrl["TxtGlobalSearch"].Add_TextChanged({ Queue-LiveGlobalSearch })
    }
    [void](Register-DomeniaContextMenus)
    Register-DomeniaDeferredViewHandlers
    [void](Register-DomeniaShortcuts)
}




# =====================================================================
# DOMENIA MASTER LAST V1 - couche finale de consolidation et de securite
# =====================================================================
# DOMENIA_MASTER_LAST_V1 = TRUE
$script:Version = "1.0"
$script:AppName = "Domenia"
$script:MasterBuild = "2026.10.02-DOMENIA-1.0-RC1.11.0-D120"
$script:ActiveWriteTaskId = ""
$script:WriteState = "Idle"
$script:UnknownWriteTargetDn = ""
$script:LastDispatcherErrorPopupAt = [datetime]::MinValue
$script:StartupWindow = $null
$script:StartupCtrl = @{}
$script:StartupTracePath = ""
$script:StartupCorrelation = [guid]::NewGuid().ToString("N")
$script:ShowingCachedObject = $false
$script:DashboardRefreshTimer = $null
$script:ActiveLinkProbeId = ""
$script:ActiveLinkProbeComputer = ""
$script:LinkIndexGeneration = 0
try {
    $hashProvider = [System.Security.Cryptography.SHA256]::Create()
    try { $rootHash = ([BitConverter]::ToString($hashProvider.ComputeHash([Text.Encoding]::UTF8.GetBytes(([string]$script:RootDir).ToLowerInvariant()))).Replace("-","")).Substring(0,20) }
    finally { $hashProvider.Dispose() }
} catch { $rootHash = [Math]::Abs(([string]$script:RootDir).ToLowerInvariant().GetHashCode()) }
$script:DataMutexName = "Local\DOMENIA_Data_$rootHash"
$script:RawAttributeBlockList = @(
    "objectGUID","objectSid","sIDHistory","nTSecurityDescriptor","unicodePwd","dBCSPwd",
    "supplementalCredentials","ntPwdHistory","lmPwdHistory","userPassword","unixUserPassword","clearTextPassword","currentValue","priorValue","pekList","trustAuthIncoming","trustAuthOutgoing","userAccountControl","adminCount",
    "isCriticalSystemObject","msDS-KeyCredentialLink","msDS-ManagedPassword","msDS-ManagedPasswordId","msDS-ManagedPasswordPreviousId","ms-Mcs-AdmPwd","ms-Mcs-AdmPwdExpirationTime",
    "msLAPS-Password","msLAPS-EncryptedPassword","msLAPS-EncryptedPasswordHistory","msLAPS-EncryptedDSRMPassword","msLAPS-EncryptedDSRMPasswordHistory","msLAPS-PasswordExpirationTime",
    "msFVE-RecoveryPassword","msFVE-KeyPackage","member","memberOf","primaryGroupID",
    "distinguishedName","objectClass","objectCategory","uSNChanged","uSNCreated","whenCreated","whenChanged"
)

function New-DefaultConfig {
    [ordered]@{
        Conf = [ordered]@{
            AutoDiscover = $true
            DOMAINE = ""
            NETBIOS = ""
            SearchBase = ""
            Server = ""
            UsersBase = ""
            ComputersBase = ""
            ADM = ""
        }
        Auth = [ordered]@{
            RememberLogin = $true
            LastLogin = ""
            LoginWindowMode = "Standard"
            AllowWindowsSession = $true
            LoginTimeoutSeconds = 30
            PerServerTimeoutSeconds = 6
            MaxServerCandidates = 4
            DetailedLoginTrace = $true
            # D120: in-memory demonstration directory. Only the JSON value true enables it.
            DemoProvider = $false
        }
        # D120 (F5): switches for behaviours that replace an existing path. Read by Get-DomeniaFeatureFlag.
        Features = [ordered]@{
            Scheduler = $true
            IdlePolicy = $true
            BitLockerKeySelection = $true
            SecretSingleCopy = $true
