            SecretMemorySeconds = 300
            RequireFreshObject = $true
            MaxObjectAgeMinutes = 15
            BlockProtectedObjects = $true
            AllowProtectedObjectWrites = $false
            AllowContainerDelete = $false
            RequireTypedDeleteConfirmation = $true
            AllowRawAttributeWrite = $false
            BlockSensitiveRawAttributes = $true
            RequireTypedHighRiskConfirmation = $true
            SingleWriteChannel = $true
            NeverPersistLaps = $true
            NeverPersistBitLockerRecovery = $true
            NeverLogSecretValues = $true
            SecretClipboardSeconds = 20
        }
        SelfCheck = [ordered]@{
