function Rename-ComputerObject {
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine"){return}
        $newName=($script:Ctrl["TxtCompNewName"].Text+"").Trim();if([string]::IsNullOrWhiteSpace($newName)){throw "Nouveau nom vide."}
        if($newName -notmatch "^[A-Za-z0-9][A-Za-z0-9-]{0,62}$"){throw "Nom ordinateur invalide."}
        if(-not (Confirm-Action "Renommer le CN de la machine en $newName ?`r`nLe poste Windows distant ne sera pas renomme.")){return}
        $payload=[pscustomobject]@{DN=[string]$script:SelectedObject.DN;NewName=$newName;Safety=(Get-DomeniaSafetyDescriptor)}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
if([string]$before.Name -ieq [string]$Payload.NewName){[pscustomobject]@{Verified=$true;Backend="None";Message="Nom deja conforme. Aucune ecriture AD.";NewDn=[string]$before.DN;Before=$before;After=$before};return}
$backend=Get-WWriteBackend $Context @("Rename-ADObject")
$newDn=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.DN;NewName=[string]$Payload.NewName;PassThru=$true;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$DomeniaWriteDispatched=$true;$o=Rename-ADObject @p;$newDn=[string]$o.DistinguishedName}
else{$de=New-WEntry $Context ([string]$Payload.DN);$DomeniaWriteDispatched=$true;$de.Rename("CN="+(Escape-WRdn ([string]$Payload.NewName)));$de.CommitChanges();$de.RefreshCache(@("distinguishedName"));$newDn=[string]$de.Properties["distinguishedName"].Value}
$after=Get-WObjectSnapshot $Context $newDn
if(-not [bool]$after.Exists -or [string]$after.Name -ine [string]$Payload.NewName){throw "Verification du renommage echouee."}
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Objet ordinateur renomme et verifie.";NewDn=$newDn;Before=$before;After=$after}
'@
        Start-DomeniaWriteTask -Name "Renommage machine AD" -OperationId "WriteRenameComputer" -Code $code -Payload $payload -Capability "Move" -DisableControls @("BtnCompRename") -AfterSuccessAction "RenameComputer"
    } catch { Show-ErrorBox "Erreur renommage : $($_.Exception.Message)" }
}

function Create-OuUnderSelected {
    try {
        if ([string]::IsNullOrWhiteSpace([string]$script:SelectedBranchDn)) { throw "Selectionne une branche cible." }
        $name = ($script:Ctrl["TxtNewOuName"].Text + "").Trim()
        if ([string]::IsNullOrWhiteSpace($name)) { throw "Nom de l OU vide." }
        if ($name.IndexOfAny([IO.Path]::GetInvalidFileNameChars()) -ge 0) { throw "Le nom contient des caracteres invalides." }
        if (-not (Confirm-TextAction -Message "Creer une OU protegee contre la suppression accidentelle ?`r`nNom : $name`r`nParent : $($script:SelectedBranchDn)" -Expected "CREER")) { Set-Status "Creation OU annulee." "WARN"; return }
        $payload = [pscustomobject]@{ ParentDn=[string]$script:SelectedBranchDn; Name=$name; DN=[string]$script:SelectedBranchDn }
        $code = @'
$parent=Get-WObjectSnapshot $Context ([string]$Payload.ParentDn)
if(-not [bool]$parent.Exists){throw "Branche parente introuvable."}
if(-not (@($parent.Classes) -contains "organizationalUnit") -and -not (@($parent.Classes) -contains "container") -and -not (@($parent.Classes) -contains "domainDNS")){throw "La cible n est pas une OU, un conteneur ou la racine du domaine."}
$escaped=Escape-WLdap ([string]$Payload.Name)
$check=New-WSearcher $Context ([string]$Payload.ParentDn) "(&(objectClass=organizationalUnit)(name=$escaped))" @("distinguishedName") "OneLevel" 2
if(@($check.FindAll()).Count -gt 0){throw "Une OU portant deja ce nom existe sous la branche cible."}
$backend=Get-WWriteBackend $Context @("New-ADOrganizationalUnit")
$dn=""
if($backend -eq "Module"){
    $p=@{Name=[string]$Payload.Name;Path=[string]$Payload.ParentDn;ProtectedFromAccidentalDeletion=$true;PassThru=$true;ErrorAction="Stop"}
    if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c}
    $DomeniaWriteDispatched=$true
    $o=New-ADOrganizationalUnit @p;$dn=[string]$o.DistinguishedName
}else{
    $de=New-WEntry $Context ([string]$Payload.ParentDn)
    $DomeniaWriteDispatched=$true
    $ou=$de.Children.Add("OU="+(Escape-WRdn ([string]$Payload.Name)),"organizationalUnit")
    $ou.CommitChanges();$ou.RefreshCache(@("distinguishedName"));$dn=[string]$ou.Properties["distinguishedName"].Value
}
if([string]::IsNullOrWhiteSpace($dn)){$dn="OU="+(Escape-WRdn ([string]$Payload.Name))+","+[string]$Payload.ParentDn}
$after=Get-WObjectSnapshot $Context $dn
if(-not [bool]$after.Exists -or -not (@($after.Classes) -contains "organizationalUnit")){throw "La verification de l OU creee a echoue."}
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if($backend -eq "Module"){"OU creee, protegee et verifiee : $dn"}else{"OU creee et verifiee via ADSI : $dn. La protection contre suppression accidentelle necessite le module AD."});DN=$dn;Before=$parent;After=$after}
'@
        Start-DomeniaWriteTask -Name "Creation OU" -OperationId "WriteCreateOu" -Code $code -Payload $payload -Capability "Create" -DisableControls @("BtnCreateOu") -AfterSuccessAction "CreateOu"
    }
    catch { Show-ErrorBox "Erreur creation OU : $($_.Exception.Message)" }
}

function Set-OrClearRawAttribute {
    param([bool]$Clear)
    try {
        if ($null -eq $script:SelectedObject) { return }
        if (-not [bool](Get-CfgValue "Security" "AllowRawAttributeWrite" $false)) { throw "L editeur brut est verrouille par defaut. Active Security.AllowRawAttributeWrite uniquement apres validation en laboratoire." }
        $attr = ($script:Ctrl["TxtRawAttrName"].Text + "").Trim()
        if ($attr -notmatch "^[A-Za-z][A-Za-z0-9-]{0,127}$") { throw "Nom d attribut invalide." }
        foreach ($blocked in $script:RawAttributeBlockList) { if ([string]$blocked -ieq $attr) { throw "Attribut sensible bloque : $attr" } }
        $value = [string]$script:Ctrl["TxtRawAttrValue"].Text
        $old = Get-DomeniaOriginalValue $attr
        if ($Clear -and [string]::IsNullOrWhiteSpace($old)) { Set-Status "Attribut deja vide. Aucune ecriture AD."; return }
        if ((-not $Clear) -and ([string]$old -ceq $value)) { Set-Status "Valeur deja conforme. Aucune ecriture AD."; return }
        $newLabel = if ($Clear) { "<EFFACE>" } else { $value }
        $message = "Objet : $($script:SelectedObject.DN)`r`nAttribut : $attr`r`nAncienne valeur : $old`r`nNouvelle valeur : $newLabel"
        if (-not (Confirm-TextAction -Message $message -Expected "MODIFIER" -Title "Ecriture d attribut a haut risque")) { Set-Status "Ecriture brute annulee." "WARN"; return }
        $change = [pscustomobject]@{ Name=$attr; Old=[string]$old; New=$value; Clear=$Clear }
        Start-DomeniaAttributeWrite -OperationName "Attribut brut $attr" -Changes @($change) -Capability "Edit" -DisableControls @("BtnRawSet","BtnRawClear")
    }
    catch { Show-ErrorBox "Erreur attribut brut : $($_.Exception.Message)" }
}

function Delete-SelectedObject {
    try {
        if ($null -eq $script:SelectedObject) { return }
        Assert-DomeniaCapability "Delete"
        $dn = [string]$script:SelectedObject.DN
        $type = [string]$script:SelectedObject.Type
        $name = [string]$script:SelectedObject.Name
        if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$script:Ctrl["TxtObjName"].Text }
        if ($dn -ieq [string]$script:Conn.BaseDn) { throw "La racine du domaine ne peut jamais etre supprimee par Domenia." }
        if ($type -in @("OU","Conteneur") -and -not [bool](Get-CfgValue "Security" "AllowContainerDelete" $false)) { throw "Suppression des unites d organisation bloquee par defaut. Aucune suppression recursive n est possible." }
        $expected = if ([string]::IsNullOrWhiteSpace($name)) { $dn } else { $name }
        if (-not (Confirm-TextAction `
            -Message "SUPPRESSION AD NON RECURSIVE`r`n`r`nObjet : $dn`r`nLes objets proteges ou possedant des enfants seront refuses." `
            -Expected $expected `
            -Title "Confirmation 1 sur 2")) {
            Set-Status "Suppression annulee : confirmation incorrecte." "WARN"
            return
        }
        if (-not (Confirm-TextAction -Message "Derniere confirmation pour supprimer uniquement cet objet :`r`n$dn" -Expected "SUPPRIMER" -Title "Confirmation finale")) { Set-Status "Suppression annulee." "WARN"; return }
        $deletedType=$type;$deletedName=$name;$deletedSam="";$deletedDns=""
        if($type -eq "Utilisateur"){$deletedSam=[string]$script:Ctrl["TxtUserSam"].Text}
        if($type -eq "Machine"){$deletedSam=[string]$script:Ctrl["TxtCompName"].Text;$deletedDns=[string]$script:Ctrl["TxtCompDns"].Text}
        $payload=[pscustomobject]@{DN=$dn;Safety=(Get-DomeniaSafetyDescriptor);Type=$type;Name=$name}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$children=Get-WChildCount $Context ([string]$Payload.DN)
if($children -gt 0){throw "Suppression bloquee : cet objet possede $children objet(s) enfant(s). Aucune suppression recursive n est autorisee."}
if(@($before.Classes) -contains "domainDNS"){throw "Suppression de la racine domaine interdite."}
if((@($before.Classes) -contains "organizationalUnit" -or @($before.Classes) -contains "container") -and -not [bool]$Context.AllowContainerDelete){throw "Suppression OU/conteneur bloquee par la politique Domenia."}
$backend=Get-WWriteBackend $Context @("Remove-ADObject")
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;Confirm=$false;Recursive=$false;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$DomeniaWriteDispatched=$true;Remove-ADObject @p
}else{
    $parentDn=Get-WParentDn ([string]$Payload.DN);if([string]::IsNullOrWhiteSpace($parentDn)){throw "Parent DN introuvable."}
    $parent=New-WEntry $Context $parentDn;$child=New-WEntry $Context ([string]$Payload.DN)
    $class=if(@($before.Classes) -contains "computer"){"computer"}elseif(@($before.Classes) -contains "user"){"user"}elseif(@($before.Classes) -contains "group"){"group"}elseif(@($before.Classes) -contains "organizationalUnit"){"organizationalUnit"}else{[string](@($before.Classes)[-1])}
    $DomeniaWriteDispatched=$true;$parent.Children.Remove($child);$parent.CommitChanges()
}
Start-Sleep -Milliseconds 250
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
if([bool]$after.Exists){throw "Verification impossible : l objet existe encore apres la demande de suppression."}
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Objet supprime sans recursivite et absence verifiee.";Before=$before;After=$after}
'@
        $deleteState = [pscustomobject]@{ DeletedType=$deletedType; DeletedName=$deletedName; DeletedSam=$deletedSam; DeletedDns=$deletedDns }
        Start-DomeniaWriteTask -Name "Suppression objet AD" -OperationId "WriteDeleteObject" -Code $code -Payload $payload -Capability "Delete" -DisableControls @("BtnDeleteObject") -AfterSuccessAction "DeleteObject" -AfterSuccessState $deleteState
    }
    catch { Show-ErrorBox "Erreur suppression : $($_.Exception.Message)" }
}

function ConvertTo-DomeniaSafeValue {
    param($Value,[string]$Key="")
    $sensitive = "(?i)password|passwd|secret|token|credential|api.?key|recoverypassword|laps|unicodepwd|keypackage|private"
    if ($Key -match $sensitive) { return "<MASQUE>" }
    if ($null -eq $Value) { return $null }
    if ($Value -is [System.Management.Automation.PSCredential] -or $Value -is [Security.SecureString]) { return "<MASQUE>" }
    if ($Value -is [System.Collections.IDictionary]) {
        $h=[ordered]@{};foreach($k in $Value.Keys){$h[[string]$k]=ConvertTo-DomeniaSafeValue $Value[$k] ([string]$k)};return [pscustomobject]$h
    }
    if ($Value -is [System.Management.Automation.PSObject] -and -not ($Value -is [string]) -and -not ($Value -is [ValueType])) {
        $h=[ordered]@{};foreach($p in $Value.PSObject.Properties){$h[$p.Name]=ConvertTo-DomeniaSafeValue $p.Value $p.Name};return [pscustomobject]$h
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) { return @($Value | ForEach-Object { ConvertTo-DomeniaSafeValue $_ $Key }) }
    $text=[string]$Value
    if($text.Length -gt 4096){return $text.Substring(0,4096)+"...<tronque>"}
    return $Value
}

function Export-SelfCheckReport {
    try {
        Initialize-DomeniaDataStore | Out-Null
        $dlg = New-DomeniaFileRequest -Mode Save
        $dlg.Filter = "Archive diagnostic ZIP (*.zip)|*.zip"
        $dlg.FileName = "Domenia-Diagnostic-$((Get-Date).ToString('yyyyMMdd-HHmmss')).zip"
        if (-not $dlg.ShowDialog()) { return }
        $work = Join-Path (Join-Path $script:DataDir "Diagnostics") ("diag-"+[guid]::NewGuid().ToString("N"))
        New-Item -ItemType Directory -Path $work -Force | Out-Null
        try {
            $runtime=[ordered]@{
                App="DOMENIA";Build=$script:MasterBuild;Version=$script:Version;Generated=(Get-Date).ToString("o")
                PowerShell=[string]$PSVersionTable.PSVersion;OS=[Environment]::OSVersion.VersionString
                RootDir=$script:RootDir;DataDir=$script:DataDir;ProcessIdentity=$script:ProcessIdentity
                AdIdentity=[string]$script:Conn.BindUser;Domain=[string]$script:Conn.Domain;Server=[string]$script:Conn.Server;BaseDn=[string]$script:Conn.BaseDn
                ReadOnly=[bool]$script:ReadOnlyMode;WriteState=[string]$script:WriteState
                AsyncEngineReady=[bool]$script:AsyncEngineReady;AsyncJobs=@($script:AsyncJobs.Keys).Count
                ModuleSources=@(Get-DomeniaAdModuleSources);ModuleLoaded=[bool](Test-DomeniaAdCommandsAvailable)
                Integrity=(Get-DomeniaIntegritySnapshot)
            }
            (ConvertTo-DomeniaSafeValue $runtime | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath (Join-Path $work "runtime.json") -Encoding UTF8
            (ConvertTo-DomeniaSafeValue $script:Config | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath (Join-Path $work "configuration-sanitized.json") -Encoding UTF8
            if(@($script:SelfCheckRows).Count -gt 0){$script:SelfCheckRows | ConvertTo-DomeniaSpreadsheetSafeRow | Export-Csv -LiteralPath (Join-Path $work "self-check.csv") -NoTypeInformation -Encoding UTF8}


            @("DOMENIA diagnostic en lecture seule","Journaux bruts exclus. Les identites, noms de machines, domaines et chemins ne sont pas anonymises. Relire avant partage.","Build: $($script:MasterBuild)","Version: $($script:Version)") | Set-Content -LiteralPath (Join-Path $work "README.txt") -Encoding UTF8
            Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
            $zipTemp = $dlg.FileName + '.' + [guid]::NewGuid().ToString('N') + '.partial'
            try {
                [System.IO.Compression.ZipFile]::CreateFromDirectory($work,$zipTemp,[System.IO.Compression.CompressionLevel]::Optimal,$false)
                if ([IO.File]::Exists($dlg.FileName)) { [IO.File]::Replace($zipTemp,$dlg.FileName,[NullString]::Value,$true) }
                else { [IO.File]::Move($zipTemp,$dlg.FileName) }
            } finally { Remove-Item -LiteralPath $zipTemp -Force -ErrorAction SilentlyContinue }
            Set-Status "ZIP diagnostic exporte : $($dlg.FileName)"
            Write-AppLog "ZIP diagnostic exporte : $($dlg.FileName)" "INFO"
        }
        finally { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
    }
    catch { Show-ErrorBox "Erreur export diagnostic : $($_.Exception.Message)" }
}

function Get-DomeniaCriticalFunctionNames {
    @(
        "Show-LoginWindow","Initialize-Window","Initialize-AsyncEngine","Get-DomeniaWorkerOperationHashes","Assert-DomeniaWorkerOperationCode","New-DomeniaWorkerRunspace","Start-UiTask","Complete-UiTasks","Start-DomeniaWriteTask",
        "Load-TreeRoot","Load-TreeChildren","Load-BranchObjects","Invoke-GlobalSearch","Open-AdObject","Show-AdObjectResult",
        "Start-PermissionAnalysis","Start-SelfCheck","Export-SelfCheckReport","Start-LoadComputerSecrets","Update-DomeniaSecretActionUi","Assert-DomeniaReadWriteControlClassification","Start-ComputerDiagnostics",
        "Start-ComputerUserLinkProbe","Save-UserProfile","Save-ComputerProfile","Save-GroupProfile","Reset-UserPassword",
        "Set-AccountDisabled","Unlock-UserAccount","Apply-UserAccountOptions","Set-UserExpiration","Expire-UserPasswordNow",
        "Move-SelectedObject","Rename-ComputerObject","AddOrRemoveObjectGroup","AddOrRemoveGroupMember","Delete-SelectedObject",
        "Create-OuUnderSelected","Set-OrClearRawAttribute","Load-AdCmdlets","Apply-CurrentPermissionUi","Get-DomeniaSafetyDescriptor",
        "Save-UserMachineLinks","Write-StartupTrace","Invoke-DomeniaInProcessAuthProbe","Start-DomeniaLoginAuthRunspace"
    )
}

function Request-DomeniaDashboardRefresh {
    param([switch]$Immediate)
    if ($Immediate) {
        try { Update-Dashboard } catch { }
        return
    }
    # D020: a hidden or inactive home page is not rebuilt; it is marked dirty and rebuilt once when shown again.
    $dashboardAllowed = $true
    if ($null -ne (Get-Command -Name Test-DomeniaBackgroundWorkAllowed -CommandType Function -ErrorAction SilentlyContinue)) {
        try { $dashboardAllowed = [bool](Test-DomeniaBackgroundWorkAllowed -Source 'Dashboard') } catch { $dashboardAllowed = $true }
    }
    if (-not $dashboardAllowed) { $script:DashboardDirty = $true; return }
    $script:DashboardDirty = $false
    try {
        if ($null -eq $script:DashboardRefreshTimer) {
            $script:DashboardRefreshTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:DashboardRefreshTimer.Interval = [TimeSpan]::FromMilliseconds(160)
            $script:DashboardRefreshTimer.Add_Tick({
                param($sender,$eventArgs)
                # Stop the timer that ticked, not the script variable: a replaced or cleared variable left it ticking forever.
                try { $sender.Stop() } catch { }
                # D020: the page may have been hidden since the request; it is then rebuilt once when shown again.
                $tickAllowed = $true
                if ($null -ne (Get-Command -Name Test-DomeniaBackgroundWorkAllowed -CommandType Function -ErrorAction SilentlyContinue)) {
                    try { $tickAllowed = [bool](Test-DomeniaBackgroundWorkAllowed -Source 'Dashboard') } catch { $tickAllowed = $true }
                }
                if (-not $tickAllowed) { $script:DashboardDirty = $true; return }
                try { Update-Dashboard } catch { }
            })
            # D019: owned timer, stopped by the registry at shutdown.
            try { [void](Register-DomeniaOwnedTimer -Owner 'Timer:DashboardRefresh' -Timer $script:DashboardRefreshTimer) } catch { }
        }
        $script:DashboardRefreshTimer.Stop()
        $script:DashboardRefreshTimer.Start()
    }
    catch { try { Update-Dashboard } catch { } }
}

function Update-Dashboard {
    try {
        # D014: no command lookup in series on each refresh; the AD module state is read once per change of module.
        $rows=@($script:BranchObjects)
        $stats=Get-ObjectsStatsText $rows
        $script:Ctrl["TxtDashDomain"].Text=[string]$script:Conn.Domain
        $script:Ctrl["TxtDashServer"].Text=[string]$script:Conn.Server
        $script:Ctrl["TxtDashUser"].Text=[string]$script:Conn.BindUser
        $script:Ctrl["TxtDashMode"].Text=if($script:ReadOnlyMode){"Lecture seule (securite par defaut)"}else{"Ecriture autorisee sous controles"}
        $script:Ctrl["TxtDashBaseDn"].Text=[string]$script:Conn.BaseDn
        $script:Ctrl["TxtDashBranch"].Text=[string]$script:SelectedBranchDn
        $script:Ctrl["TxtDashRows"].Text=[string]$rows.Count
        $adCheckDue=($null -eq $script:DashboardAdModuleCheckedAt)
        if(-not $adCheckDue -and -not [bool]$script:DashboardAdModuleLoaded){$adCheckDue=(((Get-Date)-[datetime]$script:DashboardAdModuleCheckedAt).TotalSeconds -ge 30)}
        # Demonstration: Get-Command on an AD cmdlet auto-imports ActiveDirectory, whose AD: drive binds to a domain controller.
        if($adCheckDue -and [bool]$script:DemoMode){$script:DashboardAdModuleLoaded=$false;$script:DashboardAdModuleCheckedAt=Get-Date;$adCheckDue=$false}
        if($adCheckDue){$script:DashboardAdModuleLoaded=[bool](Test-DomeniaAdCommandsAvailable);$script:DashboardAdModuleCheckedAt=Get-Date}
        $script:Ctrl["TxtDashModule"].Text=if([bool]$script:DashboardAdModuleLoaded){"ActiveDirectory charge"}else{"A la demande : RSAT/DLL verifies/LDAP"}
        $script:Ctrl["TxtDashStats"].Text=[string]$stats
        $script:Ctrl["TxtDashSelected"].Text=if($null -ne $script:SelectedObject){"$($script:SelectedObject.Type)  $($script:SelectedObject.Name)"}else{"Aucun"}
        if($script:Ctrl.ContainsKey("TxtDashRights")){$script:Ctrl["TxtDashRights"].Text=if($script:CurrentCapabilities.Count -gt 0){($script:CurrentCapabilities.GetEnumerator()|ForEach-Object{"$($_.Key)=$($_.Value)"}) -join "  "}else{"Analyse a l ouverture de l objet"}}
        if($script:Ctrl.ContainsKey("TxtDashTasks")){$script:Ctrl["TxtDashTasks"].Text="$(@($script:AsyncJobs.Keys).Count) tache(s)  ecriture=$($script:WriteState)"}
        if($script:Ctrl.ContainsKey("TxtDashCache")){$script:Ctrl["TxtDashCache"].Text="Cache visite borne : $(@($script:VisitCache.Keys).Count)  aucun scan global"}
        if($script:Ctrl.ContainsKey("TxtDashSelfCheck")){$script:Ctrl["TxtDashSelfCheck"].Text=[string]$script:LastSelfCheckSummary}
        if($script:Ctrl.ContainsKey("TxtDashLinks")){$script:Ctrl["TxtDashLinks"].Text=(Get-AssociationStatsText)}
    }
    catch { }
}

function Complete-DomeniaStartupWarmupUi {
    param($Result,$State)
    try {
        $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("BaseDn","TreeReady","ObjectsReady","TreeRows","ObjectRows","WorkerThreadId")
        if ($null -eq $effective) { throw "Le worker de prechargement n'a retourne aucun resultat exploitable." }
        if ([string]$effective.BaseDn -ine [string]$script:Conn.BaseDn) { throw "Le cache a ete construit pour une autre base AD." }
        $script:StartupWarmCache = $effective
        $script:StartupWorkerThreadId = [int]$effective.WorkerThreadId
        $script:StartupWorkerReady = $true
        $script:StartupWarmupError = ""
        $script:StartupWarmupDone = $true
        Set-DomeniaStartupStage -Stage "Cache initial pret" -Detail "Worker MTA $($script:StartupWorkerThreadId) : $(@($effective.TreeRows).Count) branche(s), $(@($effective.ObjectRows).Count) objet(s)."
    }
    catch {
        $script:StartupWarmupError = $_.Exception.Message
        $script:StartupWarmupDone = $true
        Write-StartupTrace -Stage "Cache initial" -Status "ERROR" -Detail $_.Exception.ToString()
    }
}

function Fail-DomeniaStartupWarmupUi {
    param($Message,$State)
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue du prechargement." }
    $script:StartupWarmupError = $detail
    $script:StartupWarmupDone = $true
    $script:StartupWorkerReady = $false
    Set-DomeniaStartupStage -Stage "Cache initial indisponible" -Detail $detail
}

function Invoke-DomeniaStartupCacheWarmup {
    if (-not [bool](Get-CfgValue "Cache" "RequireReadyBeforeMainWindow" $false)) {
        $script:StartupWarmupDone = $true
        $script:StartupWorkerReady = [bool]$script:AsyncEngineReady
        $script:StartupReady = $true
        return
    }

    $timeout = [Math]::Max(10,[int](Get-CfgValue "Cache" "WarmupTimeoutSeconds" 45))
    $configuredRetries = [Math]::Max(1,[int](Get-CfgValue "Cache" "WarmupRetries" 2))
    $retryDelayMs = [Math]::Max(250,[int](Get-CfgValue "Cache" "WarmupRetryDelayMs" 1200))
    $warmTree = [bool](Get-CfgValue "Cache" "WarmRootTree" $true)
    $warmObjects = [bool](Get-CfgValue "Cache" "WarmRootObjects" $true)
    $objectLimit = [Math]::Max(1,[int](Get-CfgValue "Cache" "WarmRootObjectLimit" 100))
    $properties = @("name","distinguishedName","objectClass","objectCategory","sAMAccountName","userPrincipalName","mail","dNSHostName","description","displayName","whenChanged","userAccountControl","lockoutTime","msDS-User-Account-Control-Computed","operatingSystem","lastLogonTimestamp")

    $code = @'
$treeRows = @()
$objectRows = @()
$treeReady = (-not [bool]$Payload.WarmTree)
$objectsReady = (-not [bool]$Payload.WarmObjects)
if ([bool]$Payload.WarmTree) {
    $s = New-WSearcher $Context ([string]$Context.BaseDn) "(|(objectClass=organizationalUnit)(objectClass=container)(objectClass=builtinDomain))" @("name","distinguishedName","objectClass") "OneLevel" 0
    $items = New-Object Collections.ArrayList
    foreach ($r in @($s.FindAll())) {
        $dn = [string](Get-WPropFirst $r.Properties "distinguishedname" "")
        if ([string]::IsNullOrWhiteSpace($dn)) { continue }
        [void]$items.Add([pscustomobject]@{ Name=[string](Get-WPropFirst $r.Properties "name" ""); DN=$dn; Kind=(Get-WObjectType $r.Properties) })
    }
    $treeRows = @($items | Sort-Object Name)
    $treeReady = $true
}
if ([bool]$Payload.WarmObjects) {
    $filter = "(|(&(objectCategory=person)(objectClass=user))(objectCategory=computer)(objectCategory=group)(objectClass=organizationalUnit)(objectClass=container))"
    $s2 = New-WSearcher $Context ([string]$Context.BaseDn) $filter @($Payload.Properties) "OneLevel" ([int]$Payload.ObjectLimit)
    $items2 = New-Object Collections.ArrayList
    foreach ($r in @($s2.FindAll())) { [void]$items2.Add((New-WBranchRow $r)) }
    $objectRows = @($items2)
    $objectsReady = $true
}
[pscustomobject]@{
    BaseDn=[string]$Context.BaseDn
    TreeReady=[bool]$treeReady
    ObjectsReady=[bool]$objectsReady
    TreeRows=@($treeRows)
    ObjectRows=@($objectRows)
    WorkerThreadId=[System.Threading.Thread]::CurrentThread.ManagedThreadId
}
'@

    $lastError = ""
    $attempt = 0
    while ($attempt -lt $configuredRetries) {
        if ($script:StartupCancelled) { throw "Initialisation annulee par l'utilisateur avant disponibilite du cache." }
        $attempt++
        $attemptLabel = "$attempt/$configuredRetries"
        $script:StartupWarmCache = $null
        $script:StartupWarmupDone = $false
        $script:StartupWarmupError = ""
        $script:StartupWorkerReady = $false
        Set-DomeniaStartupStage -Stage "Prechargement AD  tentative $attemptLabel" -Detail "Lecture de la racine dans un runspace MTA ; la fenetre principale reste masquee jusqu'a validation complete."

        $taskId = Start-UiTask -Name "Cache initial AD" -OperationId "StartupWarmCache" -Code $code -Payload ([pscustomobject]@{ WarmTree=$warmTree; WarmObjects=$warmObjects; ObjectLimit=$objectLimit; Properties=$properties }) -CallbackState ([pscustomobject]@{ Attempt=$attempt }) -ReplaceKey "startup-warm-cache" -TimeoutSeconds $timeout -StatusText "Prechargement du cache initial..." -SuccessHandler "Complete-DomeniaStartupWarmupUi" -ErrorHandler "Fail-DomeniaStartupWarmupUi"
        $deadline = (Get-Date).AddSeconds($timeout + 5)
        while (-not $script:StartupWarmupDone -and (Get-Date) -lt $deadline -and -not $script:StartupCancelled) {
            Complete-UiTasks
            Invoke-DomeniaUiPump
            Start-Sleep -Milliseconds 35
        }
        if ($script:StartupCancelled) {
            Request-UiTaskStop -Id $taskId -Silent -Force
            throw "Initialisation annulee par l'utilisateur pendant le prechargement AD."
        }
        if (-not $script:StartupWarmupDone) {
            Request-UiTaskStop -Id $taskId -Silent -Force
            $script:StartupWarmupError = "Le prechargement n'a pas rendu la main dans le delai de $timeout secondes."
            $script:StartupWarmupDone = $true
        }
        if ([string]::IsNullOrWhiteSpace([string]$script:StartupWarmupError) -and $null -ne $script:StartupWarmCache) { return }

        $lastError = [string]$script:StartupWarmupError
        Write-StartupTrace -Stage "Cache initial" -Status "WARN" -Detail "Tentative $attemptLabel : $lastError"
        if ($attempt -ge $configuredRetries) { break }

        Set-DomeniaStartupStage -Stage "Cache non pret  nouvelle tentative" -Detail "$lastError Nouvelle tentative automatique dans $retryDelayMs ms."
        $retryDeadline = (Get-Date).AddMilliseconds($retryDelayMs)
        while ((Get-Date) -lt $retryDeadline -and -not $script:StartupCancelled) { Invoke-DomeniaUiPump; Start-Sleep -Milliseconds 25 }
    }
    if ($script:StartupCancelled) { throw "Initialisation annulee par l'utilisateur." }
    throw "Cache initial AD non pret apres $configuredRetries tentative(s) : $lastError"
}

function Assert-DomeniaStartupReadiness {
    if (-not $script:AsyncEngineReady) { throw "Le moteur multithread ferme n'est pas pret." }
    if (-not [bool](Get-CfgValue "Cache" "RequireReadyBeforeMainWindow" $false)) {
        $script:StartupReady = $true
        return
    }
    if (-not $script:StartupWarmupDone) { throw "Le prechargement initial n'est pas termine." }
    if (-not [string]::IsNullOrWhiteSpace([string]$script:StartupWarmupError)) { throw "Prechargement initial en erreur : $($script:StartupWarmupError)" }
    if (-not $script:StartupWorkerReady -or $script:StartupWorkerThreadId -le 0) { throw "Le worker MTA de prechargement n'a pas ete valide." }
    if ($null -eq $script:StartupWarmCache) { throw "Le cache initial est absent." }
    if ([string]$script:StartupWarmCache.BaseDn -ine [string]$script:Conn.BaseDn) { throw "La base du cache initial ne correspond pas a la connexion courante." }
    if ([bool](Get-CfgValue "Cache" "WarmRootTree" $true) -and -not [bool]$script:StartupWarmCache.TreeReady) { throw "La racine de l'arborescence n'est pas prete." }
    if ([bool](Get-CfgValue "Cache" "WarmRootObjects" $true) -and -not [bool]$script:StartupWarmCache.ObjectsReady) { throw "La liste initiale des objets n'est pas prete." }
    $script:StartupReady = $true
    Write-StartupTrace -Stage "Barriere de disponibilite" -Status "OK" -Detail "Moteur MTA ferme pret ; worker=$script:StartupWorkerThreadId ; arbre=$(@($script:StartupWarmCache.TreeRows).Count) ; objets=$(@($script:StartupWarmCache.ObjectRows).Count)."
}

function Initialize-Window {
    if ([string]::IsNullOrWhiteSpace([string]$script:StartupCorrelation)) {
        $script:StartupCorrelation = [guid]::NewGuid().ToString("N")
    }
    $script:LoginAuthStarted = Get-Date
    $script:StartupCancelled = $false
    Initialize-DomeniaDataStore | Out-Null
    New-DomeniaStartupWindow
    try {
        Invoke-DomeniaStartupStage "Chargement interface WPF" { Load-XamlWindow } | Out-Null
        Invoke-DomeniaStartupStage "Protection erreurs interface" { Register-DomeniaDispatcherExceptionHandler } | Out-Null
        Invoke-DomeniaStartupStage "Moteur multithread" { Initialize-AsyncEngine; Initialize-DomeniaWorkerContextCache } | Out-Null
        Invoke-DomeniaStartupStage "Branchement des evenements" { Wire-Events } | Out-Null
        Invoke-DomeniaStartupStage "Gestion des comptes" { Initialize-DomeniaAccountPanel } | Out-Null
        # Optional local workspace: its failure cannot prevent the AD console from opening.
        try { Initialize-DomeniaSupportUi }
        catch {
            try { Stop-DomeniaSupportUi } catch { }
            Add-DomeniaUiLog -Area "Atelier" -Level "WARN" -Text ("Atelier indisponible : " + $_.Exception.Message)
        }
        Invoke-DomeniaStartupStage "Aides et ergonomie" { Apply-AutoTooltips; Apply-DomeniaGuiElementPolicy } | Out-Null
        Invoke-DomeniaStartupStage "Base autonome DOMENIA" {
            $dbBoot=[Diagnostics.Stopwatch]::StartNew()
            Initialize-DomeniaDatabase | Out-Null
            Set-DomeniaStartupStage -Stage "Base autonome DOMENIA" -Detail ("SQLite pret en " + $dbBoot.ElapsedMilliseconds + " ms")
            [void](Load-DomeniaIndexMetadata)
            Set-DomeniaStartupStage -Stage "Base autonome DOMENIA" -Detail ("Metadonnees : " + (Get-DomeniaDatabaseObjectCount) + " objet(s)")
            Load-UserMachineLinks
            $dbBoot.Stop()
            Set-DomeniaStartupStage -Stage "Base autonome DOMENIA" -Detail ("Liens charges : " + @($script:UserMachineLinks).Count + " ; total " + $dbBoot.ElapsedMilliseconds + " ms")
        } | Out-Null
        Invoke-DomeniaStartupStage "Etat initial de securite" {
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Preparation des controles..."
            Set-VisibleTabsForType ""
            if($script:Ctrl.ContainsKey("TxtBranchLimit")){$script:Ctrl["TxtBranchLimit"].Text=[string](Get-CfgValue "Browser" "DefaultLimit" 100)}
            $script:Ctrl["TxtGlobalLimit"].Text=[string](Get-CfgValue "Browser" "GlobalSearchLimit" 100)
            # Toujours demarrer en lecture seule. L administrateur peut lever le verrou explicitement dans le GUI.
            $script:ReadOnlyMode=$true
            if($script:Ctrl.ContainsKey("ChkReadOnlyMode")){$script:Ctrl["ChkReadOnlyMode"].IsChecked=$true}
            try{$script:Ctrl["LblMachineCredential"].Text="Operations poste : session Windows $script:ProcessIdentityDisplay. Le compte AD du login sert a l annuaire."}catch{}
            Assert-DomeniaReadWriteControlClassification
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Application des droits et du mode lecture seule..."
            Apply-CurrentPermissionUi
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Chargement de la presentation legere..."
            Initialize-DomeniaPresentation
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Presentation prete."
        } | Out-Null
        # D002/C2: after the presentation (which sets the session badge), the demonstration banner and the
        # write lock are applied; they stay for the whole session.
        if ([bool]$script:DemoMode) { Invoke-DomeniaStartupStage "Mode demonstration" { Set-DomeniaDemoShellPresentation } | Out-Null }
        Invoke-DomeniaStartupStage "Prechargement cache AD" { Invoke-DomeniaStartupCacheWarmup } | Out-Null
        Invoke-DomeniaStartupStage "Preparation arbre AD" { Load-TreeRoot; Update-Dashboard } | Out-Null
        Invoke-DomeniaStartupStage "Barriere de disponibilite" { Assert-DomeniaStartupReadiness } | Out-Null
        # D020: Activated, Deactivated, StateChanged and the page selector drive the idle policy (C1).
        try { Initialize-DomeniaIdlePolicy -Window $script:Window } catch { Write-AppLog ("Politique de repos non initialisee : " + $_.Exception.Message) "WARN" }
        # D089: a voluntary Alt-Tab during the startup is respected: the main window then opens without taking the foreground.
        try { if (Test-DomeniaUserSwitchedAway) { $script:Window.ShowActivated = $false } } catch { }
        $script:Window.Add_Closing({param($s,$e)
            $writeJobStillAlive = $false
            try { $writeJobStillAlive = (@($script:AsyncJobs.Values | Where-Object { $null -ne $_ -and [bool]$_.IsWrite }).Count -gt 0) } catch { }
            if(-not [string]::IsNullOrWhiteSpace($script:ActiveWriteTaskId) -or $writeJobStillAlive){
                $e.Cancel=$true
                Show-InfoBox "Une ecriture AD est en cours de confirmation par le DC. La fenetre ne peut pas etre fermee tant que son etat est inconnu."
            }
        })
        $script:Window.Add_Closed({
            try{Save-DomeniaWindowGeometry}catch{}
            try{Save-DomeniaSettings -Immediate}catch{}
            try{[void](Flush-DomeniaIndex)}catch{}
            try{Stop-DomeniaAccountValidation}catch{}
            try{Dispose-AsyncEngine}catch{}
            try{Clear-DomeniaSecretClipboard -Silent}catch{}
            try{Clear-Secrets}catch{}
            try{$script:MachineCredential=$null}catch{}
            try{$script:Conn.Credential=$null}catch{}
            try{Stop-DomeniaLoginAuth}catch{}
        })
        $script:Window.Add_ContentRendered({
            try{
                if ([bool]$script:DemoMode) { Set-Status ("Prêt. " + (Get-DomeniaDemoBannerText) + ".") "WARN" }
                else { Set-Status "Pret. Connexion validee, mode lecture seule actif." }
                Write-AppLog "Pret. Base=$($script:Conn.BaseDn) Server=$($script:Conn.Server) AD=$($script:Conn.BindUser) WIN=$script:ProcessIdentity Demo=$([bool]$script:DemoMode)" "INFO"
                Update-Dashboard
            }catch{Write-AppLog "ContentRendered : $($_.Exception.ToString())" "ERROR"}
            # D089: one activation request at the switch from login to main window, logged, never repeated.
            try { [void](Request-DomeniaWindowActivation -Window $script:Window -Trigger 'LoginToMain') } catch { }
            try { [void](Update-DomeniaIdlePolicy) } catch { }
            # Tout ce qui peut ouvrir une fenetre attend que la principale
            # soit peinte et que le fil graphique soit libre. Sinon la boite
            # n a pas de proprietaire et se cache derriere l ecran de
            # demarrage, qui reste au premier plan.
            try{
                [void]$script:Window.Dispatcher.BeginInvoke(
                    [System.Windows.Threading.DispatcherPriority]::ApplicationIdle,
                    [Action]{
                        try { [void](Load-DomeniaIndexMetadata); Update-DomeniaIndexStats } catch { }
                        try { Request-DomeniaIndexAutoRefresh } catch { }
                        try { Request-DomeniaIndexFirstBuild } catch { }
                        try { [void](Set-DomeniaControlText -Name "LblParkStatus" -Text "Etat du parc charge a la demande.") } catch { }
                        try { Request-DomeniaParkSweepAtStartup } catch { }
                        try { Add-DomeniaUiLog -Area "Demarrage" -Text "Politique V10.22 : aucune operation longue AD/reseau n'est lancee automatiquement ; recherche globale verifie toujours LDAP ; comptes editables sans reset." } catch { }
                    })
            }catch{Write-AppLog "Amorcage differe de l index impossible : $($_.Exception.Message)" "WARN"}
        })
        if (-not $script:StartupReady) { throw "La fenetre principale ne peut pas etre affichee : barriere de disponibilite non validee." }
        Write-StartupTrace -Stage "Initialisation" -Status "OK" -Detail "Fenetre principale prete ; moteur asynchrone valide et cache initial facultatif"
    }
    catch {
        Write-StartupTrace -Stage "Initialisation" -Status "ERROR" -Detail $_.Exception.ToString()
        throw
    }
    finally { Close-DomeniaStartupWindow }
}



# =====================================================================
# Domenia 1.0
# Authentification courte et bornee dans un runspace MTA interne.
# Le login effectue un bind LDAP reel, lit RootDSE et valide la base detectee
# dans un runspace borne afin que le thread WPF ne soit jamais bloque.
# =====================================================================
$script:DomeniaBuild = "Domenia 1.0 RC1.11.0"
$script:FastLoginUi = $null
$script:FastLoginState = $null
$script:FastLoginTimer = $null
$script:FastLoginLogPath = ""
$script:FastLoginMode = "Standard"

function Get-DomeniaFastLoginLogPath {
    try { Initialize-DomeniaDataStore | Out-Null } catch { }
    if ([string]::IsNullOrWhiteSpace([string]$script:FastLoginLogPath)) {
        $base = if (-not [string]::IsNullOrWhiteSpace([string]$script:DataDir)) { [string]$script:DataDir } elseif (-not [string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)) { Join-Path $env:LOCALAPPDATA "DOMENIA" } else { [string]$script:RootDir }
        $logs = Join-Path $base "Logs"
        try { if (-not (Test-Path -LiteralPath $logs -PathType Container)) { [void](New-Item -ItemType Directory -Path $logs -Force) } } catch { }
        $script:FastLoginLogPath = Join-Path $logs "Domenia-login.log"
    }
    return [string]$script:FastLoginLogPath
}

function Write-DomeniaFastLoginLog {
    param(
        [string]$Stage,
        [string]$Status = "INFO",
        [string]$Detail = "",
        [long]$DurationMs = 0
    )
    $Detail = Protect-DomeniaLogText $Detail
    try {
        $path = Get-DomeniaFastLoginLogPath
        $clean = (($Detail + "") -replace "[\r\n\t]+", " ").Trim()
        $line = "{0}`tPID={1}`tTID={2}`tBUILD={3}`t{4}`t{5}`t{6}`t{7}{8}" -f `
            (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), `
            $PID, `
            [System.Threading.Thread]::CurrentThread.ManagedThreadId, `
            $script:DomeniaBuild, `
            $Stage, `
            $Status, `
            $DurationMs, `
            $clean, `
            [Environment]::NewLine
        [System.IO.File]::AppendAllText($path, $line, (New-Object System.Text.UTF8Encoding($false)))
    }
    catch { }
    try { Write-StartupTrace -Stage "Login/$Stage" -Status $Status -Detail $Detail -DurationMs $DurationMs } catch { }
}

function New-DomeniaFastLoginSession {
    param(
        [string]$Login,
        [string]$Password,
        [string]$Domain,
        [string]$Netbios,
        [string]$ConfiguredBase,
        [string]$ConfiguredServer,
        [int]$TimeoutSeconds = 20,
        [switch]$UseCurrentCredentials,
        [switch]$Demo
    )

    $overallTimeout = [Math]::Max(8,[Math]::Min(45,$TimeoutSeconds))
    $perServerTimeout = [Math]::Max(2,[Math]::Min(10,[int](Get-CfgValue "Auth" "PerServerTimeoutSeconds" 6)))
    $maxServers = [Math]::Max(1,[Math]::Min(8,[int](Get-CfgValue "Auth" "MaxServerCandidates" 4)))
    $credential = $null
    if ($Demo) {
        # D002: no SecureString, no PSCredential: the demonstration request carries only the identity.
        $demoRequest = [pscustomobject]@{
            Login = [string]$Login; Credential = $null; PasswordLength = 0; UseCurrentCredentials = $false
            DemoOnly = $true; DemoIdentity = [string]$Login
            Domain = "demo.invalid"; Netbios = "DEMO"; ConfiguredBase = "DC=demo,DC=invalid"; ConfiguredServer = ""
            OverallTimeoutSeconds = $overallTimeout; PerServerTimeoutSeconds = $perServerTimeout; MaxServers = 1
        }
        return [pscustomobject]@{
            Id = [guid]::NewGuid().ToString("N"); Request = $demoRequest; Progress = $null; PowerShell = $null; Runspace = $null; AsyncResult = $null
            StartedAt = Get-Date; Deadline = (Get-Date).AddSeconds($overallTimeout + 3); LastProgressSequence = -1; LastHeartbeat = -1
            UseCurrentCredentials = $false; EndInvoked = $false; Cleaned = $false; CancelRequested = $false
            CleanupRetryAt = [datetime]::MinValue; CleanupGiveUpAt = [datetime]::MinValue
        }
    }
    if (-not $UseCurrentCredentials) {
        $secure = New-Object System.Security.SecureString
        foreach ($character in ([string]$Password).ToCharArray()) { $secure.AppendChar($character) }
        $secure.MakeReadOnly()
        $credential = New-Object System.Management.Automation.PSCredential -ArgumentList @([string]$Login,$secure)
    }

    $request = [pscustomobject]@{
        Login = if ($UseCurrentCredentials) { "" } else { [string]$Login }
        Credential = $credential
        PasswordLength = if ($UseCurrentCredentials) { 0 } else { ([string]$Password).Length }
        UseCurrentCredentials = [bool]$UseCurrentCredentials
        Domain = [string]$Domain
        Netbios = [string]$Netbios
        ConfiguredBase = [string]$ConfiguredBase
        ConfiguredServer = [string]$ConfiguredServer
        OverallTimeoutSeconds = $overallTimeout
        PerServerTimeoutSeconds = $perServerTimeout
        MaxServers = $maxServers
    }

    return [pscustomobject]@{
        Id = [guid]::NewGuid().ToString("N")
        Request = $request
        Progress = $null
        PowerShell = $null
        Runspace = $null
        AsyncResult = $null
        StartedAt = Get-Date
        Deadline = (Get-Date).AddSeconds($overallTimeout + 3)
        LastProgressSequence = -1
        LastHeartbeat = -1
        UseCurrentCredentials = [bool]$UseCurrentCredentials
        EndInvoked = $false
        Cleaned = $false
        CancelRequested = $false
        CleanupRetryAt = [datetime]::MinValue
        CleanupGiveUpAt = [datetime]::MinValue
    }
}

function Start-DomeniaFastLoginWorker {
    param([Parameter(Mandatory=$true)]$Session)
    $worker = Start-DomeniaLoginAuthRunspace -Request $Session.Request
    $Session.Progress = $worker.Progress
    $Session.PowerShell = $worker.PowerShell
    $Session.Runspace = $worker.Runspace
    $Session.AsyncResult = $worker.AsyncResult
    $Session.StartedAt = $worker.StartedAt
    $Session.EndInvoked = $false
    $Session.Cleaned = $false
    $authMode = if ([bool]$Session.UseCurrentCredentials) { "Windows" } else { "Explicit" }
    Write-DomeniaFastLoginLog -Stage "AUTH_STARTED" -Status "OK" -Detail "Mode=$authMode Runspace=MTA Processus=$PID"
    return $Session
}

function Stop-DomeniaFastLoginWorker {
    param($Session,[switch]$Kill,[switch]$KeepDiagnostics)
    if ($null -eq $Session) { return }
    try {
        if ($Kill) { Write-DomeniaFastLoginLog -Stage "AUTH_CANCEL" -Status "WARN" -Detail "Annulation asynchrone du runspace interne." }
        Stop-DomeniaLoginAuthRunspace -Session $Session -Terminate:$Kill
    }
    catch { Write-DomeniaFastLoginLog -Stage "AUTH_CANCEL" -Status "ERROR" -Detail $_.Exception.Message }
    try { if ($null -ne $Session.Request) { $Session.Request.Credential = $null } } catch { }
}

function Set-DomeniaFastLoginBusy {
    param([bool]$Busy)
    $ui = $script:FastLoginUi
    if ($null -eq $ui) { return }
    foreach ($name in @("Login","Password","PasswordVisible","Reveal","Remember","Connect")) {
        try { $ui[$name].IsEnabled = -not $Busy } catch { }
    }
    try {
        $allowWindowsSession = [bool](Get-CfgValue "Auth" "AllowWindowsSession" $true)
        $windowsIdentity = Get-DomeniaProcessWindowsIdentity
        $ui.Windows.IsEnabled = ((-not $Busy) -and $allowWindowsSession -and -not [string]::IsNullOrWhiteSpace($windowsIdentity))
    }
    catch { }
    if ([bool]$script:DemoMode) {
        # D002: in demonstration no password can be typed and no Windows session is offered, busy or not.
        foreach ($name in @("Password","PasswordVisible","Reveal","Remember","Windows")) {
            try { $ui[$name].IsEnabled = $false } catch { }
        }
    }
    # Standard view keeps the same outer dimensions throughout a validation attempt.
    # Debug view deliberately keeps its existing diagnostic presentation.
    if ($ui.Window -is [Windows.Window] -and $null -ne $ui.Window.FindName('PanelSplash')) {
        if ($Busy -and $ui.Window.IsLoaded) {
            $height = $ui.Window.ActualHeight
            $ui.Window.SizeToContent = [Windows.SizeToContent]::Manual
            $ui.Window.Height = [Math]::Min($height,$ui.Window.MaxHeight)
        }
        elseif (-not $Busy) {
            $ui.Window.SizeToContent = [Windows.SizeToContent]::Height
            $ui.Window.Height = [double]::NaN
        }
    }
    try { $ui.Cancel.Content = if ($Busy) { "Arreter" } else { "Annuler" } } catch { }
    try { $ui.Progress.Visibility = if ($Busy) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } } catch { }
}

function Add-DomeniaFastLoginDetail {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text) -or $null -eq $script:FastLoginUi) { return }
    try {
        $script:FastLoginUi.Technical.AppendText("[$((Get-Date).ToString('HH:mm:ss.fff'))] $Text`r`n")
        $script:FastLoginUi.Technical.ScrollToEnd()
    }
    catch { }
}

function Reset-DomeniaFastLoginAttempt {
    param([switch]$Kill,[switch]$KeepDiagnostics)
    try { if ($null -ne $script:FastLoginTimer) { $script:FastLoginTimer.Stop() } } catch { }
    $script:FastLoginTimer = $null
    if ($null -ne $script:FastLoginState -and $null -ne $script:FastLoginState.Session) {
        Stop-DomeniaFastLoginWorker -Session $script:FastLoginState.Session -Kill:$Kill -KeepDiagnostics:$KeepDiagnostics
    }
    if ($null -ne $script:FastLoginState) {
        $script:FastLoginState.Session = $null
        $script:FastLoginState.Password = ""
    }
    Set-DomeniaFastLoginBusy $false
}

function Complete-DomeniaFastLoginSuccess {
    param($Result,$Credential)
    $state = $script:FastLoginState
    $ui = $script:FastLoginUi
    if ($null -eq $state -or $null -eq $ui) { return }

    # D002/C2: a demonstration result is accepted only in demonstration mode, and the reverse.
    $isDemo = ($null -ne $Result.PSObject.Properties["AuthMethod"] -and [string]$Result.AuthMethod -ceq 'Demo.InMemory')
    if ($isDemo -ne [bool]$script:DemoMode) { throw 'Mode demonstration incoherent : connexion refusee.' }
    if ($isDemo) {
        $script:Conn.Connected = $true
        $script:Conn.AuthMode = 'Demo'
        $script:Conn.UseCredential = $false
        $script:Conn.Credential = $null
        $script:Conn.User = [string]$Result.BindUser
        $script:Conn.BindUser = [string]$Result.BindUser
        $script:Conn.Domain = [string]$Result.Domain
        $script:Conn.Netbios = [string]$Result.Netbios
        $script:Conn.BaseDn = [string]$Result.BaseDn
        $script:Conn.Server = [string]$Result.Server
        $script:Conn.RootPath = [string]$Result.RootPath
        $script:Conn.LastError = ""
        $script:DirectoryCredentialFaulted = $false
        $script:DirectoryCredentialFaultMessage = ""
        $script:ActualDeniedCapabilities = @{}
        $script:ActualSecretDeniedDn = ""
        try { if ($null -ne $script:DomeniaProviderState) { Reset-DomeniaProviderState -State $script:DomeniaProviderState } } catch { }
        # Nothing is remembered in HKCU in demonstration (no Save-AppConfig).
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Success")
        $ui.Error.Text = "Identité de démonstration acceptée — aucune connexion AD."
        $ui.Stage.Text = "Démonstration prête en $([Math]::Round(([long]$Result.DurationMs / 1000),2)) s."
        Write-DomeniaFastLoginLog -Stage "LOGIN_OK" -Status "OK" -Detail "Compte=$($Result.BindUser) Mode=Demo Base=$($Result.BaseDn)" -DurationMs ([long]$Result.DurationMs)
        $state.LoginOk = $true
        $state.Password = ""
        Set-DomeniaSurfaceResult $ui.Window $true
        return
    }

    $isWindows = [bool]$state.UseCurrentCredentials
    if ($null -ne $Result.PSObject.Properties["AuthMode"] -and [string]$Result.AuthMode -eq "Windows") { $isWindows = $true }
    $script:Conn.Connected = $true
    $script:Conn.AuthMode = if ($isWindows) { "Windows" } else { "Explicit" }
    $script:Conn.UseCredential = -not $isWindows
    $script:Conn.User = if ($isWindows) { [string]$Result.BindUser } else { [string]$state.Login }
    $script:Conn.BindUser = [string]$Result.BindUser

    # Conserver le mot de passe uniquement en SecureString, mais reconstruire le
    # PSCredential avec l'identite QUI A REELLEMENT REUSSI le bind de validation.
    # Sans cela, le login peut reussir avec CNAMTS\user puis les workers recevoir
    # encore le PSCredential "user" d'origine et echouer immediatement sur FindAll.
    if ($isWindows) {
        $script:Conn.Credential = $null
    }
    else {
        if ($null -eq $Credential) { throw "Credential AD explicite absent apres validation." }
        $validatedBindUser = ([string]$Result.BindUser).Trim()
        if ([string]::IsNullOrWhiteSpace($validatedBindUser)) { $validatedBindUser = ([string]$Credential.UserName).Trim() }
        if ([string]$Credential.UserName -ieq $validatedBindUser) {
            $script:Conn.Credential = $Credential
        }
        else {
            $script:Conn.Credential = New-Object System.Management.Automation.PSCredential -ArgumentList @($validatedBindUser,$Credential.Password)
        }
    }
    # Un login valide rearme explicitement le coupe-circuit AD, meme si le moteur
    # asynchrone etait deja initialise dans ce processus.
    $script:DirectoryCredentialFaulted = $false
    $script:DirectoryCredentialFaultMessage = ""
    # D018: an explicit reconnection is the change of account that lifts the per-resource refusals.
    try { if ($null -ne $script:DomeniaProviderState) { Reset-DomeniaProviderState -State $script:DomeniaProviderState } } catch { }
    $script:Conn.Domain = [string]$Result.Domain
    $script:Conn.Netbios = [string]$Result.Netbios
    $script:Conn.BaseDn = [string]$Result.BaseDn
    $script:Conn.Server = [string]$Result.Server
    $script:Conn.RootPath = [string]$Result.RootPath
    $script:Conn.LastError = ""
    $script:ActualDeniedCapabilities = @{}
    $script:ActualSecretDeniedDn = ""

    if (-not $isWindows) {
        $script:Config.Auth.RememberLogin = [bool]$ui.Remember.IsChecked
        $script:Config.Auth.LastLogin = if ([bool]$ui.Remember.IsChecked) { [string]$state.Login } else { "" }
        Save-AppConfig
    }

    $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Success")
    $ui.Error.Text = if ($isWindows) { "Session Windows validee." } else { "Compte valide." }
    $ui.Stage.Text = "Connexion terminee en $([Math]::Round(([long]$Result.DurationMs / 1000),2)) s."
    $authMethod = if ($null -ne $Result.PSObject.Properties["AuthMethod"]) { [string]$Result.AuthMethod } else { "LDAP" }
    Add-DomeniaFastLoginDetail "Compte valide : $($Result.BindUser) ; mode=$($script:Conn.AuthMode) ; methode=$authMethod ; serveur=$($Result.Server) ; base=$($Result.BaseDn)."
    Write-DomeniaFastLoginLog -Stage "LOGIN_OK" -Status "OK" -Detail "Compte=$($Result.BindUser) Mode=$($script:Conn.AuthMode) Serveur=$($Result.Server) Base=$($Result.BaseDn)" -DurationMs ([long]$Result.DurationMs)

    if (-not $isWindows -and $null -eq $script:Conn.Credential) {
        throw "Le credential de la session AD n a pas ete conserve en memoire. Connexion annulee pour eviter une interface inutilisable."
    }
    $state.LoginOk = $true
    try { $ui.Password.Password = "" } catch { }
    try { $ui.PasswordVisible.Text = "" } catch { }
    $state.Password = ""
    Set-DomeniaSurfaceResult $ui.Window $true
}

function Convert-DomeniaLoginFailureMessage {
    param([AllowNull()][string]$Message,[AllowNull()][string]$Category="")
    $m=([string]$Message).Trim()
    $c=([string]$Category).Trim()
    if ($c -eq 'Internal' -or $m -match '(?i)NullArray|Indexation impossible dans un tableau Null|Cannot index into a null array|DOMENIA_AUTH_(ENTRY|PROPERTIES|NATIVE)_NULL') {
        return 'Erreur interne pendant la connexion. Consulte le diagnostic.'
    }
    if ($c -eq 'Metadata') { return 'Lecture des informations AD incomplete. Consulte le diagnostic.' }
    if ($c -eq 'AccessDenied') { return 'Acces refuse par AD. Consulte le diagnostic.' }
    if ($c -in @('AccountRestriction','Authentication')) { return $m }
    if($m -match "(?i)((?:\bdata\s+52e\b)|\b(?:0x)?8007052e\b|logon failure|unknown user name or bad password|user name or password is incorrect|username or password is incorrect|nom d.?utilisateur.*mot de passe.*incorrect|identifiant.*mot de passe.*incorrect|mot de passe.*incorrect|invalid credentials|credentials.*invalid)") {
        return "Identifiant ou mot de passe incorrect."
    }
    if($m -match "(?i)((?:\bdata\s+775\b)|\b(?:0x)?80070775\b|account.*locked|compte.*verrouill)") {
        return "Ce compte est verrouille."
    }
    if($m -match "(?i)((?:\bdata\s+533\b)|\b(?:0x)?80070533\b|account.*disabled|compte.*desactiv|compte.*desactiv)") {
        return "Ce compte est desactive."
    }
    if($m -match "(?i)((?:\bdata\s+532\b)|\b(?:0x)?80070532\b|password.*expired|mot de passe.*expir)") {
        return "Le mot de passe de ce compte a expire."
    }
    if($c -eq "Credentials" -and -not [string]::IsNullOrWhiteSpace($m)) {
        return $m
    }
    if([string]::IsNullOrWhiteSpace($m)){ return "Echec de validation du compte." }
    return $m
}

function Get-DomeniaLoginFailureHint {
    param([AllowNull()][string]$Category='', [AllowNull()][string]$Message='')
    if ($Category -eq 'Internal' -or $Message -match '(?i)Erreur interne|NullArray|tableau Null|null array') {
        return 'Ce defaut ne prouve pas un mauvais mot de passe. Ouvre le journal.'
    }
    if ($Category -eq 'Metadata') { return 'La lecture du domaine ou de la base a echoue. Ouvre le journal.' }
    if ($Category -eq 'AccessDenied') { return 'Verifie le contexte, les droits du compte et les restrictions. Details dans le journal.' }
    if ($Message -eq 'Identifiant ou mot de passe incorrect.') { return 'Verifie les identifiants avant tout nouvel essai.' }
    if ($Category -eq 'Credentials') { return 'Compte refuse : lis le motif avant de refaire un essai.' }
    if ($Category -eq 'AccountRestriction') { return 'Lis la restriction indiquee avant tout nouvel essai. Ne multiplie pas les tentatives.' }
    if ($Category -eq 'Authentication') { return 'Le bind a echoue sans cause identifiee. Copie le diagnostic natif avant tout nouvel essai.' }
    if ($Category -eq 'Input') { return 'Complete les informations demandees.' }
    if ($Category -eq 'Timeout' -or $Category -eq 'DomainUnavailable') { return 'Verifie le reseau, le DNS ou le VPN. Details dans le journal.' }
    return 'Ouvre le journal de connexion pour identifier l etape en echec.'
}

function Update-DomeniaFastLoginAttempt {
    $state = $script:FastLoginState
    $ui = $script:FastLoginUi
    if ($null -eq $state -or $null -eq $state.Session -or $null -eq $ui) { return }
    $session = $state.Session

    try {
        $elapsed = [int]((Get-Date) - $session.StartedAt).TotalSeconds
        $sequence = -1
        try { $sequence = [int]$session.Progress["Sequence"] } catch { }
        if ($sequence -ne [int]$session.LastProgressSequence) {
            $session.LastProgressSequence = $sequence
            $stage = ""
            $detail = ""
            try { $stage = [string]$session.Progress["Stage"] } catch { }
            try { $detail = [string]$session.Progress["Detail"] } catch { }
            if (-not [string]::IsNullOrWhiteSpace($stage) -or -not [string]::IsNullOrWhiteSpace($detail)) {
                $signature = "$stage|$detail"
                $ui.Stage.Text = "$stage  $detail  ${elapsed}s"
                Add-DomeniaFastLoginDetail "$stage : $detail"
                Write-DomeniaFastLoginLog -Stage "PROGRESS" -Detail $signature
            }
        }
        else {
            $ui.Stage.Text = "Validation Active Directory en memoire  ${elapsed}s"
        }

        if ($elapsed -ne [int]$session.LastHeartbeat) {
            $session.LastHeartbeat = $elapsed
            Write-DomeniaFastLoginLog -Stage "HEARTBEAT" -Detail "Elapsed=${elapsed}s Runspace=MTA Processus=$PID"
        }

        $completed = $false
        try { $completed = [bool]$session.AsyncResult.IsCompleted } catch { $completed = $true }
        if (-not $completed -and (Get-Date) -lt $session.Deadline) { return }
        if (-not $completed) {
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = "Delai depasse. La validation a ete arretee sans bloquer l interface."
            $ui.Stage.Text = "Verifie le reseau, le VPN, le DNS ou le journal de connexion."
            Write-DomeniaFastLoginLog -Stage "TIMEOUT" -Status "ERROR" -Detail "Runspace MTA interne ; delai depasse."
            Reset-DomeniaFastLoginAttempt -Kill
            return
        }

        try { if ($null -ne $script:FastLoginTimer) { $script:FastLoginTimer.Stop() } } catch { }
        $script:FastLoginTimer = $null
        Write-DomeniaFastLoginLog -Stage "AUTH_COMPLETED" -Detail "Runspace MTA termine."

        $result = $null
        try { $result = Read-DomeniaAuthRunspaceResult -Session $session }
        catch {
            $detail = [string]$_.Exception.Message
            $friendly = Convert-DomeniaLoginFailureMessage -Message $detail
            Write-DomeniaFastLoginLog -Stage "NO_RESULT" -Status "ERROR" -Detail $detail
            Add-DomeniaFastLoginDetail $detail
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = $friendly
            $ui.Stage.Text = Get-DomeniaLoginFailureHint -Message $friendly
            $state.Session = $null
            Complete-DomeniaLoginAuthRunspaceCleanup -Session $session
            Set-DomeniaFastLoginBusy $false
            return
        }

        $validatedCredential = if ([bool]$session.UseCurrentCredentials) { $null } else { $session.Request.Credential }
        $state.Session = $null
        Complete-DomeniaLoginAuthRunspaceCleanup -Session $session

        if ($null -eq $result -or -not [bool]$result.Success) {
            $rawMessage = if ($null -ne $result -and -not [string]::IsNullOrWhiteSpace([string]$result.Error)) { [string]$result.Error } else { "Echec de validation du compte." }
            $errorCategory = ""
            try { $errorCategory = [string]$result.ErrorCategory } catch { }
            $message = Convert-DomeniaLoginFailureMessage -Message $rawMessage -Category $errorCategory
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = $message
            $ui.Stage.Text = Get-DomeniaLoginFailureHint -Category $errorCategory -Message $message
            # Keep the technical cause in the log, not only the shortened UI message.
            Add-DomeniaFastLoginDetail $rawMessage
            if ($null -ne $result) {
                $diagnosticProperty = $result.PSObject.Properties['Diagnostic']
                if ($null -ne $diagnosticProperty -and $null -ne $diagnosticProperty.Value) {
                    $d = $diagnosticProperty.Value
                    $diagnosticText = 'Category={0}; Stage={1}; ErrorId={2}; Type={3}; HResult={4}; WorkerLine={5}; CredentialAttempted={6}; Stack={7}; Server={8}; BindIdentity={9}; NativeMessage={10}; ExtendedCode={11}; ExtendedMessage={12}; LdapCode={13}' -f $errorCategory,$d.Stage,$d.ErrorId,$d.ExceptionType,$d.HResult,$d.WorkerLine,$d.CredentialAttempted,$d.Stack,$d.Server,$d.BindIdentity,$d.NativeMessage,$d.ExtendedCode,$d.ExtendedMessage,$d.LdapCode
                    Add-DomeniaFastLoginDetail $diagnosticText
                    Write-DomeniaFastLoginLog -Stage "LOGIN_DIAGNOSTIC" -Status "ERROR" -Detail $diagnosticText
                }
            }
            Write-DomeniaFastLoginLog -Stage "LOGIN_ERROR" -Status "ERROR" -Detail $rawMessage -DurationMs $(if($null -ne $result){[long]$result.DurationMs}else{0})
            Set-DomeniaFastLoginBusy $false
            return
        }

        Complete-DomeniaFastLoginSuccess -Result $result -Credential $validatedCredential
        $validatedCredential = $null
    }
    catch {
        $detail = $_.Exception.ToString()
        $friendly = Convert-DomeniaLoginFailureMessage -Message $detail
        Write-DomeniaFastLoginLog -Stage "MONITOR_ERROR" -Status "ERROR" -Detail $detail
        Add-DomeniaFastLoginDetail $detail
        try {
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            if($friendly -eq "Identifiant ou mot de passe incorrect.") {
                $ui.Error.Text = $friendly
                $ui.Stage.Text = "Corrige l identifiant ou le mot de passe."
            }
            else {
                $ui.Error.Text = "Erreur du moniteur de connexion : $($_.Exception.Message)"
                $ui.Stage.Text = "Le GUI reste actif. Consulte Domenia-login.log."
            }
        }
        catch { }
        Reset-DomeniaFastLoginAttempt -Kill
    }
}

function Test-DomeniaComputerAccountIdentity {
    param([AllowNull()][string]$Identity)

    $value = ([string]$Identity).Trim()
    if ([string]::IsNullOrWhiteSpace($value)) { return $false }

    $account = $value
    if ($account.Contains([string][char]92)) { $account = $account.Split([char]92)[-1] }
    if ($account.Contains("@")) { $account = $account.Split("@")[0] }

    return $account.EndsWith([string][char]36)
}

function Get-DomeniaProcessWindowsIdentity {
    $identity = ""
    try { $identity = [string][System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { }
    if ([string]::IsNullOrWhiteSpace($identity)) {
        try { $identity = "$env:USERDOMAIN\$env:USERNAME" } catch { }
    }

    # Un EXE demarre par SYSTEM peut s'executer sous DOMAIN\POSTE$.
    # Ce compte ordinateur ne doit jamais etre presente comme un login utilisateur.
    if (Test-DomeniaComputerAccountIdentity -Identity $identity) { return "" }
    if ($identity -match '^(?i:NT AUTHORITY|BUILTIN)\\') { return "" }
    try {
        if ($identity.Contains([string][char]92)) {
            $identityDomain = $identity.Split([char]92)[0]
            if (-not [string]::IsNullOrWhiteSpace([string]$env:COMPUTERNAME) -and $identityDomain -ieq [string]$env:COMPUTERNAME) { return "" }
        }
    }
    catch { }
    return $identity.Trim()
}

function Start-DomeniaFastLoginAttempt {
    param([switch]$UseCurrentCredentials)

    $ui = $script:FastLoginUi
    $state = $script:FastLoginState
    if ($null -eq $ui -or $null -eq $state -or $null -ne $state.Session) { return }

    if ([bool]$script:DemoMode) {
        # D002/C2: demonstration identity only. No password is read, no domain discovery, no LDAP bind:
        # the same session, worker, timer and completion as production, with a request marked DemoOnly.
        if ($UseCurrentCredentials) { return }
        $demoLogin = ([string]$ui.Login.Text).Trim()
        Write-DomeniaFastLoginLog -Stage "CLICK" -Detail "Compte=$demoLogin Mode=Demo"
        if (-not (Test-DomeniaDemoIdentity $demoLogin)) {
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = "Identité de démonstration attendue (DEMO\nom)."
            return
        }
        $state.Login = $demoLogin
        $state.Password = ""
        $state.LoginOk = $false
        $state.UseCurrentCredentials = $false
        $ui.Technical.Clear()
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Muted")
        $ui.Error.Text = "Vérification de l'identité de démonstration, sans connexion AD."
        $ui.Stage.Text = "Démonstration : annuaire fictif en mémoire."
        Set-DomeniaFastLoginBusy $true
        try {
            $session = New-DomeniaFastLoginSession -Login $demoLogin -Password "" -TimeoutSeconds 8 -Demo
            $state.Session = Start-DomeniaFastLoginWorker -Session $session
            $script:FastLoginTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:FastLoginTimer.Interval = [TimeSpan]::FromMilliseconds(200)
            $script:FastLoginTimer.Add_Tick({ Update-DomeniaFastLoginAttempt })
            $script:FastLoginTimer.Start()
            Write-DomeniaFastLoginLog -Stage "TIMER_STARTED" -Detail "Interval=200ms Mode=Demo"
        }
        catch {
            Write-DomeniaFastLoginLog -Stage "START_ERROR" -Status "ERROR" -Detail $_.Exception.ToString()
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = "Impossible de demarrer la demonstration : $($_.Exception.Message)"
            Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics
        }
        return
    }

    $login = if ($UseCurrentCredentials) {
        Get-DomeniaProcessWindowsIdentity
    }
    else {
        ([string]$ui.Login.Text).Trim()
    }
    $password = if ($UseCurrentCredentials) { "" } elseif ($state.Reveal) { [string]$ui.PasswordVisible.Text } else { [string]$ui.Password.Password }
    $modeLabel = if ($UseCurrentCredentials) { "Windows" } else { "Explicit" }
    Write-DomeniaFastLoginLog -Stage "CLICK" -Detail "Compte=$login Mode=$modeLabel"
    Add-DomeniaFastLoginDetail "Demande de connexion. Mode=$modeLabel Build=$($script:DomeniaBuild)."

    if (-not $UseCurrentCredentials -and [string]::IsNullOrWhiteSpace($login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Identifiant manquant."
        return
    }
    if (-not $UseCurrentCredentials -and [string]::IsNullOrWhiteSpace($password)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Mot de passe manquant."
        return
    }
    if (-not $UseCurrentCredentials -and (Test-DomeniaComputerAccountIdentity -Identity $login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Ce compte correspond a un objet ordinateur Active Directory et ne peut pas servir de login interactif."
        $ui.Stage.Text = "Saisis un compte utilisateur administrateur."
        return
    }
    if ($UseCurrentCredentials -and [string]::IsNullOrWhiteSpace($login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "La session Windows courante nest pas un compte utilisateur de domaine."
        $ui.Stage.Text = "Lapplication semble etre lancee sous SYSTEM, un compte local ou un compte ordinateur."
        return
    }

    $autoDiscover = [bool](Get-CfgValue "Conf" "AutoDiscover" $true)
    $domain = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "DOMAINE" "") }
    $netbios = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "NETBIOS" "") }
    $baseDn = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "SearchBase" "") }
    if (-not [string]::IsNullOrWhiteSpace($SearchBase)) { $baseDn = $SearchBase }
    if (-not $autoDiscover -and [string]::IsNullOrWhiteSpace($baseDn)) { $baseDn = Convert-DomainToDn $domain }
    $serverValue = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "Server" "") }
    if (-not [string]::IsNullOrWhiteSpace($Server)) { $serverValue = $Server }
    $timeout = [Math]::Max(8,[Math]::Min(45,[int](Get-CfgValue "Auth" "LoginTimeoutSeconds" 30)))

    $state.Login = $login
    $state.Password = ""
    $state.LoginOk = $false
    $state.UseCurrentCredentials = [bool]$UseCurrentCredentials
    $ui.Technical.Clear()
    $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Muted")
    $ui.Error.Text = if ($UseCurrentCredentials) { "Verification de la session Windows courante." } else { "Verification du compte administrateur." }
    $ui.Stage.Text = "Demarrage du controle Active Directory..."
    Set-DomeniaFastLoginBusy $true

    try {
        Write-DomeniaFastLoginLog -Stage "SESSION_CREATE" -Detail "Mode=$modeLabel Domaine=$domain Base=$baseDn Serveur=$serverValue Timeout=${timeout}s"
        $session = New-DomeniaFastLoginSession -Login $login -Password $password -Domain $domain -Netbios $netbios -ConfiguredBase $baseDn -ConfiguredServer $serverValue -TimeoutSeconds $timeout -UseCurrentCredentials:$UseCurrentCredentials
        $state.Session = Start-DomeniaFastLoginWorker -Session $session
        $state.Password = ""
        $password = ""
        try { $ui.Password.Password = ""; $ui.PasswordVisible.Text = "" } catch { }
        Add-DomeniaFastLoginDetail "Validation lancee dans un runspace MTA interne. Aucun processus enfant et aucun fichier de mot de passe ne sont utilises."

        $script:FastLoginTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:FastLoginTimer.Interval = [TimeSpan]::FromMilliseconds(200)
        $script:FastLoginTimer.Add_Tick({ Update-DomeniaFastLoginAttempt })
        $script:FastLoginTimer.Start()
        Write-DomeniaFastLoginLog -Stage "TIMER_STARTED" -Detail "Interval=200ms IsEnabled=$($script:FastLoginTimer.IsEnabled)"
    }
    catch {
        $detail = $_.Exception.ToString()
        Write-DomeniaFastLoginLog -Stage "START_ERROR" -Status "ERROR" -Detail $detail
        Add-DomeniaFastLoginDetail $detail
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Impossible de demarrer la validation : $($_.Exception.Message)"
        $ui.Stage.Text = "Consulte Domenia-login.log."
        Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics
    }
}

function Toggle-DomeniaFastLoginPassword {
    $ui = $script:FastLoginUi
    $state = $script:FastLoginState
    if ($null -eq $ui -or $null -eq $state) { return }
    if ($state.Reveal) {
        $ui.Password.Password = [string]$ui.PasswordVisible.Text
        $ui.PasswordVisible.Text = ""
        $ui.PasswordVisible.Visibility = [System.Windows.Visibility]::Collapsed
        $ui.Password.Visibility = [System.Windows.Visibility]::Visible
        $ui.Reveal.Content = "👁"
        try { $ui.Reveal.ToolTip = "Afficher le mot de passe." } catch { }
        $state.Reveal = $false
        $ui.Password.Focus() | Out-Null
    }
    else {
        $ui.PasswordVisible.Text = [string]$ui.Password.Password
        $ui.Password.Visibility = [System.Windows.Visibility]::Collapsed
        $ui.PasswordVisible.Visibility = [System.Windows.Visibility]::Visible
        $ui.Reveal.Content = "🙈"
        try { $ui.Reveal.ToolTip = "Masquer le mot de passe." } catch { }
        $state.Reveal = $true
        $ui.PasswordVisible.Focus() | Out-Null
    }
}

function Get-DomeniaLoginWindowMode {
    $script:LoginWindowModeSource = "Valeur integree"

    # 1) Marqueur d urgence : sa presence force le mode Debug.
    $flagPath = Join-Path $script:RootDir "Domenia.login.debug"
    try {
        if (Test-Path -LiteralPath $flagPath -PathType Leaf) {
            $script:LoginWindowModeSource = $flagPath
            return "Debug"
        }
    }
    catch { }

    # 2) Fichier operateur simple : Standard ou Debug sur une ligne.
    # Les formes LoginMode=Debug et LoginWindowMode=Debug sont aussi admises.
    $modeCfgPath = Join-Path $script:RootDir "Domenia.login-mode.cfg"
    try {
        if (Test-Path -LiteralPath $modeCfgPath -PathType Leaf) {
            foreach ($line in @(Get-Content -LiteralPath $modeCfgPath -Encoding UTF8 -ErrorAction Stop)) {
                $candidate = ([string]$line).Trim()
                if ([string]::IsNullOrWhiteSpace($candidate) -or $candidate.StartsWith("#") -or $candidate.StartsWith(";")) { continue }
                if ($candidate -match '(?i)^(?:LoginMode|LoginWindowMode)\s*=\s*(.+)$') { $candidate = [string]$Matches[1] }
                $candidate = $candidate.Trim().Trim('"').Trim("'")
                $script:LoginWindowModeSource = $modeCfgPath
                $normalizedCfg = $candidate.ToLowerInvariant()
                if (@("debug","diagnostic","diag","verbose","detail","detailed","true","1","on","oui") -contains $normalizedCfg) { return "Debug" }
                if (@("standard","normal","production","prod","false","0","off","non") -contains $normalizedCfg) { return "Standard" }
                try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Valeur '$candidate' inconnue dans $modeCfgPath. Repli securise sur Standard." } catch { }
                $script:LoginWindowModeSource = "$modeCfgPath (valeur invalide)"
                return "Standard"
            }
        }
    }
    catch {
        try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Lecture impossible de $modeCfgPath : $($_.Exception.Message). Repli sur Domenia.config.json." } catch { }
    }

    # 3) Configuration JSON existante.
    $rawMode = [string](Get-CfgValue "Auth" "LoginWindowMode" "Standard")
    $script:LoginWindowModeSource = if (Test-Path -LiteralPath $script:CfgPath -PathType Leaf) { "$($script:CfgPath) / Auth.LoginWindowMode" } else { "Valeur integree Auth.LoginWindowMode" }
    $normalized = ($rawMode + "").Trim().ToLowerInvariant()
    if (@("debug","diagnostic","diag","verbose","detail","detailed","true","1","on","oui") -contains $normalized) { return "Debug" }
    if (@("standard","normal","production","prod","false","0","off","non","") -contains $normalized) { return "Standard" }

    try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Valeur '$rawMode' inconnue dans Auth.LoginWindowMode. Repli securise sur Standard." } catch { }
    $script:LoginWindowModeSource = "$($script:LoginWindowModeSource) (valeur invalide)"
    return "Standard"
}

